@publish(data.IMPORTED_PREV_DSA_MATCH_KEYS.schema, cells=data.IMPORTED_PREV_DSA_MATCH_KEYS.cells)
def imported_prev_dsa_match_keys(*, imported_prev_dsa_investment_weo_codes: data.Series[str | None], imported_country_code: int | str, imported_prev_dsa_weo_codes: data.Series[str | int | float | bool | None], imported_selected_vintage_dates: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Compute concatenated PREV_DSA INDEX/MATCH row keys of the form country.WEO.vintage.A.

    Build bounded lookup keys for the previous DSA row catalog from country, WEO code, and vintage selections.

    Args:
        imported_prev_dsa_investment_weo_codes: Series of nullable WEO codes for investment-related indicators, keyed by parameter names such as 2024.NGDP_R_PCH.
        imported_country_code: Scalar country code, either integer or string, that is prefixed to every generated match key.
        imported_prev_dsa_weo_codes: Series of nullable WEO codes for non-investment DSA parameters, keyed by parameter names such as 2024.NGDPD.
        imported_selected_vintage_dates: Series of nullable vintage date selectors keyed by vintage labels, including the latest vintage and five years ago.

    Returns:
        data.Series[str | int | float | bool | None]: Concatenated country.WEO.vintage.A match keys for each required PREV_DSA match key index.
    """
    data.IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES.schema.validate(imported_prev_dsa_investment_weo_codes)
    def formula(parameter: str) -> str | int | float | bool | None:
        PARAMETER_TO_IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES_INDICATOR = {'2024.NGDP_R_PCH': 'NGDP_R_PCH', '2024.NFIG_R_GDP': 'NFIG_R_GDP', '2024.NFIP_R_GDP': 'NFIP_R_GDP'}
        if parameter in ('2024.NGDP_R_PCH', '2024.NFIG_R_GDP', '2024.NFIP_R_GDP'):
            return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_investment_weo_codes[PARAMETER_TO_IMPORTED_PREV_DSA_INVESTMENT_WEO_CODES_INDICATOR[parameter]]), '.'), imported_selected_vintage_dates['The latest vintage']), '.A'), 'str')
        elif parameter in ('2024.NGDPD', '2024.D_PPG_GDP', '2024.NGDP', '2024.DU_GDP'):
            return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_weo_codes[parameter]), '.'), imported_selected_vintage_dates['The latest vintage']), '.A'), 'str')
        return as_measure(xl_concat(xl_concat(xl_concat(xl_concat(xl_concat(imported_country_code, '.'), imported_prev_dsa_weo_codes[parameter]), '.'), imported_selected_vintage_dates['5 years ago']), '.A'), 'str')

    return data.IMPORTED_PREV_DSA_MATCH_KEYS.collect(evaluate(formula, data.IMPORTED_PREV_DSA_MATCH_KEYS.required))

@publish(data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.schema, cells=data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.cells)
def imported_prev_dsa_history_year_headers(*, realism1_external_year_headers: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Build year headers for imported previous DSA history columns.

    Provide the year axis for historical PREV_DSA INDEX/MATCH columns on Imported data.

    Args:
        realism1_external_year_headers: A data.Series of int, str, or None supplying the Realism 1 external year headers used as the anchor for resolving imported previous DSA history year labels.

    Returns:
        A data.Series of int, str, or None containing the imported previous DSA history year headers.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(realism1_external_year_headers[time_period], 'int')
        elif time_period <= 2023:
            return as_measure(xl_sub(imported_prev_dsa_history_year_headers[time_period + 1], 1), 'int')
        return as_measure(xl_add(imported_prev_dsa_history_year_headers[time_period - 1], 1), 'int')

    imported_prev_dsa_history_year_headers = CoordinateReader('imported_prev_dsa_history_year_headers', data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.required, formula)
    return data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.collect((coord, imported_prev_dsa_history_year_headers[coord]) for coord in data.IMPORTED_PREV_DSA_HISTORY_YEAR_HEADERS.required)

@publish(data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.schema, cells=data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.cells)
def imported_prev_dsa_investment_year_headers(*, realism3_contribution_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute imported previous-DSA investment year headers from Realism 3 contribution years.

    Derives the imported PREV_DSA investment year header series by aliasing Realism 3 investment-growth contribution years along the required coordinate axis.

    Args:
        realism3_contribution_years: Series over catalog coordinates containing Realism 3 investment-growth contribution years as int, str, or None; these values alias the Realism 3 header years used by the PREV_DSA INDEX/MATCH logic.

    Returns:
        data.Series[int | str | None] of imported previous-DSA investment year headers aligned to the required coordinate axis; empty overflow W59:AA59 is represented as BLANK_RANGES.
    """
    def formula(time_period: int) -> int | str | None:
        return as_measure(realism3_contribution_years[time_period], 'int')

    return data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.collect(evaluate(formula, data.IMPORTED_PREV_DSA_INVESTMENT_YEAR_HEADERS.required))

