    def dsa_ext_exports_usd_millions_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3' and time_period == 2025:
            return as_measure(xl_mul(macro_debt_exports_of_goods_services[time_period], xl_add(1, xl_add(xl_mul(xl_mul(leftover_official_transfers_gdp, c3_commodity_ext_ii_key_macroeconomic_ii_key_macroeconomic_assumptions_3), c3_commodity_ext_ii_key_macroeconomic_ii_key_macroeconomic_assumptions_4), xl_mul(xl_mul(leftover_official_transfers_gdp, c3_commodity_ext_ii_key_macroeconomic_ii_key_macroeconomic_assumptions), c3_commodity_ext_ii_key_macroeconomic_ii_key_macroeconomic_assumptions_2)))))
        elif scenario in ('B3', 'B6_mkt', 'B6_nonmkt') and time_period == 2024:
            return as_measure(xl_mul(xl_div(dsa_ext_exports[scenario, 2024], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))
        elif (scenario == 'B3' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044)) or (scenario == 'B6_mkt' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044)) or (scenario == 'B6_nonmkt' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044)) or (scenario == 'C3' and time_period >= 2031):
            return as_measure(xl_mul(dsa_ext_exports_usd_millions[scenario, time_period - 1], xl_add(1, xl_div(dsa_ext_growth_of_exports_of_g_s_us_dollar_terms_in_percent[scenario, time_period], 100))))
        return as_measure(xl_mul(xl_div(dsa_ext_exports[scenario, time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars[scenario, time_period]))

