@publish(data.DSA_EXT_PV_OF_ADDITIONAL_BORROWING.schema, cells=data.DSA_EXT_PV_OF_ADDITIONAL_BORROWING.cells)
def dsa_ext_pv_of_additional_borrowing(*, pv_stress_bounds_pv_of_new_forex_debt_in_usd: data.Series[float | str | None], pv_stress_pv_of_new_forex_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Assemble the PV of additional borrowing series for external DSA scenarios.

    Map each scenario and projection year to its source stress series so the A1 historical and B1–B6 bound/tailored paths drive the PV of new external borrowing output.

    Args:
        pv_stress_bounds_pv_of_new_forex_debt_in_usd: data.Series of bound-test PV of new forex debt in USD values, keyed by scenario and years, supplying the B1, B5, B6 market/non-market, and fallback bound paths.
        pv_stress_pv_of_new_forex_debt: data.Series of PV of new forex debt values, keyed by scenario and years, supplying the A1 historical-average and C3 commodity-price tailored-stress paths.

    Returns:
        data.Series of PV of additional borrowing (A1_historical_ext) values, keyed by scenario and years from row 8.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_pv_of_new_forex_debt['Key variables at historical average', time_period])
        elif scenario == 'B1' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 1: Real GDP Growth Shock', time_period])
        elif scenario == 'B5' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 5: Exchange Rate Shock', time_period])
        elif scenario == 'B6_mkt' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Market Access Countries', time_period])
        elif scenario == 'B6_nonmkt' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period])
        elif scenario == 'C3' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(pv_stress_pv_of_new_forex_debt['Tailored Stress Test 3. Commodity Price shock -External', time_period])
        elif scenario == 'B3':
            return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 2: Exports Shock', time_period])
        return as_measure(pv_stress_bounds_pv_of_new_forex_debt_in_usd['Bound Test 4: Other Flows Shock', time_period])

    return data.DSA_EXT_PV_OF_ADDITIONAL_BORROWING.collect(evaluate(formula, data.DSA_EXT_PV_OF_ADDITIONAL_BORROWING.required))

@publish(data.DSA_EXT_PV_PPG_STRESS.schema, cells=data.DSA_EXT_PV_PPG_STRESS.cells)
def dsa_ext_pv_ppg_stress(*, dsa_ext_pv_ppg_baseline: data.Series[float | str | None], dsa_ext_pv_of_additional_borrowing: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the A1_historical_ext PV PPG external debt stress path.

    Sum baseline external PPG PV debt and additional borrowing PV to produce the stress series.

    Args:
        dsa_ext_pv_ppg_baseline: Baseline external PPG PV debt path as a data.Series over scenario and projection-year coordinates, with float, string, or None cells.
        dsa_ext_pv_of_additional_borrowing: PV of additional external borrowing path as a data.Series over scenario and projection-year coordinates, with float, string, or None cells.

    Returns:
        A data.Series over scenario and projection-year coordinates containing the A1_historical_ext PV PPG stress path, with float, string, or None cells.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_ext_pv_ppg_baseline[scenario, time_period], dsa_ext_pv_of_additional_borrowing[scenario, time_period]))

    return data.DSA_EXT_PV_PPG_STRESS.collect(evaluate(formula, data.DSA_EXT_PV_PPG_STRESS.required))

