@publish(data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO.schema, cells=data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO.cells)
def dsa_ext_total_external_debt_service_to_exports_ratio(*, macro_debt_private_sector_short_term: data.Series[float | str | None], macro_debt_total_ext_debt_interest_due_include_interest: data.Series[float | str | None], macro_debt_total_external_amortization_due_include: data.Series[float | str | None], macro_debt_exports_of_goods_services: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the external-baseline total external debt service-to-exports ratio for the LIC-DSF template.

    Derive the Baseline - external debt-service-to-exports indicator from short-term private debt, external interest due, amortization due, and exports of goods and services.

    Args:
        macro_debt_private_sector_short_term: Keyword-only data.Series[float | str | None] of short-term private-sector external debt stock, aligned to scenario and projection-year catalog coordinates and read with a one-year lag in the numerator.
        macro_debt_total_ext_debt_interest_due_include_interest: Keyword-only data.Series[float | str | None] of total external debt interest due, including interest, indexed by scenario and time coordinate.
        macro_debt_total_external_amortization_due_include: Keyword-only data.Series[float | str | None] of total external amortization due, including principal repayments, indexed by scenario and time coordinate.
        macro_debt_exports_of_goods_services: Keyword-only data.Series[float | str | None] of exports of goods and services, providing the ratio denominator over scenario and time coordinate.

    Returns:
        A data.Series[float | str | None] of total external debt service-to-exports ratios keyed by scenario and years from row 8, using authored coordinate identities and yielding '...' where the numeric ratio is undefined.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_mul(xl_add(xl_add(macro_debt_private_sector_short_term[time_period - 1], macro_debt_total_ext_debt_interest_due_include_interest[time_period]), macro_debt_total_external_amortization_due_include[time_period]), 100), macro_debt_exports_of_goods_services[time_period]) if xl_bool(xl_isnumber(lambda: xl_div(xl_add(xl_add(macro_debt_private_sector_short_term[time_period - 1], macro_debt_total_ext_debt_interest_due_include_interest[time_period]), macro_debt_total_external_amortization_due_include[time_period]), macro_debt_exports_of_goods_services[time_period]))) else '...'))

    return data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO.collect(evaluate(formula, data.DSA_EXT_TOTAL_EXTERNAL_DEBT_SERVICE_TO_EXPORTS_RATIO.required))

@publish(data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.schema, cells=data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.cells)
def dsa_ext_government_revenues_excluding_grants_in_percent_of_gdp(*, macro_debt_revenues_pct_gdp: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Constructs the external DSA government revenues excluding grants (percent of GDP) series.

    Maps macro-debt revenue values into the internal DSA external revenue indicator by scenario and projection year.

    Args:
        macro_debt_revenues_pct_gdp: data.Series[float | str | None] of macro-debt revenues as a percent of GDP, keyed by scenario and year, used as the source values for the external DSA revenue indicator.

    Returns:
        data.Series[float | str | None] of government revenues excluding grants in percent of GDP (Baseline - external), keyed by scenario and years from row 8; nonnumeric source entries are represented as '...'.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((macro_debt_revenues_pct_gdp[time_period] if xl_bool(xl_isnumber(lambda: macro_debt_revenues_pct_gdp[time_period])) else '...'))

    return data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.collect(evaluate(formula, data.DSA_EXT_GOVERNMENT_REVENUES_EXCLUDING_GRANTS_IN_PERCENT_OF_GDP.required))

@dataclass(frozen=True, slots=True)
class ScanDsaPubPublicSectorDebt1Result:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_public_sector_debt_1: data.Series[float | str | None]
    dsa_pub_change_in_public_sector_debt: data.Series[float | str | None]
    dsa_pub_identified_debt_creating_flows: data.Series[float | str | None]
    dsa_pub_automatic_debt_dynamics: data.Series[float | str | None]
    dsa_pub_contribution_from_interest_rate_growth_differential: data.Series[float | str | None]
    dsa_pub_of_which_contribution_from_average_real_interest_rate: data.Series[float | str | None]
    dsa_pub_of_which_contribution_from_real_gdp_growth: data.Series[float | str | None]
    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent: data.Series[float | str | None]
    dsa_pub_average_real_interest_rate_in_percent: data.Series[float | str | None]
    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent: data.Series[float | str | None]
    dsa_pub_nominal_debt: data.Series[float | str | None]
    dsa_pub_total_public_domestic_debt: data.Series[float | str | None]

def scan_dsa_pub_public_sector_debt_1(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_primary_deficit: data.Series[float | str | None], dsa_pub_contribution_from_real_exchange_rate_depreciation: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_other_identified_debt_creating_flows: data.Series[float | str | None], dsa_pub_residual: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None], dsa_pub_domestic_debt: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None], macro_debt_total_public_debt_outstanding_year_end: data.Series[float | str | None], pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt: data.Series[float | str | None]) -> ScanDsaPubPublicSectorDebt1Result:
    """Evaluate the recurrence group `dsa_pub_public_sector_debt_1`, `dsa_pub_change_in_public_sector_debt`, `dsa_pub_identified_debt_creating_flows`, `dsa_pub_automatic_debt_dynamics`, `dsa_pub_contribution_from_interest_rate_growth_differential`, `dsa_pub_of_which_contribution_from_average_real_interest_rate`, `dsa_pub_of_which_contribution_from_real_gdp_growth`, `dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_average_real_interest_rate_in_percent`, `dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent`, `dsa_pub_nominal_debt`, `dsa_pub_total_public_domestic_debt` and publish complete tensors."""
    def dsa_pub_public_sector_debt_1_formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_total_public_debt_outstanding_year_end[time_period]), xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_total_public_debt_outstanding_year_end[time_period], xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])))) else '.'))
        return as_measure(xl_add(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_change_in_public_sector_debt[scenario, time_period]))

    dsa_pub_public_sector_debt_1 = CoordinateReader('dsa_pub_public_sector_debt_1', data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.required, dsa_pub_public_sector_debt_1_formula)
    def dsa_pub_change_in_public_sector_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_identified_debt_creating_flows[scenario, time_period], dsa_pub_residual[scenario, time_period]))

    dsa_pub_change_in_public_sector_debt = CoordinateReader('dsa_pub_change_in_public_sector_debt', data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required, dsa_pub_change_in_public_sector_debt_formula)
    def dsa_pub_identified_debt_creating_flows_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(dsa_pub_primary_deficit[scenario, time_period], dsa_pub_automatic_debt_dynamics[scenario, time_period]), dsa_pub_other_identified_debt_creating_flows[scenario, time_period]))

    dsa_pub_identified_debt_creating_flows = CoordinateReader('dsa_pub_identified_debt_creating_flows', data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required, dsa_pub_identified_debt_creating_flows_formula)
    def dsa_pub_automatic_debt_dynamics_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_contribution_from_interest_rate_growth_differential[scenario, time_period], dsa_pub_contribution_from_real_exchange_rate_depreciation[scenario, time_period]))

    dsa_pub_automatic_debt_dynamics = CoordinateReader('dsa_pub_automatic_debt_dynamics', data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.required, dsa_pub_automatic_debt_dynamics_formula)
    def dsa_pub_contribution_from_interest_rate_growth_differential_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(dsa_pub_of_which_contribution_from_average_real_interest_rate[scenario, time_period], dsa_pub_of_which_contribution_from_real_gdp_growth[scenario, time_period]))

    dsa_pub_contribution_from_interest_rate_growth_differential = CoordinateReader('dsa_pub_contribution_from_interest_rate_growth_differential', data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.required, dsa_pub_contribution_from_interest_rate_growth_differential_formula)
    def dsa_pub_of_which_contribution_from_average_real_interest_rate_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_div(dsa_pub_average_real_interest_rate_in_percent[scenario, time_period], 100), dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_denominator_1_g[scenario, time_period]))

    dsa_pub_of_which_contribution_from_average_real_interest_rate = CoordinateReader('dsa_pub_of_which_contribution_from_average_real_interest_rate', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.required, dsa_pub_of_which_contribution_from_average_real_interest_rate_formula)
    def dsa_pub_of_which_contribution_from_real_gdp_growth_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_neg(xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)), xl_div(dsa_pub_public_sector_debt_1[scenario, time_period - 1], dsa_pub_denominator_1_g[scenario, time_period])))

    dsa_pub_of_which_contribution_from_real_gdp_growth = CoordinateReader('dsa_pub_of_which_contribution_from_real_gdp_growth', data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required, dsa_pub_of_which_contribution_from_real_gdp_growth_formula)
    def dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(pv_resfin_pub_assumptions_average_interest_rate_on_domestic_debt[time_period], 100) if xl_bool(xl_eq(dsa_pub_total_public_domestic_debt[scenario, time_period - 1], 0)) else xl_mul(xl_div(dsa_pub_domestic_debt[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period - 1]), 100)))

    dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_average_real_interest_rate_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_mul(xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1]), dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period]), xl_mul(xl_sub(1, xl_div(dsa_pub_of_which_external_debt[scenario, time_period - 1], dsa_pub_public_sector_debt_1[scenario, time_period - 1])), dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[scenario, time_period])))

    dsa_pub_average_real_interest_rate_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.required, dsa_pub_average_real_interest_rate_in_percent_formula)
    def dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[scenario, time_period], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent = CoordinateReader('dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent', data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent_formula)
    def dsa_pub_nominal_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_public_sector_debt_1[scenario, time_period], 100), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    dsa_pub_nominal_debt = CoordinateReader('dsa_pub_nominal_debt', data.DSA_PUB_NOMINAL_DEBT.required, dsa_pub_nominal_debt_formula)
    def dsa_pub_total_public_domestic_debt_formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(dsa_pub_nominal_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, time_period]))

    dsa_pub_total_public_domestic_debt = CoordinateReader('dsa_pub_total_public_domestic_debt', data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required, dsa_pub_total_public_domestic_debt_formula)
    return ScanDsaPubPublicSectorDebt1Result(
        dsa_pub_public_sector_debt_1=data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.collect((coord, dsa_pub_public_sector_debt_1[coord]) for coord in data.DSA_PUB_PUBLIC_SECTOR_DEBT_1.required),
        dsa_pub_change_in_public_sector_debt=data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.collect((coord, dsa_pub_change_in_public_sector_debt[coord]) for coord in data.DSA_PUB_CHANGE_IN_PUBLIC_SECTOR_DEBT.required),
        dsa_pub_identified_debt_creating_flows=data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.collect((coord, dsa_pub_identified_debt_creating_flows[coord]) for coord in data.DSA_PUB_IDENTIFIED_DEBT_CREATING_FLOWS.required),
        dsa_pub_automatic_debt_dynamics=data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.collect((coord, dsa_pub_automatic_debt_dynamics[coord]) for coord in data.DSA_PUB_AUTOMATIC_DEBT_DYNAMICS.required),
        dsa_pub_contribution_from_interest_rate_growth_differential=data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.collect((coord, dsa_pub_contribution_from_interest_rate_growth_differential[coord]) for coord in data.DSA_PUB_CONTRIBUTION_FROM_INTEREST_RATE_GROWTH_DIFFERENTIAL.required),
        dsa_pub_of_which_contribution_from_average_real_interest_rate=data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.collect((coord, dsa_pub_of_which_contribution_from_average_real_interest_rate[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_AVERAGE_REAL_INTEREST_RATE.required),
        dsa_pub_of_which_contribution_from_real_gdp_growth=data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.collect((coord, dsa_pub_of_which_contribution_from_real_gdp_growth[coord]) for coord in data.DSA_PUB_OF_WHICH_CONTRIBUTION_FROM_REAL_GDP_GROWTH.required),
        dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.collect((coord, dsa_pub_average_nominal_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required),
        dsa_pub_average_real_interest_rate_in_percent=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.collect((coord, dsa_pub_average_real_interest_rate_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_IN_PERCENT.required),
        dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.collect((coord, dsa_pub_average_real_interest_rate_on_domestic_debt_in_percent[coord]) for coord in data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_DOMESTIC_DEBT_IN_PERCENT.required),
        dsa_pub_nominal_debt=data.DSA_PUB_NOMINAL_DEBT.collect((coord, dsa_pub_nominal_debt[coord]) for coord in data.DSA_PUB_NOMINAL_DEBT.required),
        dsa_pub_total_public_domestic_debt=data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.collect((coord, dsa_pub_total_public_domestic_debt[coord]) for coord in data.DSA_PUB_TOTAL_PUBLIC_DOMESTIC_DEBT.required),
    )

@publish(data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.schema, cells=data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.cells)
def dsa_pub_of_which_external_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_external_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public external debt "of which" indicator as a percent of nominal GDP in local currency.

    Derive the LIC-DSF public external debt series (B1_GDP_pub) from total public external debt and nominal GDP for use in DSA chart data.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, a data.Series keyed by scenario and years from row 7; values may be float, str, or None.
        dsa_pub_total_public_external_debt: Total public external debt, a data.Series keyed by scenario and years from row 7; values may be float, str, or None.

    Returns:
        A data.Series of float, str, or None keyed by scenario and years from row 7, containing the "of which: external debt" share (B1_GDP_pub) as a percentage of nominal GDP in local currency.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_pub_total_public_external_debt[scenario, time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_EXTERNAL_DEBT.required))

@publish(data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.schema, cells=data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.cells)
def dsa_pub_pv_of_total_public_debt(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_total_public_domestic_debt: data.Series[float | str | None], dsa_pub_pv_of_public_sector_external_debt_end_of_period: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the present value of total public debt as a share of GDP across scenarios and years.

    Combines external and domestic public debt stocks and scales them by nominal GDP to yield the PV of total public debt-to-GDP ratio used in public DSA charts.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency, keyed by scenario and year, used as the denominator of the ratio.
        dsa_pub_total_public_domestic_debt: Total public domestic debt stock in local currency, keyed by scenario and year, summed with external debt in the numerator.
        dsa_pub_pv_of_public_sector_external_debt_end_of_period: Present value of public-sector external debt at end of period in local currency, keyed by scenario and year, summed with domestic debt in the numerator.

    Returns:
        Series of PV of total public debt as a percentage of GDP, keyed by scenario and year; the A1 historical scenario floors negative ratios at zero.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure((0 if xl_bool(xl_lt(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100), 0)) else xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100)))
        return as_measure(xl_mul(xl_div(xl_add(dsa_pub_pv_of_public_sector_external_debt_end_of_period[scenario, time_period], dsa_pub_total_public_domestic_debt[scenario, time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100))

    return data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.collect(evaluate(formula, data.DSA_PUB_PV_OF_TOTAL_PUBLIC_DEBT.required))

@publish(data.DSA_PUB_PRIMARY_DEFICIT.schema, cells=data.DSA_PUB_PRIMARY_DEFICIT.cells)
def dsa_pub_primary_deficit(*, b6_combo_non_mkt_pub_gdp_shock_label: str, input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_pub_revenue_and_grants: data.Series[float | str | None], dsa_pub_primary_noninterest_expenditure: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: str | int | float | bool, dsa_pub_standard_test_pb_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: str | int | float | bool, a1_hist_pub_historical_statistics: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], leftover_primary_deficit: data.Series[float | str | None], leftover_revenue_gdp: data.Series[float | str | None], b2_pb_mkt_pub_i_baseline_medium_term_projections: int | str, b2_pb_nonmkt_pub_i_baseline_medium_term_projections: int | str) -> data.Series[float | str | None]:
    """Compute the public-sector primary deficit (B1_GDP_pub) paths for the baseline, historical-average (A1), and standard stress scenarios (B2/B6 market and non-market).

    Builds each scenario-year cell of the public primary-deficit series by subtracting revenue and grants from primary non-interest expenditure for ordinary years, while applying threshold-selected leftover-financing and shock-adjustment identities to the 2025–2026 transition years of the B2 and B6 scenarios and carrying the historical average forward for A1.

    Args:
        b6_combo_non_mkt_pub_gdp_shock_label: Text label identifying the GDP shock applied to the B6 combo non-market-access public scenario.
        input6_standard_size_threshold_option_historical_average_only: Option token for the historical-average-only standard size threshold rule, compared against the relevant test parameter to select the leftover-based projection branch.
        input6_standard_size_threshold_option_whichever_is_lower: Option token for the whichever-is-lower standard size threshold rule, compared against the relevant test parameter to select the maximum of the leftover-based and baseline-plus-leftover branches.
        dsa_pub_revenue_and_grants: Revenue and grants for the public DSA, as a named-axis series over scenario and year catalog coordinates.
        dsa_pub_primary_noninterest_expenditure: Primary non-interest expenditure for the public DSA, as a named-axis series over scenario and year catalog coordinates.
        dsa_pub_standard_test_parameter: Standard test parameter for the public DSA, as a named-axis series over scenario and year coordinates holding the threshold-selection tokens.
        dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter: Scalar standard test parameter used for the B2 non-market-access public scenario's PB rule comparison.
        dsa_pub_standard_test_pb_rule: Scalar standard test PB rule token checked when choosing the 2025 branch of the B6 market-access public scenario.
        dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule: Scalar standard test PB rule token checked when choosing the 2025 branch of the B6 combo non-market-access public scenario.
        a1_hist_pub_historical_statistics: Historical statistics for the public DSA, as a named-axis series keyed by row label and statistic (for example, primary deficit by historical average).
        baseline_pub_primary_deficit: Baseline public primary deficit projections, as a named-axis series over year coordinates used as the fallback term in the stress identities.
        leftover_primary_deficit: Leftover public primary deficit, as a named-axis series over scenario and year coordinates providing the 2023 anchor and the per-year continuation term.
        leftover_revenue_gdp: Leftover revenue-to-GDP ratio, as a named-axis series over scenario coordinates providing the scaling factor applied to the leftover primary deficit in the B6 branches.
        b2_pb_mkt_pub_i_baseline_medium_term_projections: Medium-term projection multiplier for the B2 market-access public baseline, supplied as a scalar integer or string.
        b2_pb_nonmkt_pub_i_baseline_medium_term_projections: Medium-term projection multiplier for the B2 non-market-access public baseline, supplied as a scalar integer or string.

    Returns:
        data.Series[float | str | None]: the public-sector primary deficit (B1_GDP_pub) keyed by scenario and years from row 7, collected over every required scenario-year coordinate.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B2_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_mkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_mkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b2_pb_non_mkt_pub_standard_test_parameter, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'B2_nonmkt' and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b2_pb_nonmkt_pub_i_baseline_medium_term_projections, leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_max(xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])), xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_add(leftover_primary_deficit[scenario, 2023], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_pb_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(b6_combo_non_mkt_pub_gdp_shock_label, leftover_primary_deficit[scenario, time_period])))))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Primary deficit', 'Historical average'])
        elif scenario in ('B6_mkt', 'B6_nonmkt') and time_period == 2026:
            return as_measure((xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_primary_deficit[scenario, time_period - 1], xl_add(leftover_primary_deficit[scenario, time_period - 3], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1])))) else xl_add(baseline_pub_primary_deficit[time_period], xl_mul(leftover_revenue_gdp[scenario], leftover_primary_deficit[scenario, time_period - 1]))))
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_primary_deficit[scenario, time_period - 1])
        return as_measure(xl_sub(dsa_pub_primary_noninterest_expenditure[scenario, time_period], dsa_pub_revenue_and_grants[scenario, time_period]))

    dsa_pub_primary_deficit = CoordinateReader('dsa_pub_primary_deficit', data.DSA_PUB_PRIMARY_DEFICIT.required, formula)
    return data.DSA_PUB_PRIMARY_DEFICIT.collect((coord, dsa_pub_primary_deficit[coord]) for coord in data.DSA_PUB_PRIMARY_DEFICIT.required)

@publish(data.DSA_PUB_REVENUE_AND_GRANTS.schema, cells=data.DSA_PUB_REVENUE_AND_GRANTS.cells)
def dsa_pub_revenue_and_grants(*, dsa_pub_of_which_grants: data.Series[float | str | None], dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_revenue_grants: data.Series[float | str | None], baseline_pub_of_which_grants: data.Series[float | str | None], macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None], c3_commodity_pub_historical_statistics_key_variables_past_10: int | str) -> data.Series[float | str | None]:
    """Compute the LIC-DSF public revenue and grants series across scenarios and projection years.

    Assemble baseline public revenue and grants with scenario-specific grants, interest-rate, and C3 commodity adjustments into the branded public revenue-and-grants output series.

    Args:
        dsa_pub_of_which_grants: data.Series[float | str | None] of grants included in public revenue, keyed by scenario and projection year.
        dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None] of nominal GDP in local currency for the public DSA, keyed by scenario and projection year.
        baseline_pub_revenue_grants: data.Series[float | str | None] of baseline public revenue and grants over the projection-year axis.
        baseline_pub_of_which_grants: data.Series[float | str | None] of the baseline grants component of public revenue over the projection-year axis.
        macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None] of macro-debt public-sector revenues including grants over the projection-year axis.
        leftover_real_interest_rate: data.Series[float | str | None] of the scenario-specific leftover real interest rate over the projection-year axis.
        c3_commodity_pub_historical_statistics_key_variables_past_10: int | str scalar count or label for the C3 commodity public historical-statistics key variable measured over the past 10 periods.

    Returns:
        data.Series[float | str | None] branded as DSA_PUB_REVENUE_AND_GRANTS, containing public revenue and grants values or blanks for each scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3' and time_period == 2028:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2029:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and time_period == 2030:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), xl_div(xl_mul(leftover_real_interest_rate[scenario], xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2))))
        elif scenario == 'C3' and 2025 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]), leftover_real_interest_rate[scenario]))
        elif time_period == 2024:
            return as_measure((xl_div(xl_mul(100, macro_debt_public_sector_revenues_including_grants[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: xl_div(macro_debt_public_sector_revenues_including_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]))) else '.'))
        return as_measure(xl_add(xl_sub(baseline_pub_revenue_grants[time_period], baseline_pub_of_which_grants[time_period]), dsa_pub_of_which_grants[scenario, time_period]))

    return data.DSA_PUB_REVENUE_AND_GRANTS.collect(evaluate(formula, data.DSA_PUB_REVENUE_AND_GRANTS.required))

@publish(data.DSA_PUB_OF_WHICH_GRANTS.schema, cells=data.DSA_PUB_OF_WHICH_GRANTS.cells)
def dsa_pub_of_which_grants(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], macro_debt_public_sector_grants: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the "of which: grants" series (B1_GDP_pub) as public-sector grants divided by nominal GDP.

    Express public-sector grants as a percentage of nominal GDP in local currency, keyed by scenario and projection year.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency as a scenario- and year-keyed data.Series; supplies the denominator for the grants ratio and may contain float, str, or None entries.
        macro_debt_public_sector_grants: Public-sector grants as a year-keyed data.Series; supplies the numerator for the grants ratio and may contain float, str, or None entries.

    Returns:
        A data.Series[float | str | None] keyed by scenario and year for the "of which: grants" (B1_GDP_pub) series, containing grants-to-nominal-GDP percentages or "..." where the grants value is not numeric.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_mul(xl_div(macro_debt_public_sector_grants[time_period], dsa_pub_nominal_gdp_local_currency[scenario, time_period]), 100) if xl_bool(xl_isnumber(lambda: macro_debt_public_sector_grants[time_period])) else '...'))

    return data.DSA_PUB_OF_WHICH_GRANTS.collect(evaluate(formula, data.DSA_PUB_OF_WHICH_GRANTS.required))

@publish(data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.schema, cells=data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.cells)
def dsa_pub_primary_noninterest_expenditure(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_primary_noninterest_expenditure: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute DSA public primary noninterest expenditure.

    Derive the public primary noninterest expenditure series by rebasing baseline expenditure to the DSA public nominal GDP path in local currency.

    Args:
        dsa_pub_nominal_gdp_local_currency: DSA public nominal GDP in local currency as a data.Series[float | str | None] over scenario and projection-year coordinates; the B1 scenario is used for the C3 case.
        baseline_pub_primary_noninterest_expenditure: Baseline public primary noninterest expenditure as a data.Series[float | str | None] over projection years.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local currency as a data.Series[float | str | None] over projection years.

    Returns:
        A data.Series[float | str | None] of public primary noninterest expenditure, keyed by scenario and projection years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C3':
            return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency['B1', time_period]))
        return as_measure(xl_div(xl_mul(baseline_pub_primary_noninterest_expenditure[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.collect(evaluate(formula, data.DSA_PUB_PRIMARY_NONINTEREST_EXPENDITURE.required))

@publish(data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.schema, cells=data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.cells)
def dsa_pub_contribution_from_real_exchange_rate_depreciation(*, dsa_pub_of_which_external_debt: data.Series[float | str | None], dsa_pub_denominator_1_g: data.Series[float | str | None], dsa_pub_average_real_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public debt contribution from real exchange rate depreciation (B1_GDP_pub).

    Calculate the contribution to public debt dynamics from real exchange rate depreciation per the LIC-DSF template.

    Args:
        dsa_pub_of_which_external_debt: External debt series (previous period) used as the base for the depreciation contribution.
        dsa_pub_denominator_1_g: Denominator series (1 + g), where g is the nominal GDP growth rate, used to scale the contribution.
        dsa_pub_average_real_interest_rate_on_external_debt_in_percent: Average real interest rate on external debt, in percent, used in the interest adjustment factor.
        dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation: Real exchange rate depreciation, in percent, indicating depreciation when positive.

    Returns:
        A data.Series of contribution values (float, str, or None), keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation[scenario, time_period], 100), dsa_pub_of_which_external_debt[scenario, time_period - 1]), xl_add(1, xl_div(dsa_pub_average_real_interest_rate_on_external_debt_in_percent[scenario, time_period], 100))), dsa_pub_denominator_1_g[scenario, time_period]))

    return data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.collect(evaluate(formula, data.DSA_PUB_CONTRIBUTION_FROM_REAL_EXCHANGE_RATE_DEPRECIATION.required))

@publish(data.DSA_PUB_DENOMINATOR_1_G.schema, cells=data.DSA_PUB_DENOMINATOR_1_G.cells)
def dsa_pub_denominator_1_g(*, dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public-debt denominator as 1 plus real GDP growth.

    Derives the per-scenario, per-year denominator series used in public DSA ratio calculations from real GDP growth expressed in percent.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Real GDP growth in percent, provided as a named-axis data.Series[float | str | None] over scenario and year coordinates; numeric values are percent growth, while string or missing entries propagate through unchanged.

    Returns:
        A named-axis data.Series[float | str | None] keyed by scenario and year, where each numeric value is 1 plus the corresponding real GDP growth fraction (growth divided by 100), and string or blank inputs propagate as their original or missing values.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100)))

    return data.DSA_PUB_DENOMINATOR_1_G.collect(evaluate(formula, data.DSA_PUB_DENOMINATOR_1_G.required))

@publish(data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.schema, cells=data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.cells)
def dsa_pub_other_identified_debt_creating_flows(*, dsa_pub_privatization_receipts_negative: data.Series[float | str | None], dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: data.Series[float | str | None], dsa_pub_debt_relief_hipc_and_other: data.Series[float | str | None], dsa_pub_other_debt_creating_or_reducing_flow_please_specify: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Aggregate four other identified public debt-creating flow components into a scenario-year series.

    Compute the 'Other identified debt-creating flows (B1_GDP_pub)' line by summing the four residual public-debt flow components.

    Args:
        dsa_pub_privatization_receipts_negative: Series of privatization receipts (recorded as negative amounts) by scenario and projection year.
        dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization: Series of recognition of contingent liabilities (for example, bank recapitalization) by scenario and projection year.
        dsa_pub_debt_relief_hipc_and_other: Series of debt relief under HIPC and other initiatives by scenario and projection year.
        dsa_pub_other_debt_creating_or_reducing_flow_please_specify: Series of other debt-creating or reducing flows explicitly specified by the user, by scenario and projection year.

    Returns:
        data.Series[float | str | None] of the summed other identified debt-creating flows, indexed by scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sum((dsa_pub_privatization_receipts_negative[scenario, time_period], dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization[scenario, time_period], dsa_pub_debt_relief_hipc_and_other[scenario, time_period], dsa_pub_other_debt_creating_or_reducing_flow_please_specify[scenario, time_period])))

    return data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.DSA_PUB_OTHER_IDENTIFIED_DEBT_CREATING_FLOWS.required))

@publish(data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.schema, cells=data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.cells)
def dsa_pub_privatization_receipts_negative(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_privatization_receipts_negative: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute privatization receipts (negative) as a ratio-scaled series over scenario and year coordinates.

    Rescales baseline privatization receipts (negative) by the ratio of baseline to DSA nominal GDP in local currency, producing the public-debt input series.

    Args:
        dsa_pub_nominal_gdp_local_currency: Scenario- and year-keyed `data.Series[float | str | None]` of DSA public nominal GDP in local currency.
        baseline_pub_privatization_receipts_negative: Time-period-keyed `data.Series[float | str | None]` of baseline privatization receipts (negative) from `B1_GDP_pub`.
        baseline_pub_nominal_gdp_lc: Time-period-keyed `data.Series[float | str | None]` of baseline public nominal GDP in local currency.

    Returns:
        `data.Series[float | str | None]` of privatization receipts (negative) scaled by baseline-to-DSA nominal GDP, keyed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_privatization_receipts_negative[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.collect(evaluate(formula, data.DSA_PUB_PRIVATIZATION_RECEIPTS_NEGATIVE.required))

@publish(data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.schema, cells=data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.cells)
def dsa_pub_recognition_of_contingent_liabilities_e_g_bank_recapitalization(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_recognition_of_contingent_liab_e_g_bank: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public DSA recognition of contingent liabilities (e.g. bank recapitalization) as a share of nominal GDP.

    Scale baseline recognized contingent-liability amounts by the ratio of baseline to scenario nominal GDP in local currency so the result is expressed as a public-DSA GDP share.

    Args:
        dsa_pub_nominal_gdp_local_currency: Named-axis series of the public DSA scenario's nominal GDP in local currency, keyed by scenario and time period.
        baseline_pub_recognition_of_contingent_liab_e_g_bank: Named-axis series of baseline recognized contingent liabilities (e.g. bank recapitalization) in local currency, keyed by scenario and time period.
        baseline_pub_nominal_gdp_lc: Named-axis series of baseline nominal GDP in local currency, keyed by scenario and time period.

    Returns:
        Named-axis series of recognized contingent liabilities as a GDP share under the public DSA, keyed by scenario and time period, with baseline rows scaled against baseline GDP and other rows left as the raw ratio.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period])) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_recognition_of_contingent_liab_e_g_bank[time_period])) else 0))

    return data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.collect(evaluate(formula, data.DSA_PUB_RECOGNITION_OF_CONTINGENT_LIABILITIES_E_G_BANK_RECAPITALIZATION.required))

@publish(data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.schema, cells=data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.cells)
def dsa_pub_debt_relief_hipc_and_other(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_debt_relief_hipc_other: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute scenario-specific public debt relief (HIPC and other) as a share of GDP.

    Rebase baseline debt relief ratios from baseline GDP to the scenario's nominal GDP in local currency.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the scenario, a data.Series of floats, strings, or None keyed by scenario and time period.
        baseline_pub_debt_relief_hipc_other: Baseline public debt relief (HIPC and other) series, a data.Series of integers, strings, or None indexed by time period.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local currency series, a data.Series of floats, strings, or None indexed by time period.

    Returns:
        A data.Series of floats, strings, or None for the B1_GDP_pub debt relief (HIPC and other) series, keyed by scenario and projection year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_debt_relief_hipc_other[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.collect(evaluate(formula, data.DSA_PUB_DEBT_RELIEF_HIPC_AND_OTHER.required))

@publish(data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.schema, cells=data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.cells)
def dsa_pub_other_debt_creating_or_reducing_flow_please_specify(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], dsa_pub_old_new_scenario_total: float | str, baseline_pub_other_debt_creating_reducing_flow_please_specify: data.Series[int | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], c2_natdisaster_historical_statistics_key_variables_past_10: int | str) -> data.Series[float | str | None]:
    """Compute the public other debt creating or reducing flow series by scenario and year.

    Derives the specified 'other debt creating or reducing flow' from baseline flow and GDP data, applying scenario-specific adjustments such as natural-disaster inputs and old/new scenario totals.

    Args:
        dsa_pub_nominal_gdp_local_currency: dsa_pub_nominal_gdp_local_currency: A data series of nominal GDP in local currency for the public DSA, indexed by scenario and year.
        dsa_pub_old_new_scenario_total: dsa_pub_old_new_scenario_total: Scalar total for the old/new scenario adjustment, applied when the scenario is 'C1' and the year is 2025.
        baseline_pub_other_debt_creating_reducing_flow_please_specify: baseline_pub_other_debt_creating_reducing_flow_please_specify: Baseline series of other debt creating or reducing flow (please specify), indexed by year.
        baseline_pub_nominal_gdp_lc: baseline_pub_nominal_gdp_lc: Baseline nominal GDP in local currency, indexed by year.
        c2_natdisaster_historical_statistics_key_variables_past_10: c2_natdisaster_historical_statistics_key_variables_past_10: Scalar value from historical natural disaster statistics for the past 10 years, used for scenario 'C2'.

    Returns:
        A data.Series[float | str | None] of the computed 'other debt creating or reducing flow' by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'C1' and time_period == 2025:
            return as_measure(xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), dsa_pub_old_new_scenario_total))
        elif scenario == 'C2' and time_period == 2025:
            return as_measure((xl_add(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else xl_add(xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]), c2_natdisaster_historical_statistics_key_variables_past_10)))
        elif scenario == 'C1' and time_period >= 2026:
            return as_measure(xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))
        elif scenario in ('B1', 'B2_nonmkt', 'C3', 'A1'):
            return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else xl_div(xl_mul(0, baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period])))
        return as_measure((xl_div(xl_mul(baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]) if xl_bool(xl_isnumber(lambda: baseline_pub_other_debt_creating_reducing_flow_please_specify[time_period])) else 0))

    return data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.collect(evaluate(formula, data.DSA_PUB_OTHER_DEBT_CREATING_OR_REDUCING_FLOW_PLEASE_SPECIFY.required))

@publish(data.DSA_PUB_RESIDUAL.schema, cells=data.DSA_PUB_RESIDUAL.cells)
def dsa_pub_residual(*, dsa_pub_nominal_gdp_local_currency: data.Series[float | str | None], baseline_pub_residual: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the public DSA residual (B1_GDP_pub) from baseline residual and GDP scaling series.

    Derive the public residual financing path used in LIC-DSF public debt scenario and stress analysis.

    Args:
        dsa_pub_nominal_gdp_local_currency: Nominal GDP in local currency for the public DSA scenario, as a data.Series of float, str, or None keyed by scenario and projection year; supplies the scenario-specific denominator.
        baseline_pub_residual: Baseline public residual series, as a data.Series of float, str, or None keyed by projection year; supplies the residual numerator component.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local currency, as a data.Series of float, str, or None keyed by projection year; supplies the baseline scaling factor.

    Returns:
        data.Series[float | str | None] of public DSA residual values (B1_GDP_pub), keyed by scenario and projection years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(baseline_pub_residual[time_period], baseline_pub_nominal_gdp_lc[time_period]), dsa_pub_nominal_gdp_local_currency[scenario, time_period]))

    return data.DSA_PUB_RESIDUAL.collect(evaluate(formula, data.DSA_PUB_RESIDUAL.required))

@publish(data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.schema, cells=data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.cells)
def dsa_pub_nominal_gdp_local_currency(*, dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], macro_debt_gdp_current_prices_u_s_dollars: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute nominal GDP in local currency.

    Derive the public DSA nominal GDP path in local currency, anchored to the macro-debt level in 2024 and rolled forward with real growth and GDP-deflator inflation.

    Args:
        dsa_pub_real_gdp_growth_in_percent: Scenario-keyed series of real GDP growth rates in percent, indexed by scenario and projection year.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: Scenario-keyed series of GDP-deflator inflation rates in percent, indexed by scenario and projection year.
        macro_debt_gdp_current_prices_u_s_dollars: Scenario-keyed series of GDP at current prices in U.S. dollars, provided as the 2024 anchor level.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Scenario-keyed series of the exchange rate in national currency per U.S. dollar, used to convert the 2024 USD anchor.

    Returns:
        data.Series[float | str | None] of nominal GDP in local currency, keyed by scenario and years from row 7; 2024 equals USD GDP times the exchange rate, and later years compound the prior nominal value by real growth and inflation.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(macro_debt_gdp_current_prices_u_s_dollars[time_period], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))
        return as_measure(xl_mul(xl_mul(dsa_pub_nominal_gdp_local_currency[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_real_gdp_growth_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))))

    dsa_pub_nominal_gdp_local_currency = CoordinateReader('dsa_pub_nominal_gdp_local_currency', data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.required, formula)
    return data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.collect((coord, dsa_pub_nominal_gdp_local_currency[coord]) for coord in data.DSA_PUB_NOMINAL_GDP_LOCAL_CURRENCY.required)

@publish(data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.schema, cells=data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.cells)
def dsa_pub_real_gdp_growth_in_percent(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], input6_standard_size_threshold_option_historical_average_only: str, input6_standard_size_threshold_option_whichever_is_lower: str, dsa_ext_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_standard_test_parameter: data.Series[str | int | float | bool | None], dsa_pub_standard_test_gdp_growth_rule: str | int | float | bool, dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: str | int | float | bool, baseline_pub_real_gdp_growth: data.Series[float | str | None], leftover_real_gdp_growth: data.Series[float | str | None], b1_gdp_pub_key_macroeconomic_fiscal_assumptions: int | str, b6_combo_mkt_pub_i_baseline_medium_term_projections: float | str, b6_combo_nonmkt_pub_i_baseline_medium_term_projections: float | str, leftover_nominal_interest_rate: float | str) -> data.Series[float | str | None]:
    """Compute the public DSA real GDP growth path in percent, keyed by scenario and projection year.

    Derive the public-sector real GDP growth series that drives the public baseline and the B1, B6 market/non-market, C2, A1 and C3 standardized-test variants.

    Args:
        a1_hist_pub_historical_statistics: Historical statistics series over statistic-label and variant coordinates; supplies the A1 scenario's 2025 growth value from the 'Real GDP growth (in percent)' historical-average cell.
        input6_standard_size_threshold_option_historical_average_only: Input 6 threshold-option label selecting the 'historical average only' branch of the standardized size test.
        input6_standard_size_threshold_option_whichever_is_lower: Input 6 threshold-option label selecting the 'whichever is lower' branch, which takes the minimum of the historical-average and baseline-minus-adjusted paths.
        dsa_ext_real_gdp_growth_in_percent: External DSA real GDP growth series over scenario and year coordinates; the public C3 scenario copies its values through 2030.
        dsa_pub_standard_test_parameter: Per-scenario standard-test parameter series whose value selects which Input 6 threshold option applies to the B1 public scenario.
        dsa_pub_standard_test_gdp_growth_rule: Scalar rule selector compared against the Input 6 threshold options to choose the adjustment form for the public B6 market-financing standard test.
        dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule: Scalar rule selector compared against the Input 6 threshold options to choose the adjustment form for the public B6 non-market-financing standard test.
        baseline_pub_real_gdp_growth: Baseline public real GDP growth path over years; the default fallback for unhandled scenario/year cells and the reference level from which adjusted scenarios depart.
        leftover_real_gdp_growth: Residual real GDP growth series over scenario and year coordinates; its 2023 historical value and projected values are scaled by the scenario coefficients to adjust the B1 and B6 paths.
        b1_gdp_pub_key_macroeconomic_fiscal_assumptions: Scalar multiplier from the B1 key macroeconomic and fiscal assumptions, applied to the residual real GDP growth when adjusting the B1 scenario.
        b6_combo_mkt_pub_i_baseline_medium_term_projections: Scalar multiplier from the B6 combined market-financing public baseline medium-term projections, applied to the residual real GDP growth when adjusting the B6 market scenario.
        b6_combo_nonmkt_pub_i_baseline_medium_term_projections: Scalar multiplier from the B6 combined non-market-financing public baseline medium-term projections, applied to the residual real GDP growth when adjusting the B6 non-market scenario.
        leftover_nominal_interest_rate: Scalar residual nominal interest rate subtracted from the baseline growth level to set the C2 scenario's 2025 value.

    Returns:
        A typed data.Series[float | str | None] of real GDP growth in percent for the public DSA, keyed by scenario and year from row 7, where the opening years of the B1, B6 market, B6 non-market, C2, A1 and C3 scenarios follow their rule-driven adjustments (with A1 persisting the prior year from 2026) and any remaining cells fall back to the baseline path.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B1' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_parameter[scenario], input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B1' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b1_gdp_pub_key_macroeconomic_fiscal_assumptions, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_mkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_mkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure((xl_min(xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])), xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period]))) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_whichever_is_lower)) else (xl_sub(leftover_real_gdp_growth[scenario, 2023], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])) if xl_bool(xl_eq(dsa_pub_b6_combo_non_mkt_pub_standard_test_gdp_growth_rule, input6_standard_size_threshold_option_historical_average_only)) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period])))))
        elif scenario == 'B6_nonmkt' and time_period == 2026:
            return as_measure((xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])) if xl_bool(xl_eq(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1], xl_sub(leftover_real_gdp_growth[scenario, time_period - 3], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1])))) else xl_sub(baseline_pub_real_gdp_growth[time_period], xl_mul(b6_combo_nonmkt_pub_i_baseline_medium_term_projections, leftover_real_gdp_growth[scenario, time_period - 1]))))
        elif scenario == 'C2' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_real_gdp_growth[time_period], leftover_nominal_interest_rate))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Real GDP growth (in percent)', 'Historical average'])
        elif scenario == 'C3' and time_period <= 2030:
            return as_measure(dsa_ext_real_gdp_growth_in_percent[scenario, time_period])
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_real_gdp_growth_in_percent[scenario, time_period - 1])
        return as_measure(baseline_pub_real_gdp_growth[time_period])

    dsa_pub_real_gdp_growth_in_percent = CoordinateReader('dsa_pub_real_gdp_growth_in_percent', data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required, formula)
    return data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.collect((coord, dsa_pub_real_gdp_growth_in_percent[coord]) for coord in data.DSA_PUB_REAL_GDP_GROWTH_IN_PERCENT.required)

@publish(data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.schema, cells=data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.cells)
def dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent(*, dsa_pub_total_public_external_debt: data.Series[float | str | None], dsa_pub_external_debt: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the average nominal interest rate on external debt (in percent) from public external debt and exchange-rate series.

    Derive the B1_GDP_pub indicator for LIC-DSF external debt risk analysis.

    Args:
        dsa_pub_total_public_external_debt: Series of total public external debt amounts, indexed by scenario and year.
        dsa_pub_external_debt: Series of external debt amounts, indexed by scenario and year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Series of exchange rates (national currency per U.S. dollar) used as the prior-period conversion factor, indexed by year.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Series of exchange rates (national currency per U.S. dollar) used as the current-period conversion factor, indexed by year.

    Returns:
        A data.Series[float | str | None] of average nominal interest rates on external debt in percent, indexed by scenario and year.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_mul(xl_mul(xl_div(dsa_pub_external_debt[scenario, time_period], dsa_pub_total_public_external_debt[scenario, time_period - 1]), 100), macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_AVERAGE_NOMINAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required))

@publish(data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.schema, cells=data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.cells)
def dsa_pub_average_real_interest_rate_on_external_debt_in_percent(*, dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: data.Series[float | str | None], dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the average real interest rate on external debt, in percent.

    Deflate the average nominal external-debt interest rate by US GDP-deflator inflation to obtain the real rate.

    Args:
        dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent: Average nominal interest rate on external debt, in percent, as a data.Series[float | str | None] keyed by scenario and year.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: US inflation rate based on the GDP deflator, in percent, as a data.Series[float | str | None] keyed by scenario and year.

    Returns:
        Average real interest rate on external debt (B1_GDP_pub), in percent, as a data.Series[float | str | None] keyed by scenario and year from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure((xl_div(xl_sub(dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period], dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))) if xl_bool(xl_isnumber(lambda: dsa_pub_average_nominal_interest_rate_on_external_debt_in_percent[scenario, time_period])) else '...'))

    return data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_AVERAGE_REAL_INTEREST_RATE_ON_EXTERNAL_DEBT_IN_PERCENT.required))

@dataclass(frozen=True, slots=True)
class ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Complete named results of one recurrence group evaluation."""
    dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None]
    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc: data.Series[float | str | None]

def scan_dsa_pub_exchange_rate_lc_per_us_dollar(*, dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], baseline_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None]) -> ScanDsaPubExchangeRateLcPerUsDollarResult:
    """Evaluate the recurrence group `dsa_pub_exchange_rate_lc_per_us_dollar`, `dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc` and publish complete tensors."""
    def dsa_pub_exchange_rate_lc_per_us_dollar_formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B5' and time_period >= 2025:
            return as_measure(xl_div(1, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period]))
        elif scenario == 'A1':
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(baseline_pub_exchange_rate_lc_per_us_dollar[time_period])

    dsa_pub_exchange_rate_lc_per_us_dollar = CoordinateReader('dsa_pub_exchange_rate_lc_per_us_dollar', data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required, dsa_pub_exchange_rate_lc_per_us_dollar_formula)
    def dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_div(1, dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period]))
        return as_measure(xl_mul(dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[scenario, time_period - 1], xl_add(1, xl_div(dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period], 100))))

    dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc = CoordinateReader('dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc', data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.required, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc_formula)
    return ScanDsaPubExchangeRateLcPerUsDollarResult(
        dsa_pub_exchange_rate_lc_per_us_dollar=data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.collect((coord, dsa_pub_exchange_rate_lc_per_us_dollar[coord]) for coord in data.DSA_PUB_EXCHANGE_RATE_LC_PER_US_DOLLAR.required),
        dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc=data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.collect((coord, dsa_pub_b5_depreciation_pub_exchange_rate_us_dollar_per_lc[coord]) for coord in data.DSA_PUB_B5_DEPRECIATION_PUB_EXCHANGE_RATE_US_DOLLAR_PER_LC.required),
    )

@publish(data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.schema, cells=data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.cells)
def dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar(*, dsa_pub_exchange_rate_lc_per_us_dollar: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute nominal depreciation of the local currency as the percentage change in local currency per US dollar.

    Derive the public DSA B1_GDP_pub series from the exchange-rate path.

    Args:
        dsa_pub_exchange_rate_lc_per_us_dollar: Typed data.Series of exchange rates in local currency per US dollar, keyed by scenario and projection year, with scalar entries that may be float, str, or None.

    Returns:
        Typed data.Series[float | str | None] of nominal depreciation of the local currency (percentage change in LC per US dollar), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_sub(xl_div(dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period], dsa_pub_exchange_rate_lc_per_us_dollar[scenario, time_period - 1]), 1), 100))

    return data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.collect(evaluate(formula, data.DSA_PUB_NOMINAL_DEPRECIATION_OF_LOCAL_CURRENCY_PERCENTAGE_CHANGE_IN_LC_PER_DOLLAR.required))

@publish(data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.schema, cells=data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.cells)
def dsa_pub_real_exchange_rate_depreciation_in_percent_indicates_depreciation(*, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: data.Series[float | str | None], dsa_pub_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None], dsa_pub_us_inflation_rate_gdp_deflator_in_percent: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes real exchange rate depreciation (in percent, + indicates depreciation) from nominal depreciation and domestic and US GDP-deflator inflation.

    Derives the LIC-DSF real exchange rate depreciation series for the external debt sustainability analysis.

    Args:
        dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar: Scenario-keyed series over projection years of the nominal depreciation of the local currency, expressed as the percentage change in local currency per US dollar.
        dsa_pub_inflation_rate_gdp_deflator_in_percent: Scenario-keyed series over projection years of the domestic inflation rate measured by the GDP deflator, in percent.
        dsa_pub_us_inflation_rate_gdp_deflator_in_percent: Scenario-keyed series over projection years of the US inflation rate measured by the GDP deflator, in percent.

    Returns:
        A scenario-keyed series over projection years of real exchange rate depreciation in percent, where positive values indicate depreciation; entries are float values or str/None where the underlying cells are blank or non-numeric.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(xl_div(xl_mul(xl_add(100, dsa_pub_nominal_depreciation_of_local_currency_percentage_change_in_lc_per_dollar[scenario, time_period]), xl_add(1, xl_div(dsa_pub_us_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), xl_add(1, xl_div(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period], 100))), 100))

    return data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.collect(evaluate(formula, data.DSA_PUB_REAL_EXCHANGE_RATE_DEPRECIATION_IN_PERCENT_INDICATES_DEPRECIATION.required))

@publish(data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.schema, cells=data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.cells)
def dsa_pub_inflation_rate_gdp_deflator_in_percent(*, a1_hist_pub_historical_statistics: data.Series[float | str | None], dsa_ext_exports: data.Series[float | str | None], dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None], dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: float | str, baseline_pub_real_gdp_growth: data.Series[float | str | None], baseline_pub_inflation_rate_gdp_deflator_pct: data.Series[float | str | None], leftover_real_interest_rate: data.Series[float | str | None], b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: float | str, b6_combo_nonmkt_pub_in_billions_of_lc: float | str, c3_commodity_pub_historical_statistics_key_variables_past_10: int | str) -> data.Series[float | str | None]:
    """Compute the public DSA GDP-deflator inflation rate in percent by scenario and year.

    Derives scenario-specific inflation paths from baseline inflation and growth, exchange-rate, interest-rate, and commodity-price adjustments for the LIC-DSF public DSA.

    Args:
        a1_hist_pub_historical_statistics: data.Series[float | str | None] of historical public DSA statistics over named catalog coordinates, supplying historical averages such as GDP-deflator inflation for the A1 scenario.
        dsa_ext_exports: data.Series[float | str | None] of external exports keyed by scenario and year, used in the C3 commodity-price adjustment for the prior period.
        dsa_pub_real_gdp_growth_in_percent: data.Series[float | str | None] of public real GDP growth in percent keyed by scenario and year, used to derive the B1 inflation adjustment from growth shocks.
        dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None] of B5 depreciation in percent keyed by scenario and year, measuring the increase in the U.S. dollar value of the local currency for the B5 scenario.
        dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None] of nominal appreciation in percent keyed by scenario and year, measuring the increase in the U.S. dollar value of the local currency.
        dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent: data.Series[float | str | None] of B6 combo non-market nominal appreciation in percent keyed by scenario and year, measuring the increase in the U.S. dollar value of the local currency for the B6 non-market scenario.
        dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator: Scalar percentage decline in the GDP deflator from commodity prices for the C3 shock.
        baseline_pub_real_gdp_growth: data.Series[float | str | None] of baseline public real GDP growth keyed by year, providing the baseline growth path used in the B1 adjustment.
        baseline_pub_inflation_rate_gdp_deflator_pct: data.Series[float | str | None] of baseline public GDP-deflator inflation in percent keyed by year, providing the pre-shock inflation path.
        leftover_real_interest_rate: data.Series[float | str | None] of leftover real interest rate keyed by scenario, used to scale growth and depreciation adjustments in the B1 and B5 scenarios.
        b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt: Scalar baseline medium-term nominal debt for the B6 market public scenario, used to scale the nominal appreciation adjustment.
        b6_combo_nonmkt_pub_in_billions_of_lc: Scalar B6 combo non-market public debt in billions of local currency, used to scale the non-market nominal appreciation adjustment.
        c3_commodity_pub_historical_statistics_key_variables_past_10: Scalar historical-statistics key variable for the past ten years, used as the C3 phase-out denominator and decrement.

    Returns:
        data.Series[float | str | None] containing the inflation rate (GDP deflator, in percent) (B1_GDP_pub), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'B6_mkt' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_mkt_pub_i_baseline_medium_term_nominal_debt, dsa_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B5' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(leftover_real_interest_rate[scenario], dsa_pub_b5_depreciation_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'B6_nonmkt' and time_period == 2025:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(b6_combo_nonmkt_pub_in_billions_of_lc, dsa_pub_b6_combo_non_mkt_pub_nominal_appreciation_increase_in_us_dollar_value_of_local_currency_in_percent[scenario, time_period])))
        elif scenario == 'C3' and time_period == 2025:
            return as_measure(xl_mul(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_add(1, xl_div(xl_mul(dsa_pub_c3_commodity_prices_pub_decline_in_gdp_deflator, dsa_ext_exports[scenario, time_period - 1]), 100))))
        elif scenario == 'C3' and time_period == 2026:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 1)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2027:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 2)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2028:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 3)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2029:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 4)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'C3' and time_period == 2030:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_div(xl_mul(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[2026], dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, 2025]), xl_sub(c3_commodity_pub_historical_statistics_key_variables_past_10, 5)), c3_commodity_pub_historical_statistics_key_variables_past_10)))
        elif scenario == 'A1' and time_period == 2025:
            return as_measure(a1_hist_pub_historical_statistics['Inflation rate (GDP deflator, in percent)', 'Historical average'])
        elif scenario == 'B1' and time_period <= 2026:
            return as_measure(xl_sub(baseline_pub_inflation_rate_gdp_deflator_pct[time_period], xl_mul(xl_sub(baseline_pub_real_gdp_growth[time_period], dsa_pub_real_gdp_growth_in_percent[scenario, time_period]), leftover_real_interest_rate[scenario])))
        elif scenario == 'A1' and time_period >= 2026:
            return as_measure(dsa_pub_inflation_rate_gdp_deflator_in_percent[scenario, time_period - 1])
        return as_measure(baseline_pub_inflation_rate_gdp_deflator_pct[time_period])

    dsa_pub_inflation_rate_gdp_deflator_in_percent = CoordinateReader('dsa_pub_inflation_rate_gdp_deflator_in_percent', data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required, formula)
    return data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.collect((coord, dsa_pub_inflation_rate_gdp_deflator_in_percent[coord]) for coord in data.DSA_PUB_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required)

@publish(data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.schema, cells=data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.cells)
def dsa_pub_us_inflation_rate_gdp_deflator_in_percent(*, macro_debt_us_gdp_deflator_percent_change: data.Series[float | str | None], baseline_pub_us_inflation_rate_gdp_deflator_pct: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Selects US GDP-deflator inflation rates by scenario, using macro-debt percent changes for A1 and the baseline public inflation series otherwise.

    Builds the DSA public US inflation rate (GDP deflator, in percent) series keyed by scenario and projection years.

    Args:
        macro_debt_us_gdp_deflator_percent_change: data.Series[float | str | None] of US GDP-deflator percent changes from macro-debt data, supplying the A1 scenario values.
        baseline_pub_us_inflation_rate_gdp_deflator_pct: data.Series[float | str | None] of baseline public US inflation rates (GDP deflator, in percent), supplying all non-A1 scenario values.

    Returns:
        data.Series[float | str | None] of US inflation rates (GDP deflator, in percent), keyed by scenario and years from row 7.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'A1':
            return as_measure(macro_debt_us_gdp_deflator_percent_change[time_period])
        return as_measure(baseline_pub_us_inflation_rate_gdp_deflator_pct[time_period])

    return data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.collect(evaluate(formula, data.DSA_PUB_US_INFLATION_RATE_GDP_DEFLATOR_IN_PERCENT.required))

