        pv_resfin_add_int_cost_mkt_cumulative_beyond_projection_window=data.PV_RESFIN_ADD_INT_COST_MKT_CUMULATIVE_BEYOND_PROJECTION_WINDOW.collect((coord, pv_resfin_add_int_cost_mkt_cumulative_beyond_projection_window[coord]) for coord in data.PV_RESFIN_ADD_INT_COST_MKT_CUMULATIVE_BEYOND_PROJECTION_WINDOW.required),
