@publish(data.INPUT4_DISCOUNT_RATE.schema, cells=data.INPUT4_DISCOUNT_RATE.cells)
def input4_discount_rate(*, discount_rate: float | str) -> data.Series[float | str | None]:
    """Build the external-debt discount-rate series from a scalar input.

    Apply one discount rate to every external instrument row for Input 4.

    Args:
        discount_rate: Discount rate applied to each external instrument row; scalar float or string.

    Returns:
        A data.Series[float | str | None] over external instrument rows, carrying the discount rate for IMF and all other instruments.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'IMF':
            return as_measure(discount_rate)
        return as_measure(input4_discount_rate['IMF'])

    input4_discount_rate = CoordinateReader('input4_discount_rate', data.INPUT4_DISCOUNT_RATE.required, formula)
    return data.INPUT4_DISCOUNT_RATE.collect((coord, input4_discount_rate[coord]) for coord in data.INPUT4_DISCOUNT_RATE.required)

