        INSTRUMENT_TO_INPUT3_NEW_DISBURSEMENTS = {'IMF': 'IMF', 'IDA - regular': 'IDA - regular', 'IDA - 50Y loans': 'IDA - 50Y loans', 'IDA - SML': 'IDA - SML', 'IDA NEW 40-year credits': 'IDA NEW 40-year credits', 'IDA NEW Regular': 'IDA NEW Regular', 'IDA NEW Blend (also enter) -->': 'IDA NEW Blend', 'IDA NEW 60-year credits': 'IDA NEW 60-year credits', 'MULTI1': 'Multilateral2', 'MULTI2': 'Multilateral3', 'OTH_MULTI1': 'Other multilateral1', 'OTH_MULTI2': 'Other multilateral2', 'OTH_MULTI3': 'Other multilateral3', 'Export Credit Agencies': 'Paris Club1', 'PC2': 'Paris Club2', 'PC3': 'Paris Club3', 'PC4': 'Paris Club4', 'PC5': 'Paris Club5', 'Export Import Bank of NPC': 'Non-Paris Club1', 'NPC2': 'Non-Paris Club2', 'NPC3': 'Non-Paris Club3', 'NPC4': 'Non-Paris Club4', 'NPC5': 'Non-Paris Club5', 'Eurobond': 'Commercial1', 'Commecial Bank': 'Commercial2', 'COM3': 'Commercial3', 'COM4': 'Commercial4', 'COM5': 'Commercial5'}
