        return as_measure(xl_sum(view(input4_disbursements_internal, rows=('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend (also enter) -->', 'IDA NEW 60-year credits', 'MULTI1', 'MULTI2', 'OTH_MULTI1', 'OTH_MULTI2', 'OTH_MULTI3', 'Export Credit Agencies', 'PC2', 'PC3', 'PC4', 'PC5', 'Export Import Bank of NPC', 'NPC2', 'NPC3', 'NPC4', 'NPC5', 'Eurobond', 'Commecial Bank', 'COM3', 'COM4', 'COM5'), cols=(time_period,))))

