@publish(data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.schema, cells=data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.cells)
def input5_instrument_terms_instrument_label(*, translation_input_5_domestic_financing_locally_issued_debt: data.Series[str | None], translation_input_5_domestic_financing_central_bank_financing: data.Series[str | None], translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: data.Series[str | None], translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: data.Series[str | None], translation_input_5_domestic_financing_mlt_debt: data.Series[str | None], translation_input_5_domestic_financing_denominated_in_local_currency_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_1_to_3_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_4_to_7_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_beyond_7_years_lc: data.Series[str | None], translation_input_5_domestic_financing_bonds_1_to_3_years_fx: data.Series[str | None], translation_input_5_domestic_financing_bonds_4_to_7_years_fx: data.Series[str | None], translation_input_5_domestic_financing_bonds_beyond_7_years_fx: data.Series[str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, external_domestic_debt_definition: str, start_debt_sustainability_analysis_m: int | str, lookup_afg_ap: str | int | float | bool, lookup_hti: str | int | float | bool, lookup_hnd: str | int | float | bool, translation_st_debt: data.Series[str | int | float | bool | None], lookup_afg: str | int | float | bool) -> data.Series[str | int | float | bool | None]:
    """Compute the `input5.instrument_terms` instrument-label series for the resident-holder column.

    Resolve each instrument label shown under Input 5 domestic financing from the translation sheet, the short-term debt labels, and the external/domestic debt definition lookups.

    Args:
        translation_input_5_domestic_financing_locally_issued_debt: Translation-sheet label text for locally issued debt under Input 5 domestic financing, carried as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_central_bank_financing: Translation-sheet label text for central bank financing under Input 5 domestic financing, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_t_bills_denominated_in_local_currency: Translation-sheet label text for T-bills denominated in local currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency: Translation-sheet label text for T-bills denominated in foreign currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_mlt_debt: Translation-sheet label text for medium- and long-term (MLT) debt, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_denominated_in_local_currency_lc: Translation-sheet label text for the debt-denominated-in-local-currency line item, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_1_to_3_years_lc: Translation-sheet label text for bonds with 1 to 3 year maturities in local currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_4_to_7_years_lc: Translation-sheet label text for bonds with 4 to 7 year maturities in local currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_beyond_7_years_lc: Translation-sheet label text for bonds with maturities beyond 7 years in local currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_1_to_3_years_fx: Translation-sheet label text for bonds with 1 to 3 year maturities in foreign currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_4_to_7_years_fx: Translation-sheet label text for bonds with 4 to 7 year maturities in foreign currency, as a named-axis series over catalog coordinates.
        translation_input_5_domestic_financing_bonds_beyond_7_years_fx: Translation-sheet label text for bonds with maturities beyond 7 years in foreign currency, as a named-axis series over catalog coordinates.
        input5_definition_of_external_domestic_debt: Scalar switch for the Input 5 definition of external/domestic debt, compared against the definition lookup to select the foreign-currency label.
        external_domestic_debt_definition: Scalar definition string for external and domestic debt, tested against the Input 5 switch to choose the foreign-currency label.
        start_debt_sustainability_analysis_m: Scalar starting period of the debt sustainability analysis, used to select the language column when stepping the label axes.
        lookup_afg_ap: Scalar lookup label for the AFG/AP case, returned as the held-by-residents label when the definition matches.
        lookup_hti: Scalar lookup label for the HTI case, returned as the denominated-in-foreign-currency label when the Input 5 definition matches.
        lookup_hnd: Scalar lookup label for the HND case, returned as the denominated-in-foreign-currency label when the Input 5 definition does not match.
        translation_st_debt: Text and numeric labels for short-term debt keyed by the Maturity axis, carried as a named-axis series over catalog coordinates.
        lookup_afg: Scalar lookup label for the AFG case, used as the held-by-residents label when the debt definition matches.

    Returns:
        A `data.Series[str | int | float | bool | None]` of instrument labels over the instrument and holder (residents) catalog coordinates.
    """
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_LOCALLY_ISSUED_DEBT.schema.validate(translation_input_5_domestic_financing_locally_issued_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_CENTRAL_BANK_FINANCING.schema.validate(translation_input_5_domestic_financing_central_bank_financing)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_LOCAL_CURRENCY.schema.validate(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_T_BILLS_DENOMINATED_IN_FOREIGN_CURRENCY.schema.validate(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_MLT_DEBT.schema.validate(translation_input_5_domestic_financing_mlt_debt)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_DENOMINATED_IN_LOCAL_CURRENCY_LC.schema.validate(translation_input_5_domestic_financing_denominated_in_local_currency_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_LC.schema.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_lc)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_1_TO_3_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_1_to_3_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_4_TO_7_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_4_to_7_years_fx)
    data.TRANSLATION_INPUT_5_DOMESTIC_FINANCING_BONDS_BEYOND_7_YEARS_FX.schema.validate(translation_input_5_domestic_financing_bonds_beyond_7_years_fx)
    def formula(instrument: str, holder: str) -> str | int | float | bool | None:
        if instrument == 'Locally-issued debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_locally_issued_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Held by residents' and holder == 'residents':
            return as_measure((lookup_afg_ap if xl_bool(xl_eq(external_domestic_debt_definition, lookup_afg)) else ''), 'str')
        elif instrument == 'Central bank financing' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_central_bank_financing[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Short-term debt' and holder == 'residents':
            return as_measure(translation_st_debt[axis_step(('Maturity', 'Échéance', 'Vencimento', 'Vencimiento'), 'Maturity', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in local currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_local_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'T-bills (denominated in foreign currency)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_t_bills_denominated_in_foreign_currency[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'MLT debt' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_mlt_debt[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in local currency (LC)' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_denominated_in_local_currency_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (1 to 3 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-LC' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_lc[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Denominated in foreign currency (FX)' and holder == 'residents':
            return as_measure((lookup_hti if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else lookup_hnd), 'str')
        elif instrument == 'Bonds (1 to 3 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_1_to_3_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (4 to 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_4_to_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        elif instrument == 'Bonds (beyond 7 years)-FX' and holder == 'residents':
            return as_measure(translation_input_5_domestic_financing_bonds_beyond_7_years_fx[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
        return as_measure(input5_instrument_terms_instrument_label[instrument, 'residents'], 'str')

    input5_instrument_terms_instrument_label = CoordinateReader('input5_instrument_terms_instrument_label', data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.required, formula)
    return data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.collect((coord, input5_instrument_terms_instrument_label[coord]) for coord in data.INPUT5_INSTRUMENT_TERMS_INSTRUMENT_LABEL.required)

@publish(data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.schema, cells=data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.cells)
def input5_internal_interest_rate_on_domestic_debt(*, input5_interest_rate_on_domestic_debt: data.Input5InterestRateOnDomesticDebt, input5_interest_rate_on_domestic_debt_fx_long: data.Input5InterestRateOnDomesticDebtFxLong) -> data.Series[float | str | None]:
    """Lift the Input 5 interest-rate-on-domestic-debt series by carrying prior-year instrument/holder terms forward across the projection grid.

    Fills the 17-series internal interest-rate block for domestic debt, including the FX-bond terms that non-residents inherit from residents and the trailing-year carry-forward on member rows.

    Args:
        input5_interest_rate_on_domestic_debt: Named-axis tensor of domestic-debt interest rates on Input 5 by instrument (bonds by maturity and currency, T-bills, central bank financing), holder (residents, non-residents), and year, supplying the rates that roll forward one period at a time.
        input5_interest_rate_on_domestic_debt_fx_long: Companion series holding the long-maturity foreign-currency bond rates (4 to 7 years, beyond 7 years) that are applied when the resident terms are copied onto non-resident holders over the projection years.

    Returns:
        Series over instrument, holder, and year coordinates giving each instrument/holder/year interest rate as a float, or a str or None where the underlying cell is text or blank.
    """
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT.schema.validate(input5_interest_rate_on_domestic_debt)
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT_FX_LONG.schema.validate(input5_interest_rate_on_domestic_debt_fx_long)
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if instrument == 'Central bank financing' and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt_fx_long[instrument, holder, time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX') and holder == 'residents' and time_period == 2030:
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])
        elif instrument in ('Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and holder == 'non-residents' and time_period in (2024, 2025, 2026, 2027, 2028, 2029):
            return as_measure(input5_interest_rate_on_domestic_debt_fx_long[instrument, 'residents', time_period])
        elif instrument == 'Central bank financing' and holder == 'residents' and time_period in (2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Central bank financing', 'residents', time_period - 1])
        elif instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX') and holder == 'non-residents' and time_period in (2024, 2025, 2026, 2027, 2028, 2029):
            return as_measure(input5_interest_rate_on_domestic_debt[instrument, 'residents', time_period])
        return as_measure(input5_internal_interest_rate_on_domestic_debt[instrument, holder, time_period - 1])

    input5_internal_interest_rate_on_domestic_debt = CoordinateReader('input5_internal_interest_rate_on_domestic_debt', data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.required, formula)
    return data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.collect((coord, input5_internal_interest_rate_on_domestic_debt[coord]) for coord in data.INPUT5_INTERNAL_INTEREST_RATE_ON_DOMESTIC_DEBT.required)

@publish(data.INPUT5_INTERNAL_GRACE_PERIOD.schema, cells=data.INPUT5_INTERNAL_GRACE_PERIOD.cells)
def input5_internal_grace_period(*, input5_grace_period: data.Input5GracePeriod) -> data.Series[float | str | None]:
    """Compute the internal grace-period series from Input 5 instrument terms.

    Lift internal grace-period values for the six bond instrument-term series and non-resident holders.

    Args:
        input5_grace_period: Input5GracePeriod series keyed by instrument and holder, providing the source grace-period terms.

    Returns:
        A data.Series[float | str | None] of internal grace-period values for the six bond instrument-term series and non-resident holders.
    """
    data.INPUT5_GRACE_PERIOD.schema.validate(input5_grace_period)
    def formula(instrument: str, holder: str) -> float | str | None:
        return as_measure(input5_grace_period[instrument, 'residents'])

    return data.INPUT5_INTERNAL_GRACE_PERIOD.collect(evaluate(formula, data.INPUT5_INTERNAL_GRACE_PERIOD.required))

@publish(data.INPUT5_INTERNAL_MATURITY.schema, cells=data.INPUT5_INTERNAL_MATURITY.cells)
def input5_internal_maturity(*, input5_maturity: data.Input5Maturity) -> data.Series[float | str | None]:
    """Extract internal bond maturity terms from Input 5 instrument data.

    Project internal maturity values for downstream LIC-DSF debt calculations.

    Args:
        input5_maturity: Maturity data series from Input 5, indexed by instrument and holder, carrying bond maturity terms for FX and LC instruments in the 1–3 year, 4–7 year, and beyond-7-year buckets.

    Returns:
        A data.Series[float | str | None] of internal maturity values keyed by the required instrument coordinates, with entries as floats, text labels, or nulls where no term is specified.
    """
    data.INPUT5_MATURITY.schema.validate(input5_maturity)
    def formula(instrument: str, holder: str) -> float | str | None:
        return as_measure(input5_maturity[instrument, 'residents'])

    return data.INPUT5_INTERNAL_MATURITY.collect(evaluate(formula, data.INPUT5_INTERNAL_MATURITY.required))

@publish(data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.schema, cells=data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.cells)
def input5_public_gfns_1_primary_deficit(*, macro_debt_public_sector_revenues_including_grants: data.Series[float | str | None], macro_debt_public_sector_primary_expenditure: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the Input 5 public-sector primary deficit series.

    Derives the primary deficit by subtracting public-sector revenues including grants from primary expenditure across projection years.

    Args:
        macro_debt_public_sector_revenues_including_grants: Public-sector revenues including grants as a data.Series[float | str | None] over the Input 5 projection-year catalog coordinates, supplying the subtrahend per year.
        macro_debt_public_sector_primary_expenditure: Public-sector primary expenditure as a data.Series[float | str | None] over the same projection-year coordinates, supplying the minuend per year.

    Returns:
        The public-sector primary deficit as a data.Series[float | str | None] keyed by projection years, with None or str propagated where the underlying inputs are blank or text-authored.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(macro_debt_public_sector_primary_expenditure[time_period], macro_debt_public_sector_revenues_including_grants[time_period]))

    return data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_1_PRIMARY_DEFICIT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.cells)
def input5_public_gfns_2_debt_services_from_existing_debt(*, input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: data.Series[float | str | None], input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute debt service from existing public debt on Input 5.

    Adds domestic including short-term debt from the previous year and external MLT debt service into a projection-year series.

    Args:
        input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year: Domestic debt service from existing debt, including short-term debt from the previous year, as a projection-year series.
        input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt: External medium- and long-term (MLT) debt service from existing debt, as a projection-year series.

    Returns:
        A projection-year series of total debt service from existing debt, equal to domestic including short-term from previous year plus external MLT debt service.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year[time_period], input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_domestic_including_st_debt_from_previous_year(*, input5_old_debt_debt_service_from_old_debt_residency_based: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute Input 5 domestic debt service from existing debt, including short-term debt from the previous year, for public GFNs 2.

    Project the domestic debt-service series from the residency-based old-debt service series using authored coordinate identities.

    Args:
        input5_old_debt_debt_service_from_old_debt_residency_based: A projection-year series of debt service on existing debt, residency-based, with float, string, or missing values.

    Returns:
        A data.Series[float | str | None] keyed by projection years, giving debt services from existing debt / domestic (including short-term debt from the previous year) on Input 5.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(input5_old_debt_debt_service_from_old_debt_residency_based[time_period])

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_DOMESTIC_INCLUDING_ST_DEBT_FROM_PREVIOUS_YEAR.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_external_debt_mlt(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_total_including_locally_issued: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes debt services from existing external debt (MLT) on Input 5 by multiplying total external debt including locally issued debt by the nominal average LCU/USD exchange rate.

    Populates the Input 5 public GFNS 2 debt-service series for external debt (MLT) across projection years.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: A data.Series[float | str | None] over catalog coordinates holding the macro nominal average LCU/USD exchange rate for each projection year.
        ext_debt_total_including_locally_issued: A data.Series[float | str | None] over catalog coordinates holding total external debt including locally issued debt for each projection year.

    Returns:
        A data.Series[float | str | None] of debt services from existing debt / external debt (MLT) on Input 5, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_total_including_locally_issued[time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_EXTERNAL_DEBT_MLT.required))

@publish(data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.cells)
def input5_public_gfns_2_debt_services_from_existing_debt_ow_imf(*, ext_debt_old_mlt_debt_service: data.Series[float | str | None], input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Convert existing external debt service owed to the IMF from USD into local currency at the Input 5 average nominal exchange rate.

    Produces the Input 5 public GFNS line for debt service on existing debt, of which IMF, across the projection-year grid.

    Args:
        ext_debt_old_mlt_debt_service: Series of existing external debt multilateral debt service owed to the IMF, keyed by projection years, expressible as floats with template blanks and text placeholders.
        input5_macro_nominal_exchange_rate_average_lcu_usd: Series of the Input 5 macro nominal average exchange rate in LCU per USD, keyed by the same projection years, with the same float-or-placeholder value domain.

    Returns:
        Series of debt service from existing debt (of which IMF) in local currency units, keyed by projection years, preserving the float-or-placeholder value domain of the inputs.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_old_mlt_debt_service['IMF', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_2_DEBT_SERVICES_FROM_EXISTING_DEBT_OW_IMF.required))

