@publish(data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.cells)
def input5_public_gfns_3_debt_services_from_new_debt_ow_imf(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_new_interest_external: data.Series[float | str | None], ext_debt_new_amortization_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the of-which-IMF debt service from new external debt on Input 5, keyed by projection years.

    Derive the IMF share of public GFNS debt service from new debt by converting interest plus amortization to local currency.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Nominal average exchange rate (LCU per USD) series keyed by projection years.
        ext_debt_new_interest_external: External new-debt interest series restricted to the IMF creditor category, keyed by projection years.
        ext_debt_new_amortization_external: External new-debt amortization series restricted to the IMF creditor category, keyed by projection years.

    Returns:
        data.Series[float | str | None] of public GFNS debt service from new debt, of which IMF, expressed in local currency units and keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_add(ext_debt_new_interest_external['IMF', time_period], ext_debt_new_amortization_external['IMF', time_period]), input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_3_DEBT_SERVICES_FROM_NEW_DEBT_OW_IMF.required))

@publish(data.INPUT5_PUBLIC_GFNS_5_OTHER_DEBT_CREATING_OR_REDUCING_FLOWS.schema, cells=data.INPUT5_PUBLIC_GFNS_5_OTHER_DEBT_CREATING_OR_REDUCING_FLOWS.cells)
def input5_public_gfns_5_other_debt_creating_or_reducing_flows(*, baseline_pub_other_identified_debt_creating_flows: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute Input 5 other public debt-creating or reducing flows.

    Derives the other debt-creating or reducing flows series by applying the identified flow share to baseline public nominal GDP.

    Args:
        baseline_pub_other_identified_debt_creating_flows: Baseline public other identified debt-creating or reducing flows, as a data.Series[float | str | None] keyed by projection years and expressed as a percentage of GDP.
        baseline_pub_nominal_gdp_lc: Baseline public nominal GDP in local currency, as a data.Series[float | str | None] keyed by projection years.

    Returns:
        data.Series[float | str | None]: Other debt creating or reducing flows on Input 5, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(baseline_pub_other_identified_debt_creating_flows[time_period], 100), baseline_pub_nominal_gdp_lc[time_period]))

    return data.INPUT5_PUBLIC_GFNS_5_OTHER_DEBT_CREATING_OR_REDUCING_FLOWS.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_5_OTHER_DEBT_CREATING_OR_REDUCING_FLOWS.required))

@publish(data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_EXCLUDING_LOCALLY_ISSUED_DEBT.schema, cells=data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_EXCLUDING_LOCALLY_ISSUED_DEBT.cells)
def input5_public_gfns_7_external_financing_mlt_excluding_locally_issued_debt(*, input4_disbursement_totals: data.Series[float | str | None], input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute Input 5 external financing (MLT) excluding locally issued debt.

    Derives the projection-year external financing series by multiplying disbursement totals by the average nominal LCU/USD exchange rate.

    Args:
        input4_disbursement_totals: Disbursement totals as a data.Series[float | str | None] over catalog projection-year coordinates; entries may be numeric, string, or missing.
        input5_macro_nominal_exchange_rate_average_lcu_usd: Average macro nominal exchange rate in LCU per USD as a data.Series[float | str | None] over catalog projection-year coordinates; entries may be numeric, string, or missing.

    Returns:
        A data.Series[float | str | None] of external financing (MLT) excluding locally issued debt, keyed by projection years, where each value is the elementwise product of the corresponding disbursement-total and nominal-exchange-rate entries.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(input4_disbursement_totals[time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_EXCLUDING_LOCALLY_ISSUED_DEBT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_EXCLUDING_LOCALLY_ISSUED_DEBT.required))

@publish(data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_OW_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_OW_IMF.cells)
def input5_public_gfns_7_external_financing_mlt_ow_imf(*, ext_debt_new_disbursements_external: data.Series[float | str | None], input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute IMF medium-and-long-term external financing in local currency on Input 5.

    Convert IMF external debt disbursements to local currency so they can be reported in the Input 5 external financing row.

    Args:
        ext_debt_new_disbursements_external: A data.Series keyed by projection years holding new external debt disbursements from the IMF, as a float, str, or None per year.
        input5_macro_nominal_exchange_rate_average_lcu_usd: A data.Series keyed by projection years holding the average nominal exchange rate in local currency units per U.S. dollar, as a float, str, or None per year.

    Returns:
        A data.Series keyed by projection years containing the IMF medium-and-long-term external financing amount in local currency, as a float, str, or None per year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_new_disbursements_external['IMF', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_OW_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_7_EXTERNAL_FINANCING_MLT_OW_IMF.required))

@publish(data.INPUT5_PUBLIC_GFNS_8_EXTERNAL_FINANCING_ST_EXCLUDING_LOCALLY_ISSUED_DEBT.schema, cells=data.INPUT5_PUBLIC_GFNS_8_EXTERNAL_FINANCING_ST_EXCLUDING_LOCALLY_ISSUED_DEBT.cells)
def input5_public_gfns_8_external_financing_st_excluding_locally_issued_debt(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], ext_debt_st_external_nominal: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes short-term external financing excluding locally issued debt by converting nominal short-term external debt to local currency at the average nominal exchange rate.

    Derives the Input 5 external short-term financing series excluding locally issued debt over projection years.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Series of average nominal LCU/USD exchange rates over projection years; accepts numeric, text, or missing values.
        ext_debt_st_external_nominal: Series of nominal short-term external debt over projection years; accepts numeric, text, or missing values.

    Returns:
        Series keyed by projection years containing external short-term financing excluding locally issued debt in local currency, with values that may be numeric, text, or missing.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_st_external_nominal[time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]))

    return data.INPUT5_PUBLIC_GFNS_8_EXTERNAL_FINANCING_ST_EXCLUDING_LOCALLY_ISSUED_DEBT.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_8_EXTERNAL_FINANCING_ST_EXCLUDING_LOCALLY_ISSUED_DEBT.required))

@publish(data.INPUT5_PUBLIC_GFNS_9_CHANGES_IN_LIQUID_ASSETS.schema, cells=data.INPUT5_PUBLIC_GFNS_9_CHANGES_IN_LIQUID_ASSETS.cells)
def input5_public_gfns_9_changes_in_liquid_assets(*, in3_macro_liquid_financial_assets_used_meet_gfns_flow_e_g: data.In3MacroLiquidFinancialAssetsUsedMeetGfnsFlowEG) -> data.Series[float | str | None]:
    """Compute Input 5 line 9 changes in liquid assets by negating the macro liquid financial assets used to meet GFNS flow over projection years.

    Derive the Input 5 public GFNS liquid-asset change series from the corresponding Input 3 macro liquid-asset series.

    Args:
        in3_macro_liquid_financial_assets_used_meet_gfns_flow_e_g: Named-axis tensor series of macro liquid financial assets used to meet gross financing needs over catalog projection years, with numeric cells contributing and non-numeric cells treated as zero.

    Returns:
        Typed data.Series over projection years giving the Input 5 changes in liquid assets, using the negated source value for numeric cells and zero for non-numeric cells, with elements typed float | str | None.
    """
    data.IN3_MACRO_LIQUID_FINANCIAL_ASSETS_USED_MEET_GFNS_FLOW_E_G.schema.validate(in3_macro_liquid_financial_assets_used_meet_gfns_flow_e_g)
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_neg(in3_macro_liquid_financial_assets_used_meet_gfns_flow_e_g[time_period]) if xl_bool(xl_isnumber(lambda: xl_neg(in3_macro_liquid_financial_assets_used_meet_gfns_flow_e_g[time_period]))) else 0))

    return data.INPUT5_PUBLIC_GFNS_9_CHANGES_IN_LIQUID_ASSETS.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_9_CHANGES_IN_LIQUID_ASSETS.required))

@publish(data.INPUT5_PUBLIC_GFNS_10_DRAWDOWN_OF_RESERVES_TO_REPAY_THE_IMF.schema, cells=data.INPUT5_PUBLIC_GFNS_10_DRAWDOWN_OF_RESERVES_TO_REPAY_THE_IMF.cells)
def input5_public_gfns_10_drawdown_of_reserves_to_repay_the_imf(*, input5_public_gfns_2_debt_services_from_existing_debt_ow_imf: data.Series[float | str | None], input5_public_gfns_3_debt_services_from_new_debt_ow_imf: data.Series[float | str | None], input5_public_gfns_7_external_financing_mlt_ow_imf: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the drawdown of reserves to repay the IMF on Input 5 as a projection-year series.

    Derive the IMF reserve-drawdown path from existing and new IMF debt service net of medium- and long-term external financing owed to the IMF.

    Args:
        input5_public_gfns_2_debt_services_from_existing_debt_ow_imf: Projection-year data.Series[float | str | None] of debt service on existing debt owed to the IMF.
        input5_public_gfns_3_debt_services_from_new_debt_ow_imf: Projection-year data.Series[float | str | None] of debt service on new debt owed to the IMF.
        input5_public_gfns_7_external_financing_mlt_ow_imf: Projection-year data.Series[float | str | None] of medium- and long-term external financing owed to the IMF.

    Returns:
        data.Series[float | str | None] of the drawdown of reserves to repay the IMF keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(xl_add(input5_public_gfns_2_debt_services_from_existing_debt_ow_imf[time_period], input5_public_gfns_3_debt_services_from_new_debt_ow_imf[time_period]), input5_public_gfns_7_external_financing_mlt_ow_imf[time_period]))

    return data.INPUT5_PUBLIC_GFNS_10_DRAWDOWN_OF_RESERVES_TO_REPAY_THE_IMF.collect(evaluate(formula, data.INPUT5_PUBLIC_GFNS_10_DRAWDOWN_OF_RESERVES_TO_REPAY_THE_IMF.required))

