@publish(key=(), domain=None, cells=data.INPUT5_DEFINITION_OF_EXTERNAL_DOMESTIC_DEBT_CELLS)
def input5_definition_of_external_domestic_debt(*, external_domestic_debt_definition: str) -> str | int | float | bool:
    """Resolve the Input 5 external-versus-domestic debt definition selector.

    Return the validated debt-definition value that distinguishes residency-based from currency-based external/domestic debt treatment in the LIC-DSF template.

    Args:
        external_domestic_debt_definition: Keyword-only scalar definition selector indicating the residency-based or currency-based external/domestic debt split for Input 5.

    Returns:
        A scalar string when the definition resolves as a valid measure, otherwise the XlError code as an int, float, bool, or string.
    """
    try:
        return as_measure(external_domestic_debt_definition, 'str')
    except XlError as error:
        return error.code

@publish(data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.schema, cells=data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.cells)
def input5_disbursements_public_domestic_st_disbursements_residency_based(*, input5_maturity_central_bank: int | str, input5_new_issuance: data.Series[float | str | None], input5_new_issuance_short_term_debt: data.Series[float | str | None], input5_new_issuance_domestic_residual_financing_to_close_gap: data.Series[float | str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, lookup_afg: str | int | float | bool) -> data.Series[float | str | None]:
    """Compute residency-based public domestic short-term disbursements on Input 5.

    Derive the domestic short-term disbursement path by summing central-bank financing where enabled, short-term debt issuance, and domestic residual financing, selecting the instrument branch that matches the configured external/domestic debt definition.

    Args:
        input5_maturity_central_bank: Scalar maturity flag indicating whether central bank financing is included in the path.
        input5_new_issuance: Typed series of new issuance keyed by projection years and indexed over instrument and residency coordinates, contributing the central bank or local-currency T-bill component.
        input5_new_issuance_short_term_debt: Typed series of short-term debt issuance by residency over projection years, used when the short-term definition branch is selected.
        input5_new_issuance_domestic_residual_financing_to_close_gap: Typed series of domestic residual financing required to close the gap over projection years, added to both branches.
        input5_definition_of_external_domestic_debt: Scalar definition of external versus domestic debt compared against the lookup value to choose the applicable instrument branch.
        lookup_afg: Scalar lookup value compared with the debt-definition flag to determine the branch identity.

    Returns:
        Typed series of public domestic short-term disbursements keyed by projection years, aligned to the required coordinate grid.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(xl_add((input5_new_issuance['Central bank financing', 'residents', time_period] if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else 0), input5_new_issuance_short_term_debt['residents', time_period]), input5_new_issuance_domestic_residual_financing_to_close_gap[time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else xl_add(xl_add((input5_new_issuance['Central bank financing', 'residents', time_period] if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else 0), input5_new_issuance['T-bills (denominated in local currency)', 'residents', time_period]), input5_new_issuance_domestic_residual_financing_to_close_gap[time_period])))

    return data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_ST_DISBURSEMENTS_RESIDENCY_BASED.required))

@publish(data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.schema, cells=data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.cells)
def input5_disbursements_public_domestic_mlt_disbursements_residency_based(*, input5_maturity_central_bank: int | str, input5_new_issuance: data.Series[float | str | None], input5_new_issuance_mlt_debt: data.Series[float | str | None], input5_new_issuance_denominated_in_local_currency_lc: data.Series[float | str | None], input5_definition_of_external_domestic_debt: str | int | float | bool, lookup_afg: str | int | float | bool) -> data.Series[float | str | None]:
    """Compute public domestic MLT disbursements on Input 5 using a residency-based external/domestic debt definition.

    Derive the residency-based public domestic MLT disbursement series from Input 5 new issuance and central-bank maturity settings.

    Args:
        input5_maturity_central_bank: Scalar flag indicating whether central bank financing matures in one period; when equal to 1, central bank financing contributes zero to the disbursement total.
        input5_new_issuance: Input 5 new issuance series (named-axis tensor over catalog coordinates); its 'Central bank financing' / 'residents' slice is included unless the central-bank maturity flag is 1.
        input5_new_issuance_mlt_debt: Input 5 new issuance of medium- and long-term debt series; its 'residents' slice is used when the debt-definition test matches the lookup value.
        input5_new_issuance_denominated_in_local_currency_lc: Input 5 new issuance denominated in local currency series; its 'residents' slice is used when the debt-definition test does not match the lookup value.
        input5_definition_of_external_domestic_debt: Scalar Input 5 setting for the external/domestic debt definition; compared to the lookup value to choose the MLT-debt or LC-denominated issuance component.
        lookup_afg: Scalar lookup value compared against the external/domestic debt definition setting to select the appropriate issuance component.

    Returns:
        data.Series[float | str | None] of public domestic MLT disbursements on Input 5, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add((0 if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else input5_new_issuance['Central bank financing', 'residents', time_period]), input5_new_issuance_mlt_debt['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else xl_add((0 if xl_bool(xl_eq(input5_maturity_central_bank, 1)) else input5_new_issuance['Central bank financing', 'residents', time_period]), input5_new_issuance_denominated_in_local_currency_lc['residents', time_period])))

    return data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_DISBURSEMENTS_PUBLIC_DOMESTIC_MLT_DISBURSEMENTS_RESIDENCY_BASED.required))

