@publish(data.INPUT5_RESIDUAL_TERMS_GDP_DEFLATOR.schema, cells=data.INPUT5_RESIDUAL_TERMS_GDP_DEFLATOR.cells)
def input5_residual_terms_gdp_deflator(*, macro_debt_change_in_gdp_deflator_factor: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Build the Input 5 residual-terms GDP deflator series from the macro-debt change GDP deflator factor.

    Produces the catalog-indexed GDP-deflator residual-terms series used by Input 5.

    Args:
        macro_debt_change_in_gdp_deflator_factor: Keyword-only data.Series[float | str | None] holding macro-debt change GDP-deflator factors over catalog time periods; values may be floats, strings, or None.

    Returns:
        A data.Series[float | str | None] on the input5.residual_terms GDP-deflator coordinates, spanning the Domestic MLT debt and Domestic short-term debt instruments across catalog time periods.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Domestic MLT debt':
            return as_measure(macro_debt_change_in_gdp_deflator_factor[time_period])
        return as_measure(input5_residual_terms_gdp_deflator['Domestic MLT debt', time_period])

    input5_residual_terms_gdp_deflator = CoordinateReader('input5_residual_terms_gdp_deflator', data.INPUT5_RESIDUAL_TERMS_GDP_DEFLATOR.required, formula)
    return data.INPUT5_RESIDUAL_TERMS_GDP_DEFLATOR.collect((coord, input5_residual_terms_gdp_deflator[coord]) for coord in data.INPUT5_RESIDUAL_TERMS_GDP_DEFLATOR.required)

@publish(data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT.schema, cells=data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT.cells)
def input5_residual_terms_average_real_interest_rate_on_new_debt(*, input5_residual_terms_average_nominal_interest_rate_on_new_debt: data.Series[float | str | None], input5_residual_terms_gdp_deflator: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the average real interest rate on new debt for domestic MLT and short-term instruments by subtracting the GDP deflator from the nominal interest rate.

    Derive the residual-terms real interest rate series from its nominal-rate and GDP-deflator input series.

    Args:
        input5_residual_terms_average_nominal_interest_rate_on_new_debt: Average nominal interest rate on new debt as a data.Series[float | str | None] over instrument and time_period coordinates, covering Domestic MLT debt and Domestic short-term debt.
        input5_residual_terms_gdp_deflator: GDP deflator as a data.Series[float | str | None] over instrument and time_period coordinates, aligned with the nominal-rate series for real-rate deflation.

    Returns:
        A data.Series[float | str | None] of average real interest rate on new debt over instrument and time_period coordinates; values are nominal rate minus GDP deflator when the nominal input is numeric, otherwise blank.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Domestic MLT debt':
            return as_measure((xl_sub(input5_residual_terms_average_nominal_interest_rate_on_new_debt['Domestic MLT debt', time_period], input5_residual_terms_gdp_deflator['Domestic MLT debt', time_period]) if xl_bool(xl_isnumber(lambda: input5_residual_terms_average_nominal_interest_rate_on_new_debt['Domestic MLT debt', time_period])) else ''))
        return as_measure((xl_sub(input5_residual_terms_average_nominal_interest_rate_on_new_debt['Domestic short-term debt', time_period], input5_residual_terms_gdp_deflator['Domestic short-term debt', time_period]) if xl_bool(xl_isnumber(lambda: input5_residual_terms_average_nominal_interest_rate_on_new_debt['Domestic short-term debt', time_period])) else ''))

    return data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT.collect(evaluate(formula, data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT.required))

@publish(data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT_AVERAGE.schema, cells=data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT_AVERAGE.cells)
def input5_residual_terms_average_real_interest_rate_on_new_debt_average(*, input5_residual_terms_average_real_interest_rate_on_new_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the per-instrument average real interest rate on new debt from the input5 residual terms series.

    Derive averaged real interest rates on new debt for Domestic MLT debt and Domestic short-term debt over 2024–2034.

    Args:
        input5_residual_terms_average_real_interest_rate_on_new_debt: Keyword-only data.Series[float | str | None] containing the input5 residual-terms real interest rate on new debt for Domestic MLT debt and Domestic short-term debt across catalog coordinates.

    Returns:
        data.Series[float | str | None] containing the per-instrument average real interest rate on new debt over 2024–2034, yielding 0 when that window sums to zero and otherwise the window average.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure((0 if xl_bool(xl_eq(xl_sum(view(input5_residual_terms_average_real_interest_rate_on_new_debt, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, 2024, 2034))), 0)) else xl_average(view(input5_residual_terms_average_real_interest_rate_on_new_debt, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, 2024, 2034)))))

    return data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT_AVERAGE.collect(evaluate(formula, data.INPUT5_RESIDUAL_TERMS_AVERAGE_REAL_INTEREST_RATE_ON_NEW_DEBT_AVERAGE.required))

