@publish(key=('INSTRUMENT',), domain=None, cells=data.INPUT5_RESIDUAL_TERMS_AVERAGE_MATURITY_OF_NEW_DEBT_ROUNDED_AVERAGE_CELLS)
def input5_residual_terms_average_maturity_of_new_debt_rounded_average(*, input5_residual_terms_average_grace_period_on_new_debt_rounded_average: int | str, input5_residual_terms_average_maturity_of_new_debt_average: float | str) -> int | str:
    """Return the rounded average maturity of new debt as the greater of the rounded-down average maturity and the rounded grace period incremented by one.

    Derive the integer maturity horizon used in input5 residual-terms financing for new debt.

    Args:
        input5_residual_terms_average_grace_period_on_new_debt_rounded_average: The rounded average grace period on new debt, as a scalar integer or an error string.
        input5_residual_terms_average_maturity_of_new_debt_average: The average maturity of new debt, as a scalar float or an error string.

    Returns:
        The rounded average maturity of new debt as an integer, or an error string if evaluation raises an Excel error.
    """
    try:
        return as_measure(xl_max(xl_rounddown(input5_residual_terms_average_maturity_of_new_debt_average, 0), xl_add(input5_residual_terms_average_grace_period_on_new_debt_rounded_average, 1)), 'int')
    except XlError as error:
        return error.code

@publish(data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.schema, cells=data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.cells)
def input5_old_debt_debt_service_from_old_debt_residency_based(*, input5_old_debt_interest_payment_on_old_debt_residency_based: data.Series[float | str | None], input5_old_debt_principal_payment_on_old_debt_residency_based: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute residency-based debt service from old debt.

    Combine interest and principal payments on old debt to obtain debt service by projection year.

    Args:
        input5_old_debt_interest_payment_on_old_debt_residency_based: Interest payments on old debt under the residency-based definition, as a named-axis data.Series[float | str | None] over projection years.
        input5_old_debt_principal_payment_on_old_debt_residency_based: Principal payments on old debt under the residency-based definition, as a named-axis data.Series[float | str | None] over projection years.

    Returns:
        Residency-based debt service from old debt as a data.Series[float | str | None], equal to interest plus principal payments and keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(input5_old_debt_interest_payment_on_old_debt_residency_based[time_period], input5_old_debt_principal_payment_on_old_debt_residency_based[time_period]))

    return data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_OLD_DEBT_DEBT_SERVICE_FROM_OLD_DEBT_RESIDENCY_BASED.required))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.cells)
def input5_old_debt_interest_payment_on_old_debt_residency_based(*, input5_definition_of_external_domestic_debt: str | int | float | bool, input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency: data.Series[float | str | None], input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency: data.Series[float | str | None], lookup_afg: str | int | float | bool) -> data.Series[float | str | None]:
    """Compute residency-based interest payments on old debt for Input 5.

    Selects and combines local- and foreign-currency old-debt interest series according to the external/domestic debt definition.

    Args:
        input5_definition_of_external_domestic_debt: Debt-definition scalar used to determine whether the external/domestic classification matches the lookup condition.
        input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency: Local-currency interest payment series for old debt, keyed by projection years, used for the resident basis.
        input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency: Foreign-currency interest payment series for old debt, keyed by projection years, added when the debt definition matches the lookup.
        lookup_afg: Lookup scalar compared with the debt definition to decide whether foreign-currency interest is included.

    Returns:
        Residency-based old-debt interest payments as a series keyed by projection years, with float, string, or null values.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency['residents', time_period], input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency['residents', time_period]) if xl_bool(xl_eq(input5_definition_of_external_domestic_debt, lookup_afg)) else input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency['residents', time_period]))

    return data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.collect(evaluate(formula, data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_RESIDENCY_BASED.required))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.cells)
def input5_old_debt_interest_payment_on_old_debt_denominated_in_local_currency(*, input3_domestic_interest_payment_from_existing_debt: data.Input3DomesticInterestPaymentFromExistingDebt) -> data.Series[float | str | None]:
    """Compute interest payment on old debt denominated in local currency by holder.

    Derives the local-currency old-debt interest payment series from domestic interest payments on existing debt, split across resident and non-resident holders.

    Args:
        input3_domestic_interest_payment_from_existing_debt: Typed data series of domestic interest payments on existing debt, indexed by currency denomination, holder, and time period, used to source resident and non-resident local-currency values.

    Returns:
        Typed data series of interest payments on old debt denominated in local currency by holder and time period, with numeric values preserved and non-numeric source entries treated as zero.
    """
    data.INPUT3_DOMESTIC_INTEREST_PAYMENT_FROM_EXISTING_DEBT.schema.validate(input3_domestic_interest_payment_from_existing_debt)
    def formula(holder: str, time_period: int) -> float | str | None:
        if holder == 'residents':
            return as_measure((input3_domestic_interest_payment_from_existing_debt['local', 'residents', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['local', 'residents', time_period])) else 0))
        return as_measure((input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period] if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['local', 'non-residents', time_period])) else 0))

    return data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.collect(evaluate(formula, data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_LOCAL_CURRENCY.required))

@publish(data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.schema, cells=data.INPUT5_OLD_DEBT_INTEREST_PAYMENT_ON_OLD_DEBT_DENOMINATED_IN_FOREIGN_CURRENCY.cells)
def input5_old_debt_interest_payment_on_old_debt_denominated_in_foreign_currency(*, input5_macro_nominal_exchange_rate_average_lcu_usd: data.Series[float | str | None], input3_domestic_interest_payment_from_existing_debt: data.Input3DomesticInterestPaymentFromExistingDebt) -> data.Series[float | str | None]:
    """Converts domestic interest payments on existing foreign-currency debt into foreign-currency terms for holders of old debt.

    Derives the foreign-currency interest payment on old debt by applying the average nominal exchange rate to the domestic interest payment on existing foreign-currency debt, evaluated per holder and time period.

    Args:
        input5_macro_nominal_exchange_rate_average_lcu_usd: Average macro nominal exchange rate expressed in local currency units per US dollar, as a typed data series over the catalog coordinate grid.
        input3_domestic_interest_payment_from_existing_debt: Typed Input-3 series bundle of domestic interest payments arising from existing debt, keyed by currency and holder (residents and non-residents), supplying the foreign-currency amounts to be converted.

    Returns:
        A typed data series of interest payments on old debt denominated in foreign currency, indexed by holder (residents and non-residents) and time period, with non-numeric source values treated as zero.
    """
    data.INPUT3_DOMESTIC_INTEREST_PAYMENT_FROM_EXISTING_DEBT.schema.validate(input3_domestic_interest_payment_from_existing_debt)
    def formula(holder: str, time_period: int) -> float | str | None:
        if holder == 'residents':
            return as_measure((xl_mul(input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]) if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'residents', time_period])) else 0))
        return as_measure((xl_mul(input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period], input5_macro_nominal_exchange_rate_average_lcu_usd[time_period]) if xl_bool(xl_isnumber(lambda: input3_domestic_interest_payment_from_existing_debt['foreign', 'non-residents', time_period])) else 0))

