@publish(data.INPUT5_VINTAGE_PROJECTION_YEARS_STOCK.schema, cells=data.INPUT5_VINTAGE_PROJECTION_YEARS_STOCK.cells)
def input5_vintage_projection_years_stock(*, input5_projection_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Extract the Input 5 vintage stock projection-year series.

    Projects the vintage stock year axis from Input 5 row 222 into catalog coordinates.

    Args:
        input5_projection_years: Typed data.Series of int, str, or None values representing the vintage stock year axis on Input 5 row 222.

    Returns:
        Typed data.Series of int, str, or None values containing the vintage stock projection years over catalog coordinates.
    """
    def formula(time_period: int) -> int | str | None:
        return as_measure(input5_projection_years[time_period], 'int')

    return data.INPUT5_VINTAGE_PROJECTION_YEARS_STOCK.collect(evaluate(formula, data.INPUT5_VINTAGE_PROJECTION_YEARS_STOCK.required))

@publish(data.INPUT5_VINTAGE_PROJECTION_YEARS_INTEREST.schema, cells=data.INPUT5_VINTAGE_PROJECTION_YEARS_INTEREST.cells)
def input5_vintage_projection_years_interest(*, input5_vintage_projection_years_principal: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute Input 5 vintage interest-payment projection years.

    Derive the interest-payment year axis by seeding 2024 from the principal projection-year series and incrementing each subsequent projection year.

    Args:
        input5_vintage_projection_years_principal: Vintage principal-payment projection-year series on Input 5 whose 2024 value seeds the interest-payment year axis.

    Returns:
        Vintage interest-payments year axis on Input 5 row 222 as a data.Series[int | str | None].
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(input5_vintage_projection_years_principal[time_period], 'int')
        return as_measure(xl_add(input5_vintage_projection_years_interest[time_period - 1], 1), 'int')

    input5_vintage_projection_years_interest = CoordinateReader('input5_vintage_projection_years_interest', data.INPUT5_VINTAGE_PROJECTION_YEARS_INTEREST.required, formula)
    return data.INPUT5_VINTAGE_PROJECTION_YEARS_INTEREST.collect((coord, input5_vintage_projection_years_interest[coord]) for coord in data.INPUT5_VINTAGE_PROJECTION_YEARS_INTEREST.required)

@publish(data.INPUT5_VINTAGE_PROJECTION_YEARS_PRINCIPAL.schema, cells=data.INPUT5_VINTAGE_PROJECTION_YEARS_PRINCIPAL.cells)
def input5_vintage_projection_years_principal(*, input5_vintage_projection_years_stock: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Derive the Input 5 vintage principal-payments projection-year axis from the vintage stock series.

    Seeds the principal-payments year coordinate series at 2024 and advances it by one year for each subsequent projection coordinate.

    Args:
        input5_vintage_projection_years_stock: Keyword-only data.Series[int | str | None] supplying the Input 5 vintage projection-years stock axis; its 2024 value initializes the principal-payments projection-year series, while scalar entries remain int, str, or None.

    Returns:
        data.Series[int | str | None] containing the vintage principal-payments projection-year axis, anchored to the stock series at 2024 and incremented by one for each later required coordinate.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(input5_vintage_projection_years_stock[time_period], 'int')
        return as_measure(xl_add(input5_vintage_projection_years_principal[time_period - 1], 1), 'int')

    input5_vintage_projection_years_principal = CoordinateReader('input5_vintage_projection_years_principal', data.INPUT5_VINTAGE_PROJECTION_YEARS_PRINCIPAL.required, formula)
    return data.INPUT5_VINTAGE_PROJECTION_YEARS_PRINCIPAL.collect((coord, input5_vintage_projection_years_principal[coord]) for coord in data.INPUT5_VINTAGE_PROJECTION_YEARS_PRINCIPAL.required)

@publish(data.INPUT5_VINTAGE_INSTRUMENT_TITLE.schema, cells=data.INPUT5_VINTAGE_INSTRUMENT_TITLE.cells)
def input5_vintage_instrument_title(*, input5_instrument_titles: data.Series[str | int | float | bool | None], input5_instrument_terms_instrument_label: data.Series[str | int | float | bool | None]) -> data.Series[str | int | float | bool | None]:
    """Resolve the vintage instrument title per instrument and holder coordinate.

    Choose between the instrument-level title and the instrument-terms label for each input5 instrument/holder pair.

    Args:
        input5_instrument_titles: data.Series of instrument titles keyed by instrument (Central bank financing, T-bills denominated in foreign currency, T-bills denominated in local currency), providing the default label for every holder.
        input5_instrument_terms_instrument_label: data.Series of instrument-terms labels keyed by (instrument, holder), supplying the non-resident T-bill overrides.

    Returns:
        data.Series[str | int | float | bool | None] of resolved instrument titles over the input5 instrument/holder coordinates.
    """
    def formula(instrument: str, holder: str) -> str | int | float | bool | None:
        if instrument in ('T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)') and holder == 'non-residents':
            return as_measure(input5_instrument_terms_instrument_label[instrument, holder], 'str')
        return as_measure(input5_instrument_titles[instrument], 'str')

    return data.INPUT5_VINTAGE_INSTRUMENT_TITLE.collect(evaluate(formula, data.INPUT5_VINTAGE_INSTRUMENT_TITLE.required))

@publish(data.INPUT5_VINTAGE_ISSUANCE_YEAR.schema, cells=data.INPUT5_VINTAGE_ISSUANCE_YEAR.cells)
def input5_vintage_issuance_year(*, input5_projection_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Return the Input 5 vintage issuance-year series for financing instruments and holders.

    Derive issuance years from projection-year inputs and residual-financing aliases so each instrument-holder vintage has a consistent issuance-year identity.

    Args:
        input5_projection_years: Keyword-only projection-year series (data.Series[int | str | None]) whose 2024 value anchors the listed bonds, T-bills, and central-bank financing issuance years.

    Returns:
        data.Series[int | str | None] named-axis series over the required input5_vintage_issuance_year coordinates, giving each instrument-holder vintage its issuance year, including carried-forward years and residual-financing aliases.
    """
    def formula(instrument: str, holder: str, issuance_year: int) -> int | str | None:
        if instrument in ('Central bank financing', 'T-bills (denominated in local currency)', 'T-bills (denominated in foreign currency)', 'Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC', 'Bonds (1 to 3 years)-FX', 'Bonds (4 to 7 years)-FX', 'Bonds (beyond 7 years)-FX') and issuance_year == 2024:
            return as_measure(input5_projection_years[issuance_year], 'int')
        elif instrument == 'Residual financing (T-bills denominated in local currency)' and holder == 'residents':
            return as_measure(input5_vintage_issuance_year['T-bills (denominated in local currency)', holder, issuance_year], 'int')
        return as_measure(xl_add(input5_vintage_issuance_year[instrument, holder, issuance_year - 1], 1), 'int')

    input5_vintage_issuance_year = CoordinateReader('input5_vintage_issuance_year', data.INPUT5_VINTAGE_ISSUANCE_YEAR.required, formula)
    return data.INPUT5_VINTAGE_ISSUANCE_YEAR.collect((coord, input5_vintage_issuance_year[coord]) for coord in data.INPUT5_VINTAGE_ISSUANCE_YEAR.required)

@publish(data.INPUT5_VINTAGE_TERMS.schema, cells=data.INPUT5_VINTAGE_TERMS.cells)
def input5_vintage_terms(*, input5_grace_period: data.Input5GracePeriod, input5_blue_cells_note: str | int | float | bool, input5_projection_years: data.Series[int | str | None], input5_instrument_terms_assumptions_on_domestic_financial_instruments_header: str | int | float | bool, input5_instrument_terms_grace_period_header: str | int | float | bool, input5_instrument_terms_interest_rate_on_domestic_debt_header: str | int | float | bool, input5_instrument_terms_maturity_header: str | int | float | bool, input5_instrument_terms_instrument_label: data.Series[str | int | float | bool | None], input5_interest_rate_on_domestic_debt: data.Input5InterestRateOnDomesticDebt, input5_interest_rate_on_domestic_debt_fx_long: data.Input5InterestRateOnDomesticDebtFxLong, input5_internal_interest_rate_on_domestic_debt: data.Series[float | str | None], input5_maturity: data.Input5Maturity, input5_maturity_central_bank: int | str, input5_constant_grace_period: data.Series[int | str | None], input5_constant_maturity: data.Series[int | str | None], input5_internal_grace_period: data.Series[float | str | None], input5_internal_maturity: data.Series[float | str | None], input5_vintage_instrument_title: data.Series[str | int | float | bool | None], input5_vintage_issuance_year: data.Series[int | str | None], input5_vintage_instrument_label: data.Series[str | int | float | bool | None]) -> data.Series[float | str | None]:
    """Extract the Input 5 vintage-terms table into a single typed series.

    Resolve the instrument-terms and vintage-terms blocks on Input 5 into one canonical series over the instrument and holder catalog.

    Args:
        input5_grace_period: Grace-period assumptions on domestic financial instruments, as a named-axis catalog series.
        input5_blue_cells_note: Scalar note flagging the blue (user-editable) cells on the Input 5 sheet.
        input5_projection_years: Projection-year labels as a series over the year axis, with blanks for years outside the projection horizon.
        input5_instrument_terms_assumptions_on_domestic_financial_instruments_header: Scalar header text for the domestic-financial-instrument assumptions block.
        input5_instrument_terms_grace_period_header: Scalar header text for the instrument-terms grace-period column.
        input5_instrument_terms_interest_rate_on_domestic_debt_header: Scalar header text for the instrument-terms interest-rate-on-domestic-debt column.
        input5_instrument_terms_maturity_header: Scalar header text for the instrument-terms maturity column.
        input5_instrument_terms_instrument_label: Instrument labels for the instrument-terms table, as a series over the instrument axis.
        input5_interest_rate_on_domestic_debt: Interest-rate assumptions on domestic debt by instrument and holder, as a named-axis catalog series.
        input5_interest_rate_on_domestic_debt_fx_long: Long-run foreign-currency interest-rate assumptions on domestic debt, as a named-axis catalog series.
        input5_internal_interest_rate_on_domestic_debt: Internal interest-rate-on-domestic-debt values as a series over catalog coordinates, possibly carrying blanks.
        input5_maturity: Maturity assumptions on domestic financial instruments, as a named-axis catalog series.
        input5_maturity_central_bank: Scalar maturity assigned to central-bank financing.
        input5_constant_grace_period: Constant (non-time-varying) grace-period values per instrument, as a series over the instrument axis.
        input5_constant_maturity: Constant (non-time-varying) maturity values per instrument, as a series over the instrument axis.
        input5_internal_grace_period: Internal grace-period values as a series over catalog coordinates, possibly carrying blanks.
        input5_internal_maturity: Internal maturity values as a series over catalog coordinates, possibly carrying blanks.
        input5_vintage_instrument_title: Vintage instrument titles, as a series over the vintage-instrument axis.
        input5_vintage_issuance_year: Issuance year of each vintage instrument, as a series over the vintage-instrument axis.
        input5_vintage_instrument_label: Vintage instrument labels, as a series over the vintage-instrument axis.

    Returns:
        Input 5 vintage terms as a float, str, or None series over the combined instrument and holder catalog coordinates.
    """
    data.INPUT5_GRACE_PERIOD.schema.validate(input5_grace_period)
    data.INPUT5_INTEREST_RATE_ON_DOMESTIC_DEBT.schema.validate(input5_interest_rate_on_domestic_debt)
