@publish(data.CHART_PROJECTION_YEARS.schema, cells=data.CHART_PROJECTION_YEARS.cells)
def chart_projection_years(*, macro_debt_main_assumptions_further_details: int | str, macro_debt_further_details: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Assemble the Chart Data projection-year series from Macro-Debt_Data further-details measures.

    Pulls Macro-Debt_Data projection-year measures onto the Chart Data row 35 year grid.

    Args:
        macro_debt_main_assumptions_further_details: Scalar further-details assumption used for the 2024 projection year.
        macro_debt_further_details: Projection-year-indexed data.Series of further-details measures; each non-2024 chart year is resolved by its time-period key.

    Returns:
        data.Series[int | str | None] aligned to the Chart Data projection-year axis (row 35), using the scalar for 2024 and the series lookup for all other years.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_main_assumptions_further_details, 'int')
        return as_measure(macro_debt_further_details[time_period], 'int')

    return data.CHART_PROJECTION_YEARS.collect(evaluate(formula, data.CHART_PROJECTION_YEARS.required))

