        return as_measure(dsa_pub_debt_service_to_revenue_and_grants_ratio_in_percent[SCENARIO_TO_DSA_PUB_DEBT_SERVICE_TO_REVENUE_AND_GRANTS_RATIO_IN_PERCENT[scenario], time_period])

