@dataclass(frozen=True, slots=True)
class ScanExtDebtOldMltStockEvolutionResult:
    """Complete named results of one recurrence group evaluation."""
    ext_debt_old_mlt_stock_evolution: data.Series[float | str | None]
    macro_debt_main_assumptions_us_dollars: data.Series[float | str | None]

def scan_ext_debt_old_mlt_stock_evolution(*, input3_ppg_external_debt_stock: data.Series[float | str | None], input3_input_3_external_debt_ppg_mlt_external_debt_outstanding: data.Input3Input3ExternalDebtPpgMltExternalDebtOutstanding, ext_debt_old_mlt_principal: data.Series[float | str | None], ext_debt_locally_issued_evolution: data.Series[float | str | None], ext_debt_stock_of_outstanding_arrears: data.Series[float | str | None], ext_debt_nominal_new_mlt_total: data.Series[float | str | None], in3_macro_transition_formula_these_o_w_medium_long_term: float | str, input3_local_currency_external_debt: data.Series[float | str | None]) -> ScanExtDebtOldMltStockEvolutionResult:
    """Evaluate the recurrence group `ext_debt_old_mlt_stock_evolution`, `macro_debt_main_assumptions_us_dollars` and publish complete tensors."""
    data.INPUT3_PPG_EXTERNAL_DEBT_STOCK.schema.validate(input3_ppg_external_debt_stock)
    data.INPUT3_INPUT_3_EXTERNAL_DEBT_PPG_MLT_EXTERNAL_DEBT_OUTSTANDING.schema.validate(input3_input_3_external_debt_ppg_mlt_external_debt_outstanding)
    def ext_debt_old_mlt_stock_evolution_formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_sub(macro_debt_main_assumptions_us_dollars[time_period], ext_debt_stock_of_outstanding_arrears[time_period]))
        return as_measure(xl_sub(xl_sub(ext_debt_old_mlt_stock_evolution[time_period - 1], ext_debt_old_mlt_principal[time_period]), xl_sub(ext_debt_locally_issued_evolution[time_period - 1], ext_debt_locally_issued_evolution[time_period])))

    ext_debt_old_mlt_stock_evolution = CoordinateReader('ext_debt_old_mlt_stock_evolution', data.EXT_DEBT_OLD_MLT_STOCK_EVOLUTION.required, ext_debt_old_mlt_stock_evolution_formula)
    def macro_debt_main_assumptions_us_dollars_formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_add((input3_input_3_external_debt_ppg_mlt_external_debt_outstanding[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_external_debt_ppg_mlt_external_debt_outstanding[time_period])) else 0), in3_macro_transition_formula_these_o_w_medium_long_term))
        elif time_period <= 2022:
            return as_measure(xl_add((input3_ppg_external_debt_stock['PPG MLT external debt outstanding', time_period] if xl_bool(xl_isnumber(lambda: input3_ppg_external_debt_stock['PPG MLT external debt outstanding', time_period])) else 0), input3_local_currency_external_debt['Outstanding', time_period]))
        return as_measure(xl_add(xl_add(ext_debt_old_mlt_stock_evolution[time_period], ext_debt_stock_of_outstanding_arrears[time_period]), ext_debt_nominal_new_mlt_total[time_period]))

    macro_debt_main_assumptions_us_dollars = CoordinateReader('macro_debt_main_assumptions_us_dollars', data.MACRO_DEBT_MAIN_ASSUMPTIONS_US_DOLLARS.required, macro_debt_main_assumptions_us_dollars_formula)
    return ScanExtDebtOldMltStockEvolutionResult(
        ext_debt_old_mlt_stock_evolution=data.EXT_DEBT_OLD_MLT_STOCK_EVOLUTION.collect((coord, ext_debt_old_mlt_stock_evolution[coord]) for coord in data.EXT_DEBT_OLD_MLT_STOCK_EVOLUTION.required),
        macro_debt_main_assumptions_us_dollars=data.MACRO_DEBT_MAIN_ASSUMPTIONS_US_DOLLARS.collect((coord, macro_debt_main_assumptions_us_dollars[coord]) for coord in data.MACRO_DEBT_MAIN_ASSUMPTIONS_US_DOLLARS.required),
    )

@publish(data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL.schema, cells=data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL.cells)
def ext_debt_new_disbursements_external(*, input4_disbursements: data.Input4Disbursements, input4_disbursements_internal: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Aggregates new external MLT disbursements by instrument and projection year.

    Build the external new-disbursement series that the LIC-DSF external debt module consumes, combining economist-entered Input 4 amounts with authored creditor-group subtotals.

    Args:
        input4_disbursements: Economist-entered external disbursement data for the Input 4 surface, a typed Input4Disbursements series indexed by instrument and time period that supplies IMF, IDA, and MULTI1 cells directly.
        input4_disbursements_internal: Internal disbursement series over instrument and time-period coordinates, used as the fallback amount for every instrument/year cell not governed by an explicit aggregation, Input 4 copy, or post-2044 zero rule.

    Returns:
        A data.Series[float | str | None] of new MLT external disbursements indexed by instrument and projection year, containing aggregated creditor subtotals through 2034 (2044 for commercial), zeros on instrument rows beyond 2044, and blank or string values where the template cell is unpopulated.
    """
    data.INPUT4_DISBURSEMENTS.schema.validate(input4_disbursements)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Multilaterals' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'IMF', 'MULTI2'), cols=(time_period,))))
        elif instrument == 'Other Multilaterals' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,))))
        elif instrument == 'Official Bilaterals' and time_period <= 2034:
            return as_measure(xl_add(ext_debt_new_disbursements_external['Paris Club', time_period], ext_debt_new_disbursements_external['Non-Paris Club', time_period]))
        elif instrument == 'Paris Club' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,))))
        elif instrument == 'Non-Paris Club' and time_period <= 2034:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,))))
        elif (instrument == 'IMF' and time_period <= 2026) or (instrument == 'IDA - regular' and time_period == 2025) or (instrument == 'IDA NEW 40-year credits' and time_period == 2026) or (instrument == 'IDA NEW Regular' and time_period == 2026) or (instrument == 'IDA NEW Blend (also enter) -->' and 2025 <= time_period <= 2027) or (instrument == 'IDA NEW 60-year credits' and 2025 <= time_period <= 2027) or (instrument == 'MULTI1' and time_period <= 2029):
            return as_measure(input4_disbursements[instrument, time_period])
        elif instrument == 'Commercial' and time_period <= 2044:
            return as_measure(xl_sum(view(ext_debt_new_disbursements_external, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))
        elif instrument in ('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA - SML', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend (also enter) -->', 'IDA NEW 60-year credits', 'MULTI1', 'MULTI2', 'OTH_MULTI1', 'OTH_MULTI2', 'OTH_MULTI3', 'Export Credit Agencies', 'PC2', 'PC3', 'PC4', 'PC5', 'Export Import Bank of NPC', 'NPC2', 'NPC3', 'NPC4', 'NPC5', 'Eurobond', 'Commecial Bank', 'COM3', 'COM4', 'COM5') and time_period >= 2045:
            return as_measure(0)
        return as_measure(input4_disbursements_internal[instrument, time_period])

    ext_debt_new_disbursements_external = CoordinateReader('ext_debt_new_disbursements_external', data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL.required, formula)
    return data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL.collect((coord, ext_debt_new_disbursements_external[coord]) for coord in data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL.required)

@publish(data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL_TOTAL.schema, cells=data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL_TOTAL.cells)
def ext_debt_new_disbursements_external_total(*, ext_debt_new_disbursements_external: data.Series[float | str | None], ext_debt_new_disbursements_non_residents: data.Series[float | str | None], ext_debt_new_disbursements_residents: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total new public external MLT disbursements.

    Aggregate the detailed new-disbursement series into the total new public external MLT disbursements used by the LIC-DSF external debt template.

    Args:
        ext_debt_new_disbursements_external: Named-axis series of new external disbursements by creditor category (multilaterals, other multilaterals, official bilaterals, commercial).
        ext_debt_new_disbursements_non_residents: Named-axis series of new external disbursements held by non-residents, including locally-issued debt held by non-residents.
        ext_debt_new_disbursements_residents: Named-axis series of new external disbursements held by residents, including debt denominated in foreign currency (FX).

    Returns:
        A named-axis series of total new public external MLT disbursements per projection period; cells are floats, strings, or None.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(xl_add(ext_debt_new_disbursements_external['Multilaterals', time_period], ext_debt_new_disbursements_external['Other Multilaterals', time_period]), ext_debt_new_disbursements_external['Official Bilaterals', time_period]), ext_debt_new_disbursements_external['Commercial', time_period]), ext_debt_new_disbursements_non_residents['Locally-issued debt held by non-residents', time_period]), ext_debt_new_disbursements_residents['Denominated in foreign currency (FX)', time_period]))

    return data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL_TOTAL.collect(evaluate(formula, data.EXT_DEBT_NEW_DISBURSEMENTS_EXTERNAL_TOTAL.required))

@publish(data.EXT_DEBT_NEW_DISBURSEMENTS_PUBLIC_TOTAL.schema, cells=data.EXT_DEBT_NEW_DISBURSEMENTS_PUBLIC_TOTAL.cells)
def ext_debt_new_disbursements_public_total(*, input5_disbursements_total_public_new_domestic_disbursements_residency_based: data.Series[float | str | None], ext_debt_new_disbursements_external_total: data.Series[float | str | None], ext_debt_st_total: data.Series[float | str | None], ext_debt_exchange_rate_period_average: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total public new external and domestic short- and long-term disbursements.

    Aggregates external new disbursements, external short-term debt, and residency-based domestic new disbursements converted at the period-average exchange rate into the public total.

    Args:
        input5_disbursements_total_public_new_domestic_disbursements_residency_based: Public new domestic disbursements on a residency basis from Input 5, as a named-axis data series over catalog coordinates whose cells are float, str, or None.
        ext_debt_new_disbursements_external_total: External new disbursements total, as a named-axis data series over catalog coordinates whose cells are float, str, or None.
        ext_debt_st_total: External short-term debt total, as a named-axis data series over catalog coordinates whose cells are float, str, or None.
        ext_debt_exchange_rate_period_average: Period-average exchange rate used to convert domestic-currency amounts, as a named-axis data series over catalog coordinates whose cells are float, str, or None.

    Returns:
        A named-axis data series over catalog coordinates containing total public new external and domestic short- and long-term disbursements, with float, str, or None cell values.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(ext_debt_new_disbursements_external_total[time_period], ext_debt_st_total[time_period]), xl_div(input5_disbursements_total_public_new_domestic_disbursements_residency_based[time_period], ext_debt_exchange_rate_period_average[time_period])))

    return data.EXT_DEBT_NEW_DISBURSEMENTS_PUBLIC_TOTAL.collect(evaluate(formula, data.EXT_DEBT_NEW_DISBURSEMENTS_PUBLIC_TOTAL.required))

@publish(data.EXT_DEBT_MARGINAL_SHARE_EXTERNAL_PPG_MLT.schema, cells=data.EXT_DEBT_MARGINAL_SHARE_EXTERNAL_PPG_MLT.cells)
def ext_debt_marginal_share_external_ppg_mlt(*, ext_debt_new_disbursements_external_total: data.Series[float | str | None], ext_debt_new_disbursements_public_total: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the yearly marginal share of external PPG medium- and long-term new disbursements relative to total public new disbursements.

    Derive the LIC-DSF external PPG MLT residual-financing share across catalog coordinates from the provided disbursement series.

    Args:
        ext_debt_new_disbursements_external_total: External-total new external debt disbursements, as a data.Series[float | str | None] over catalog coordinates (years).
        ext_debt_new_disbursements_public_total: Public-total new external debt disbursements, as a data.Series[float | str | None] over the same catalog coordinates (years).

    Returns:
        A data.Series[float | str | None] over the shared catalog coordinates giving the per-year external PPG MLT marginal share; each element is the ratio of the external-total series to the public-total series, preserving numeric values and string or None blank markers.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(ext_debt_new_disbursements_external_total[time_period], ext_debt_new_disbursements_public_total[time_period]))

    return data.EXT_DEBT_MARGINAL_SHARE_EXTERNAL_PPG_MLT.collect(evaluate(formula, data.EXT_DEBT_MARGINAL_SHARE_EXTERNAL_PPG_MLT.required))

@publish(key=(), domain=None, cells=data.EXT_DEBT_MARGINAL_SHARE_EXTERNAL_PPG_MLT_AVERAGE_CELLS)
def ext_debt_marginal_share_external_ppg_mlt_average(*, ext_debt_marginal_share_external_ppg_mlt: data.Series[float | str | None]) -> float | str:
    """Compute the average external PPG medium and long-term marginal residual-financing share over 2024–2034.

    Provides a single summary statistic for the external PPG MLT marginal share used in LIC-DSF analysis.

    Args:
        ext_debt_marginal_share_external_ppg_mlt: A data.Series of float, str, or None containing the annual external PPG medium and long-term marginal residual-financing share values across catalog time periods.

    Returns:
        A float representing the average share over the 2024–2034 horizon, or a string error code if the average cannot be computed.
    """
    _ext_debt_marginal_share_external_ppg_mlt_average_table_0 = view(ext_debt_marginal_share_external_ppg_mlt, cols=span(data.TIME_PERIOD_AXIS, 2024, 2034))
    try:
        return as_measure(xl_average(_ext_debt_marginal_share_external_ppg_mlt_average_table_0))
    except XlError as error:
        return error.code

