@publish(data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.schema, cells=data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.cells)
def ext_debt_marginal_share_domestic_mlt(*, input5_disbursements_public_domestic_mlt_disbursements_residency_based: data.Series[float | str | None], ext_debt_new_disbursements_public_total: data.Series[float | str | None], ext_debt_exchange_rate_period_average: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the domestic medium- and long-term marginal share of external debt.

    Convert residency-based domestic MLT disbursements at the period-average exchange rate and divide by total new public external disbursements to obtain the yearly residual-financing share.

    Args:
        input5_disbursements_public_domestic_mlt_disbursements_residency_based: Residency-based domestic medium- and long-term public disbursements, as a yearly data.Series over catalog coordinates.
        ext_debt_new_disbursements_public_total: Total new public external debt disbursements, as a yearly data.Series over catalog coordinates.
        ext_debt_exchange_rate_period_average: Period-average exchange rate used to convert domestic-currency amounts into external-debt terms, as a yearly data.Series over catalog coordinates.

    Returns:
        A data.Series[float | str | None] giving the yearly domestic medium- and long-term marginal external-debt share over the coordinates required by the output series.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_div(input5_disbursements_public_domestic_mlt_disbursements_residency_based[time_period], ext_debt_exchange_rate_period_average[time_period]), ext_debt_new_disbursements_public_total[time_period]))

    return data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.collect(evaluate(formula, data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_MLT.required))

