@publish(data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_ST.schema, cells=data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_ST.cells)
def ext_debt_marginal_share_domestic_st(*, input5_disbursements_public_domestic_st_disbursements_residency_based: data.Series[float | str | None], ext_debt_new_disbursements_public_total: data.Series[float | str | None], ext_debt_exchange_rate_period_average: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the yearly marginal share of domestic short-term disbursements in total new public external debt.

    Derive a residual-financing share that expresses residency-based public domestic short-term disbursements, adjusted by the period-average exchange rate, as a proportion of total new public external debt disbursements.

    Args:
        input5_disbursements_public_domestic_st_disbursements_residency_based: A yearly data.Series over catalog coordinates of residency-based public domestic short-term disbursements from Input 5.
        ext_debt_new_disbursements_public_total: A yearly data.Series over catalog coordinates of total new public external debt disbursements.
        ext_debt_exchange_rate_period_average: A yearly data.Series over catalog coordinates of period-average exchange rates used to convert external debt amounts to domestic currency.

    Returns:
        A yearly data.Series over catalog coordinates of the computed marginal share, containing numeric values, strings, or None per year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_div(input5_disbursements_public_domestic_st_disbursements_residency_based[time_period], ext_debt_exchange_rate_period_average[time_period]), ext_debt_new_disbursements_public_total[time_period]))

    return data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_ST.collect(evaluate(formula, data.EXT_DEBT_MARGINAL_SHARE_DOMESTIC_ST.required))

