@publish(data.EXT_DEBT_RESIDUAL_INTEREST_RATE.schema, cells=data.EXT_DEBT_RESIDUAL_INTEREST_RATE.cells)
def ext_debt_residual_interest_rate(*, input4_interest_rate: data.Input4InterestRate, input4_terms_ida_regular: data.Series[float | str | None], input4_terms_ida_and_lc: data.Series[float | str | None], input4_terms_bonds_fx_non_residents: data.Series[float | str | None], input4_terms_bonds_fx_residents: data.Series[float | str | None], ext_debt_new_disbursements_external: data.Series[float | str | None], ext_debt_new_disbursements_non_residents: data.Series[float | str | None], ext_debt_new_disbursements_residents: data.Series[float | str | None], ext_debt_new_disbursements_external_total: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the yearly residual-financing interest rate on new external debt.

    Derives the weighted average interest rate applied to new external disbursements for LIC-DSF residual financing.

    Args:
        input4_interest_rate: Typed Input 4 interest-rate table series over catalog instrument and indicator coordinates, providing IMF and MULTI interest rates used in the weighted average.
        input4_terms_ida_regular: Typed series of IDA regular financing terms over the instrument axis, including interest-rate values used for IDA regular disbursements.
        input4_terms_ida_and_lc: Typed series of IDA and local-currency financing terms over instrument and indicator coordinates, including interest rates for LC bonds and IDA variants.
        input4_terms_bonds_fx_non_residents: Typed series of FX bond terms for non-resident holders over instrument and indicator coordinates, supplying interest rates for non-resident FX bond disbursements.
        input4_terms_bonds_fx_residents: Typed series of FX bond terms for resident holders over instrument and indicator coordinates, supplying interest rates for resident FX bond disbursements.
        ext_debt_new_disbursements_external: Typed series of new external debt disbursements by instrument and projection year, used as weights with corresponding interest rates.
        ext_debt_new_disbursements_non_residents: Typed series of new external debt disbursements to non-residents by instrument and projection year, used for non-resident FX bond interest-rate weighting.
        ext_debt_new_disbursements_residents: Typed series of new external debt disbursements to residents by instrument and projection year, used for resident FX bond interest-rate weighting.
        ext_debt_new_disbursements_external_total: Typed series of total new external debt disbursements by projection year, serving as the denominator for the weighted-average interest rate.

    Returns:
        Typed yearly data series of residual-financing interest rates over projection years, expressed as percent or an empty string when total new external disbursements are zero.
    """
    data.INPUT4_INTEREST_RATE.schema.validate(input4_interest_rate)
    _ext_debt_residual_interest_rate_table_0 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'))
    _ext_debt_residual_interest_rate_table_1 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'))
    _ext_debt_residual_interest_rate_table_2 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'))
    _ext_debt_residual_interest_rate_table_3 = view(input4_interest_rate, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'))
    _ext_debt_residual_interest_rate_table_4 = view(input4_terms_ida_and_lc, rows=span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=('Interest rate',))
    _ext_debt_residual_interest_rate_table_5 = view(input4_terms_bonds_fx_non_residents, rows={'INSTRUMENT': span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX')}, cols={'HOLDER': ('non-residents',), 'INDICATOR': ('Interest rate',)})
