    _ext_debt_residual_grace_period_table_6 = view(input4_terms_bonds_fx_residents, rows={'INSTRUMENT': span(data.INSTRUMENT_AXIS, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX')}, cols={'HOLDER': ('residents',), 'INDICATOR': ('Grace period',)})
