@publish(data.EXT_DEBT_PV_NEW_MLT_TOTAL.schema, cells=data.EXT_DEBT_PV_NEW_MLT_TOTAL.cells)
def ext_debt_pv_new_mlt_total(*, ext_debt_pv_new_mlt_external: data.Series[float | str | None], ext_debt_pv_new_mlt_non_residents: data.Series[float | str | None], ext_debt_pv_new_mlt_residents: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the total present value of new medium- and long-term external debt.

    Aggregates the component new-MLT debt series into the total PV used by the external DSA engine.

    Args:
        ext_debt_pv_new_mlt_external: Named-axis series of present-value amounts for new medium- and long-term external debt across the multilaterals, other multilaterals, official bilaterals, and commercial creditor categories.
        ext_debt_pv_new_mlt_non_residents: Named-axis series of present-value amounts for new MLT debt classified as locally issued debt held by non-residents.
        ext_debt_pv_new_mlt_residents: Named-axis series of present-value amounts for new MLT debt classified as foreign-currency-denominated debt owed by residents.

    Returns:
        Named-axis series containing the total present value of new medium- and long-term external debt, summed across the component categories over catalog coordinates and projection periods, with blanks and string signals preserved.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(xl_add(ext_debt_pv_new_mlt_external['Multilaterals', time_period], ext_debt_pv_new_mlt_external['Other Multilaterals', time_period]), ext_debt_pv_new_mlt_external['Official Bilaterals', time_period]), ext_debt_pv_new_mlt_external['Commercial', time_period]), ext_debt_pv_new_mlt_non_residents['Locally-issued debt held by non-residents', time_period]), ext_debt_pv_new_mlt_residents['Denominated in foreign currency (FX)', time_period]))

    return data.EXT_DEBT_PV_NEW_MLT_TOTAL.collect(evaluate(formula, data.EXT_DEBT_PV_NEW_MLT_TOTAL.required))

@publish(data.EXT_DEBT_PV_NEW_MLT_EXTERNAL.schema, cells=data.EXT_DEBT_PV_NEW_MLT_EXTERNAL.cells)
def ext_debt_pv_new_mlt_external(*, pv_base_output_pv_of_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of new external MLT debt by financing instrument.

    Aggregate multilateral, bilateral, and commercial instrument components into a single series of the present value of new external MLT debt.

    Args:
        pv_base_output_pv_of_debt: A data.Series of the PV base output by debt instrument and time period, supplying values for 'IDA NEW Blend floating' and acting as a fallback for instruments not covered by explicit aggregation ranges.

    Returns:
        A data.Series of the present value of new external MLT debt by financing instrument over time periods, with values as float, str, or None.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Multilaterals':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'IMF', 'MULTI2'), cols=(time_period,))))
        elif instrument == 'IDA NEW Blend (also enter) -->':
            return as_measure(xl_iferror(lambda: pv_base_output_pv_of_debt['IDA NEW Blend floating', time_period], lambda: 0))
        elif instrument == 'Other Multilaterals':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,))))
        elif instrument == 'Official Bilaterals':
            return as_measure(xl_add(ext_debt_pv_new_mlt_external['Paris Club', time_period], ext_debt_pv_new_mlt_external['Non-Paris Club', time_period]))
        elif instrument == 'Paris Club':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,))))
        elif instrument == 'Non-Paris Club':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,))))
        elif instrument == 'Commercial':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))
        return as_measure(xl_iferror(lambda: pv_base_output_pv_of_debt[instrument, time_period], lambda: 0))

    ext_debt_pv_new_mlt_external = CoordinateReader('ext_debt_pv_new_mlt_external', data.EXT_DEBT_PV_NEW_MLT_EXTERNAL.required, formula)
    return data.EXT_DEBT_PV_NEW_MLT_EXTERNAL.collect((coord, ext_debt_pv_new_mlt_external[coord]) for coord in data.EXT_DEBT_PV_NEW_MLT_EXTERNAL.required)

@publish(data.EXT_DEBT_PV_NEW_MLT_NON_RESIDENTS.schema, cells=data.EXT_DEBT_PV_NEW_MLT_NON_RESIDENTS.cells)
def ext_debt_pv_new_mlt_non_residents(*, pv_base_output_pv_of_debt_fx: data.Series[float | str | None], pv_lc_summary_pv_of_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of new locally-issued debt held by non-residents.

    Assemble the non-resident PV series by resolving local- and foreign-currency bond components over the catalog instrument and time coordinates.

    Args:
        pv_base_output_pv_of_debt_fx: A data.Series[float | str | None] of base-output present values of debt in foreign currency, indexed by instrument, residency, and time period; supplies the fallback and foreign-currency bond components for the non-resident calculation.
        pv_lc_summary_pv_of_debt_in_usd: A data.Series[float | str | None] of local-currency summary present values of debt in USD, indexed by instrument, residency, and time period; supplies the local-currency bond components for the non-resident calculation.

    Returns:
        A data.Series[float | str | None] of present values of new locally-issued debt held by non-residents, aligned to the required instrument and time coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Locally-issued debt held by non-residents':
            return as_measure(xl_add(ext_debt_pv_new_mlt_non_residents['Denominated in local currency (LC)', time_period], ext_debt_pv_new_mlt_non_residents['Denominated in foreign currency (FX)', time_period]))
        elif instrument == 'Denominated in local currency (LC)':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,))))
        elif instrument == 'Denominated in foreign currency (FX)':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        elif instrument in ('Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC'):
            return as_measure(xl_iferror(lambda: pv_lc_summary_pv_of_debt_in_usd[instrument, 'non-residents', time_period], lambda: 0))
        return as_measure(xl_iferror(lambda: pv_base_output_pv_of_debt_fx[instrument, 'non-residents', time_period], lambda: 0))

    ext_debt_pv_new_mlt_non_residents = CoordinateReader('ext_debt_pv_new_mlt_non_residents', data.EXT_DEBT_PV_NEW_MLT_NON_RESIDENTS.required, formula)
    return data.EXT_DEBT_PV_NEW_MLT_NON_RESIDENTS.collect((coord, ext_debt_pv_new_mlt_non_residents[coord]) for coord in data.EXT_DEBT_PV_NEW_MLT_NON_RESIDENTS.required)

@publish(data.EXT_DEBT_PV_NEW_MLT_RESIDENTS.schema, cells=data.EXT_DEBT_PV_NEW_MLT_RESIDENTS.cells)
def ext_debt_pv_new_mlt_residents(*, pv_base_output_pv_of_debt_fx: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of new locally-issued FX debt held by residents.

    Derive resident-held new foreign-currency debt from the PV base output, summing short- and long-maturity FX bonds and defaulting missing base values to zero.

    Args:
        pv_base_output_pv_of_debt_fx: A data.Series[float | str | None] over instrument, residency, and time-period coordinates giving the PV base output of debt denominated in FX; used to source non-bond instruments and as the fallback when the required coordinate is absent.

    Returns:
        A data.Series[float | str | None] of the present value of new locally-issued FX debt held by residents, aligned to the required EXT_DEBT_PV_NEW_MLT_RESIDENTS coordinates and preserving any string or null values from the base series.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Denominated in foreign currency (FX)':
            return as_measure(xl_sum(view(ext_debt_pv_new_mlt_residents, rows=span(data.INSTRUMENT_AXIS_16, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        return as_measure(xl_iferror(lambda: pv_base_output_pv_of_debt_fx[instrument, 'residents', time_period], lambda: 0))

    ext_debt_pv_new_mlt_residents = CoordinateReader('ext_debt_pv_new_mlt_residents', data.EXT_DEBT_PV_NEW_MLT_RESIDENTS.required, formula)
    return data.EXT_DEBT_PV_NEW_MLT_RESIDENTS.collect((coord, ext_debt_pv_new_mlt_residents[coord]) for coord in data.EXT_DEBT_PV_NEW_MLT_RESIDENTS.required)

@publish(data.EXT_DEBT_NOMINAL_NEW_MLT_TOTAL.schema, cells=data.EXT_DEBT_NOMINAL_NEW_MLT_TOTAL.cells)
def ext_debt_nominal_new_mlt_total(*, ext_debt_nominal_new_mlt_external: data.Series[float | str | None], ext_debt_nominal_new_mlt_non_residents: data.Series[float | str | None], ext_debt_nominal_new_mlt_residents: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the total nominal value of new medium- and long-term (MLT) debt.

    Aggregate external, non-resident, and resident foreign-currency components into a single nominal MLT debt total over the catalog coordinates.

    Args:
        ext_debt_nominal_new_mlt_external: Named-axis series of external nominal new MLT debt split by creditor class (multilateral, other multilateral, official bilateral, commercial).
        ext_debt_nominal_new_mlt_non_residents: Named-axis series of nominal new MLT debt locally issued and held by non-residents.
        ext_debt_nominal_new_mlt_residents: Named-axis series of nominal new MLT debt from residents denominated in foreign currency (FX).

    Returns:
        Named-axis data.Series[float | str | None] of total nominal new MLT debt aligned to the catalog coordinates shared by the inputs.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(xl_add(ext_debt_nominal_new_mlt_external['Multilaterals', time_period], ext_debt_nominal_new_mlt_external['Other Multilaterals', time_period]), ext_debt_nominal_new_mlt_external['Official Bilaterals', time_period]), ext_debt_nominal_new_mlt_external['Commercial', time_period]), ext_debt_nominal_new_mlt_non_residents['Locally-issued debt held by non-residents', time_period]), ext_debt_nominal_new_mlt_residents['Denominated in foreign currency (FX)', time_period]))

    return data.EXT_DEBT_NOMINAL_NEW_MLT_TOTAL.collect(evaluate(formula, data.EXT_DEBT_NOMINAL_NEW_MLT_TOTAL.required))

@publish(data.EXT_DEBT_NOMINAL_NEW_MLT_EXTERNAL.schema, cells=data.EXT_DEBT_NOMINAL_NEW_MLT_EXTERNAL.cells)
def ext_debt_nominal_new_mlt_external(*, pv_base_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the nominal value of new external MLT debt by financing instrument.

    Builds the series from PV base output and instrument-level rollups over catalog coordinates.

    Args:
        pv_base_output_stock_of_new_forex_debt_in_usd: Named-axis data.Series[float | str | None] holding the PV base output stock of new foreign-currency debt, indexed by instrument and time period; consumed directly for IMF and fallback rows and summed across instrument spans for multilateral, bilateral, and commercial groupings.

    Returns:
        data.Series[float | str | None] of nominal new external MLT debt by financing instrument across catalog coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF' and time_period >= 2025:
            return as_measure(pv_base_output_stock_of_new_forex_debt_in_usd[instrument, time_period])
        elif instrument == 'Multilaterals':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'IMF', 'MULTI2'), cols=(time_period,))))
        elif instrument == 'IDA NEW Blend (also enter) -->':
            return as_measure(xl_iferror(lambda: pv_base_output_stock_of_new_forex_debt_in_usd['IDA NEW Blend floating', time_period], lambda: 0))
        elif instrument == 'Other Multilaterals':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'OTH_MULTI1', 'OTH_MULTI3'), cols=(time_period,))))
        elif instrument == 'Official Bilaterals':
            return as_measure(xl_add(ext_debt_nominal_new_mlt_external['Paris Club', time_period], ext_debt_nominal_new_mlt_external['Non-Paris Club', time_period]))
        elif instrument == 'Paris Club':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Export Credit Agencies', 'PC5'), cols=(time_period,))))
        elif instrument == 'Non-Paris Club':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Export Import Bank of NPC', 'NPC5'), cols=(time_period,))))
        elif instrument == 'Commercial':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_external, rows=span(data.INSTRUMENT_AXIS, 'Eurobond', 'COM5'), cols=(time_period,))))
        return as_measure(xl_iferror(lambda: pv_base_output_stock_of_new_forex_debt_in_usd[instrument, time_period], lambda: 0))

    ext_debt_nominal_new_mlt_external = CoordinateReader('ext_debt_nominal_new_mlt_external', data.EXT_DEBT_NOMINAL_NEW_MLT_EXTERNAL.required, formula)
    return data.EXT_DEBT_NOMINAL_NEW_MLT_EXTERNAL.collect((coord, ext_debt_nominal_new_mlt_external[coord]) for coord in data.EXT_DEBT_NOMINAL_NEW_MLT_EXTERNAL.required)

@publish(data.EXT_DEBT_NOMINAL_NEW_MLT_NON_RESIDENTS.schema, cells=data.EXT_DEBT_NOMINAL_NEW_MLT_NON_RESIDENTS.cells)
def ext_debt_nominal_new_mlt_non_residents(*, pv_base_output_stock_of_new_forex_debt_in_usd_fx: data.Series[float | str | None], pv_lc_summary_stock_of_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute nominal new medium- and long-term external debt held by non-residents, aggregated by currency denomination and instrument.

    Derives the non-resident new-debt total from local- and foreign-currency bond components for the LIC-DSF external debt template.

    Args:
        pv_base_output_stock_of_new_forex_debt_in_usd_fx: Named-axis series of precomputed base-output stock of new foreign-currency (FX) debt in USD, keyed by instrument, holder category, and time period; missing lookups fall back to zero.
        pv_lc_summary_stock_of_debt_in_usd: Named-axis series of precomputed local-currency (LC) summary stock of debt in USD, keyed by instrument, holder category, and time period; missing lookups fall back to zero.

    Returns:
        Named-axis series of nominal new MLT non-resident debt amounts in USD, aligned to the required instrument-and-time coordinates, with float values, strings, or None where unavailable.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Locally-issued debt held by non-residents':
            return as_measure(xl_add(ext_debt_nominal_new_mlt_non_residents['Denominated in local currency (LC)', time_period], ext_debt_nominal_new_mlt_non_residents['Denominated in foreign currency (FX)', time_period]))
        elif instrument == 'Denominated in local currency (LC)':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-LC', 'Bonds (beyond 7 years)-LC'), cols=(time_period,))))
        elif instrument == 'Denominated in foreign currency (FX)':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_non_residents, rows=span(data.INSTRUMENT_AXIS_15, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        elif instrument in ('Bonds (1 to 3 years)-LC', 'Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC'):
            return as_measure(xl_iferror(lambda: pv_lc_summary_stock_of_debt_in_usd[instrument, 'non-residents', time_period], lambda: 0))
        return as_measure(xl_iferror(lambda: pv_base_output_stock_of_new_forex_debt_in_usd_fx[instrument, 'non-residents', time_period], lambda: 0))

    ext_debt_nominal_new_mlt_non_residents = CoordinateReader('ext_debt_nominal_new_mlt_non_residents', data.EXT_DEBT_NOMINAL_NEW_MLT_NON_RESIDENTS.required, formula)
    return data.EXT_DEBT_NOMINAL_NEW_MLT_NON_RESIDENTS.collect((coord, ext_debt_nominal_new_mlt_non_residents[coord]) for coord in data.EXT_DEBT_NOMINAL_NEW_MLT_NON_RESIDENTS.required)

@publish(data.EXT_DEBT_NOMINAL_NEW_MLT_RESIDENTS.schema, cells=data.EXT_DEBT_NOMINAL_NEW_MLT_RESIDENTS.cells)
def ext_debt_nominal_new_mlt_residents(*, pv_base_output_stock_of_new_forex_debt_in_usd_fx: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the nominal value of new locally-issued FX debt held by residents.

    Derive the external-debt series from aggregated FX bond tenors and a PV-base fallback for non-FX instruments.

    Args:
        pv_base_output_stock_of_new_forex_debt_in_usd_fx: A named-axis data.Series[float | str | None] over catalog coordinates giving the PV-base output stock of new foreign-currency debt in USD FX, used as the fallback for non-FX instruments.

    Returns:
        A named-axis data.Series[float | str | None] over catalog coordinates giving the nominal value of new locally-issued FX debt held by residents, with FX instruments aggregating the relevant bond tenors and non-FX instruments falling back to the PV-base series or zero.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Denominated in foreign currency (FX)':
            return as_measure(xl_sum(view(ext_debt_nominal_new_mlt_residents, rows=span(data.INSTRUMENT_AXIS_16, 'Bonds (1 to 3 years)-FX', 'Bonds (beyond 7 years)-FX'), cols=(time_period,))))
        return as_measure(xl_iferror(lambda: pv_base_output_stock_of_new_forex_debt_in_usd_fx[instrument, 'residents', time_period], lambda: 0))

    ext_debt_nominal_new_mlt_residents = CoordinateReader('ext_debt_nominal_new_mlt_residents', data.EXT_DEBT_NOMINAL_NEW_MLT_RESIDENTS.required, formula)
    return data.EXT_DEBT_NOMINAL_NEW_MLT_RESIDENTS.collect((coord, ext_debt_nominal_new_mlt_residents[coord]) for coord in data.EXT_DEBT_NOMINAL_NEW_MLT_RESIDENTS.required)

@publish(data.EXT_DEBT_ST_EXTERNAL_NOMINAL.schema, cells=data.EXT_DEBT_ST_EXTERNAL_NOMINAL.cells)
def ext_debt_st_external_nominal(*, input3_input_3_external_debt_ppg_st_external_debt_outstanding: data.Input3Input3ExternalDebtPpgStExternalDebtOutstanding) -> data.Series[float | str | None]:
    """Return nominal short-term external debt excluding locally-issued debt.

    Compute the nominal (PV-equivalent) short-term external debt series from Input 3 PPG external debt outstanding data.

    Args:
        input3_input_3_external_debt_ppg_st_external_debt_outstanding: Input 3 public and publicly guaranteed external debt outstanding for short-term external debt, supplied as a typed data series over catalog coordinates.

    Returns:
        A typed data series of nominal short-term external debt values by time period, excluding locally issued debt; each value is a float, string, or None.
    """
    data.INPUT3_INPUT_3_EXTERNAL_DEBT_PPG_ST_EXTERNAL_DEBT_OUTSTANDING.schema.validate(input3_input_3_external_debt_ppg_st_external_debt_outstanding)
    def formula(time_period: int) -> float | str | None:
        return as_measure(input3_input_3_external_debt_ppg_st_external_debt_outstanding[time_period])

    return data.EXT_DEBT_ST_EXTERNAL_NOMINAL.collect(evaluate(formula, data.EXT_DEBT_ST_EXTERNAL_NOMINAL.required))

@publish(data.EXT_DEBT_ST_EXTERNAL_INTEREST.schema, cells=data.EXT_DEBT_ST_EXTERNAL_INTEREST.cells)
def ext_debt_st_external_interest(*, input4_interest_rate: data.Input4InterestRate, ext_debt_st_external_nominal: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute short-term external debt interest excluding locally issued debt.

    Derive the short-term external interest series by applying the Input 4 PPG short-term external debt rate to the lagged nominal short-term external debt stock.

    Args:
        input4_interest_rate: Input 4 interest-rate series over catalog coordinates, supplying the PPG short-term external debt rate used to accrue interest.
        ext_debt_st_external_nominal: Short-term external debt nominal stock series over catalog coordinates; each value is lagged one period when multiplied by the interest rate.

    Returns:
        A data.Series[float | str | None] of short-term external interest over catalog coordinates, computed as prior-period short-term external debt times the PPG short-term external debt interest rate.
    """
    data.INPUT4_INTEREST_RATE.schema.validate(input4_interest_rate)
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(ext_debt_st_external_nominal[time_period - 1], input4_interest_rate['PPG ST external debt']))

    return data.EXT_DEBT_ST_EXTERNAL_INTEREST.collect(evaluate(formula, data.EXT_DEBT_ST_EXTERNAL_INTEREST.required))

@publish(data.EXT_DEBT_ST_LOCALLY_ISSUED_NOMINAL.schema, cells=data.EXT_DEBT_ST_LOCALLY_ISSUED_NOMINAL.cells)
def ext_debt_st_locally_issued_nominal(*, input5_new_debt_principal_payments_on_new_debt_denominated_in_foreign_currency_ow_short_term: data.Series[float | str | None], input5_new_debt_principal_payments_on_new_debt_denominated_in_local_currency_ow_short_term: data.Series[float | str | None], ext_debt_definition_external_domestic: str | int | float | bool, ext_debt_exchange_rate_eop: data.Series[float | str | None], lookup_afg: str | int | float | bool) -> data.Series[float | str | None]:
    """Compute nominal locally-issued short-term external debt.

    Derive the nominal (PV-equivalent) stock of locally issued short-term external debt from Input 5 principal-payment series and end-of-period exchange rates.

    Args:
        input5_new_debt_principal_payments_on_new_debt_denominated_in_foreign_currency_ow_short_term: A data.Series[float | str | None] named-axis tensor of Input 5 new-debt principal payments on short-term new debt denominated in foreign currency, over catalog coordinates.
        input5_new_debt_principal_payments_on_new_debt_denominated_in_local_currency_ow_short_term: A data.Series[float | str | None] named-axis tensor of Input 5 new-debt principal payments on short-term new debt denominated in local currency, over catalog coordinates.
        ext_debt_definition_external_domestic: Scalar (str | int | float | bool) selecting the external versus domestic debt definition; its equality with the lookup sentinel chooses whether local- and foreign-currency payments are combined or only foreign-currency resident payments are converted.
        ext_debt_exchange_rate_eop: A data.Series[float | str | None] named-axis tensor of end-of-period exchange rates used to convert short-term debt principal payments into nominal terms.
        lookup_afg: Scalar (str | int | float | bool) lookup/definition sentinel compared with the external versus domestic debt-definition selector.

    Returns:
        A data.Series[float | str | None] of nominal (PV-equivalent) locally-issued short-term external debt across projection years, preserving missing or blank results as None or text.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2044:
            return as_measure((xl_div(xl_add(None, None), ext_debt_exchange_rate_eop[time_period]) if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else xl_div(None, ext_debt_exchange_rate_eop[time_period])))
        return as_measure((xl_div(xl_add(input5_new_debt_principal_payments_on_new_debt_denominated_in_local_currency_ow_short_term['non-residents', time_period + 1], input5_new_debt_principal_payments_on_new_debt_denominated_in_foreign_currency_ow_short_term['non-residents', time_period + 1]), ext_debt_exchange_rate_eop[time_period]) if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else xl_div(input5_new_debt_principal_payments_on_new_debt_denominated_in_foreign_currency_ow_short_term['residents', time_period + 1], ext_debt_exchange_rate_eop[time_period])))

    return data.EXT_DEBT_ST_LOCALLY_ISSUED_NOMINAL.collect(evaluate(formula, data.EXT_DEBT_ST_LOCALLY_ISSUED_NOMINAL.required))

@publish(data.EXT_DEBT_ST_TOTAL.schema, cells=data.EXT_DEBT_ST_TOTAL.cells)
def ext_debt_st_total(*, ext_debt_st_external_nominal: data.Series[float | str | None], ext_debt_st_locally_issued_nominal: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total short-term external debt including locally-issued.

    Aggregates external and locally-issued short-term external debt series into a total series.

    Args:
        ext_debt_st_external_nominal: Short-term external debt from external sources, as a data.Series over catalog coordinates.
        ext_debt_st_locally_issued_nominal: Short-term external debt issued locally, as a data.Series over catalog coordinates.

    Returns:
        Total short-term external debt including locally-issued, as a data.Series over the same coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(ext_debt_st_external_nominal[time_period], ext_debt_st_locally_issued_nominal[time_period]))

    return data.EXT_DEBT_ST_TOTAL.collect(evaluate(formula, data.EXT_DEBT_ST_TOTAL.required))

@publish(data.EXT_DEBT_PV_NET_USE_OF_SDRS.schema, cells=data.EXT_DEBT_PV_NET_USE_OF_SDRS.cells)
def ext_debt_pv_net_use_of_sdrs(*, in8_sdr_pv_of_interest_payments_in_million_of_usd: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute the external-debt present value of net use of SDRs.

    Aligns the Input 8 SDR interest-payment present-value series to the external-debt PV net SDR use output via authored coordinate identities.

    Args:
        in8_sdr_pv_of_interest_payments_in_million_of_usd: SDR present value of interest payments in millions of USD as data.Series[int | str | None] over catalog coordinates.

    Returns:
        External-debt present value of net use of SDRs as data.Series[float | str | None] over catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(in8_sdr_pv_of_interest_payments_in_million_of_usd[time_period])

    return data.EXT_DEBT_PV_NET_USE_OF_SDRS.collect(evaluate(formula, data.EXT_DEBT_PV_NET_USE_OF_SDRS.required))

@publish(data.EXT_DEBT_TOTAL_PV_OF_DEBT.schema, cells=data.EXT_DEBT_TOTAL_PV_OF_DEBT.cells)
def ext_debt_total_pv_of_debt(*, ext_debt_pv_old_mlt_total: data.Series[float | str | None], ext_debt_pv_existing_arrears: data.Series[float | str | None], ext_debt_pv_new_mlt_total: data.Series[float | str | None], ext_debt_st_total: data.Series[float | str | None], ext_debt_pv_net_use_of_sdrs: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the total present value of PPG external debt.

    Aggregates the component external debt series into the LIC-DSF total over catalog coordinates.

    Args:
        ext_debt_pv_old_mlt_total: A `data.Series` of the present value of legacy multilateral long-term external debt.
        ext_debt_pv_existing_arrears: A `data.Series` of the present value of existing external arrears.
        ext_debt_pv_new_mlt_total: A `data.Series` of the present value of new multilateral long-term external debt.
        ext_debt_st_total: A `data.Series` of the total external short-term debt stock.
        ext_debt_pv_net_use_of_sdrs: A `data.Series` of the present value of net use of IMF SDR allocations.

    Returns:
        A `data.Series[float | str | None]` aligned to the external debt total coordinates, containing the summed total present value of PPG external debt per period with string and `None` values propagated.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(xl_add(xl_add(ext_debt_pv_old_mlt_total[time_period], ext_debt_pv_existing_arrears[time_period]), ext_debt_pv_new_mlt_total[time_period]), ext_debt_st_total[time_period]), ext_debt_pv_net_use_of_sdrs[time_period]))

    return data.EXT_DEBT_TOTAL_PV_OF_DEBT.collect(evaluate(formula, data.EXT_DEBT_TOTAL_PV_OF_DEBT.required))

@publish(data.EXT_DEBT_TOTAL_PUBLIC_DEBT_SERVICE.schema, cells=data.EXT_DEBT_TOTAL_PUBLIC_DEBT_SERVICE.cells)
def ext_debt_total_public_debt_service(*, ext_debt_public_debt_service_principal: data.Series[float | str | None], ext_debt_public_debt_service_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total external public debt service as the sum of principal and interest.

    Derive the combined public debt service series from its principal and interest components.

    Args:
        ext_debt_public_debt_service_principal: Principal component of external public debt service, supplied as a typed data series over catalog coordinates.
        ext_debt_public_debt_service_interest: Interest component of external public debt service, supplied as a typed data series over catalog coordinates.

    Returns:
        Typed data series of total external public debt service over the common catalog coordinates, preserving float, string, or missing values.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(ext_debt_public_debt_service_principal[time_period], ext_debt_public_debt_service_interest[time_period]))

    return data.EXT_DEBT_TOTAL_PUBLIC_DEBT_SERVICE.collect(evaluate(formula, data.EXT_DEBT_TOTAL_PUBLIC_DEBT_SERVICE.required))

@publish(data.EXT_DEBT_PUBLIC_DEBT_SERVICE_PRINCIPAL.schema, cells=data.EXT_DEBT_PUBLIC_DEBT_SERVICE_PRINCIPAL.cells)
def ext_debt_public_debt_service_principal(*, ext_debt_total_principal: data.Series[float | str | None], ext_debt_new_amortization_total: data.Series[float | str | None], ext_debt_st_total_principal: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the principal component of external public debt service by summing total, new-amortization, and short-term principal streams.

    Combine the three external-debt principal series into the principal component of public debt service used by the LIC-DSF debt-service calculations.

    Args:
        ext_debt_total_principal: Total principal of external public and publicly guaranteed debt by projection year, carried as a named-axis series over catalog coordinates; empty or template cells remain as None or text rather than numeric zeros.
        ext_debt_new_amortization_total: New amortization principal of external debt over the projection horizon, carried as the same named-axis series, with blanks and template snapshots preserved.
        ext_debt_st_total_principal: Short-term external debt principal over the projection horizon, carried as the same named-axis series, with blanks and template snapshots preserved.

    Returns:
        A data.Series[float | str | None] aligned to the external public debt service principal coordinate axis, holding the element-wise sum of the three principal inputs for the required periods, with blanks and text values passed through unchanged.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(ext_debt_total_principal[time_period], ext_debt_new_amortization_total[time_period]), ext_debt_st_total_principal[time_period]))

