@publish(data.EXT_DEBT_EXTERNAL_DEBT_OUTSTANDING.schema, cells=data.EXT_DEBT_EXTERNAL_DEBT_OUTSTANDING.cells)
def ext_debt_external_debt_outstanding(*, ext_debt_stock_of_outstanding_arrears: data.Series[float | str | None], ext_debt_old_mlt_stock_evolution: data.Series[float | str | None], ext_debt_nominal_new_mlt_total: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute external debt outstanding from new MLT nominal total, outstanding arrears stock, and old MLT stock evolution.

    Aggregate the three external-debt components into the catalog’s external debt outstanding series.

    Args:
        ext_debt_stock_of_outstanding_arrears: Named-axis data.Series[float | str | None] over catalog coordinates giving the stock of outstanding external debt arrears, indexed by time period.
        ext_debt_old_mlt_stock_evolution: Named-axis data.Series[float | str | None] over catalog coordinates giving the old MLT external debt stock evolution, indexed by time period.
        ext_debt_nominal_new_mlt_total: Named-axis data.Series[float | str | None] over catalog coordinates giving the nominal new MLT external debt total, indexed by time period.

    Returns:
        A named-axis data.Series[float | str | None] over the required catalog coordinates holding external debt outstanding, computed as the sum of nominal new MLT total, stock of outstanding arrears, and old MLT stock evolution.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(xl_add(ext_debt_nominal_new_mlt_total[time_period], ext_debt_stock_of_outstanding_arrears[time_period]), ext_debt_old_mlt_stock_evolution[time_period]))

    return data.EXT_DEBT_EXTERNAL_DEBT_OUTSTANDING.collect(evaluate(formula, data.EXT_DEBT_EXTERNAL_DEBT_OUTSTANDING.required))

@publish(data.EXT_DEBT_FX_DENOMINATED_DEBT_OUTSTANDING.schema, cells=data.EXT_DEBT_FX_DENOMINATED_DEBT_OUTSTANDING.cells)
def ext_debt_fx_denominated_debt_outstanding(*, input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd: data.Series[float | str | None], input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency: data.Series[float | str | None], ext_debt_old_mlt_evolution: data.Series[float | str | None], ext_debt_stock_of_outstanding_arrears: data.Series[float | str | None], ext_debt_definition_external_domestic: str | int | float | bool, ext_debt_nominal_new_mlt_external: data.Series[float | str | None], ext_debt_nominal_new_mlt_non_residents: data.Series[float | str | None], ext_debt_st_external_nominal: data.Series[float | str | None], ext_debt_external_debt_outstanding: data.Series[float | str | None], ext_debt_exchange_rate_eop: data.Series[float | str | None], lookup_afg: str | int | float | bool) -> data.Series[float | str | None]:
    """Compute FX-denominated external debt outstanding.

    Aggregates old and new external debt components into FX-denominated debt outstanding, using the external-versus-domestic definition branch.

    Args:
        input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd: Foreign-currency-denominated old debt outstanding in USD, as a named-axis data series over catalog coordinates.
        input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency: Stock of new debt denominated in foreign currency, as a named-axis data series over catalog coordinates.
        ext_debt_old_mlt_evolution: Evolution of old medium- and long-term external debt, as a named-axis data series over catalog coordinates.
        ext_debt_stock_of_outstanding_arrears: Stock of outstanding external debt arrears, as a named-axis data series over catalog coordinates.
        ext_debt_definition_external_domestic: Scalar definition selector distinguishing external from domestic debt, compared against the lookup value to choose the computation branch.
        ext_debt_nominal_new_mlt_external: Nominal new medium- and long-term external debt across creditor categories, as a named-axis data series over catalog coordinates.
        ext_debt_nominal_new_mlt_non_residents: Nominal new medium- and long-term debt owed to non-residents, as a named-axis data series over catalog coordinates.
        ext_debt_st_external_nominal: Nominal short-term external debt, as a named-axis data series over catalog coordinates.
        ext_debt_external_debt_outstanding: External debt outstanding, as a named-axis data series over catalog coordinates, used directly when the definition branch does not match.
        ext_debt_exchange_rate_eop: End-of-period exchange rate, as a named-axis data series over catalog coordinates.
        lookup_afg: Scalar lookup reference value used in the external-versus-domestic definition test.

    Returns:
        A data.Series[float | str | None] of FX-denominated external debt outstanding over catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_add(xl_sub(ext_debt_old_mlt_evolution[time_period], xl_sub(ext_debt_stock_of_outstanding_arrears[time_period], ext_debt_stock_of_outstanding_arrears[time_period - 1])), input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['residents', time_period]), input5_old_debt_outstanding_from_old_debt_in_foreign_currency_usd['non-residents', time_period]), ext_debt_nominal_new_mlt_external['Multilaterals', time_period]), ext_debt_nominal_new_mlt_external['Other Multilaterals', time_period]), ext_debt_nominal_new_mlt_external['Official Bilaterals', time_period]), ext_debt_nominal_new_mlt_external['Commercial', time_period]), ext_debt_nominal_new_mlt_non_residents['Denominated in foreign currency (FX)', time_period]), ext_debt_st_external_nominal[time_period]), xl_div(input5_new_debt_debt_stock_on_new_debt_denominated_in_foreign_currency['residents', time_period], ext_debt_exchange_rate_eop[time_period])) if xl_bool(xl_eq(ext_debt_definition_external_domestic, lookup_afg)) else ext_debt_external_debt_outstanding[time_period]))

    return data.EXT_DEBT_FX_DENOMINATED_DEBT_OUTSTANDING.collect(evaluate(formula, data.EXT_DEBT_FX_DENOMINATED_DEBT_OUTSTANDING.required))

