def imported_country_code(*, in1_basics_country_code: int | str) -> int | str:
    """Return the IMF country code copied from Input 1 as an integer or string scalar.

    Expose the authored identity for Input 1's country code within the LIC-DSF internals.

    Args:
        in1_basics_country_code: IMF country code copied from Input 1, provided as an integer or string scalar.

    Returns:
        The IMF country code as an integer or string scalar; if measurement fails, the relevant XlError code is returned instead.
    """
    try:
        return as_measure(in1_basics_country_code, 'int')
    except XlError as error:
        return error.code

@publish(data.IMPORTED_CLASSIFICATION_YEARS.schema, cells=data.IMPORTED_CLASSIFICATION_YEARS.cells)
def imported_classification_years(*, classification_cpia_reported_years: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute imported classification years aligned to the projection vintage.

    Extend the CPIA reported classification years across the template's projected classification window using the 2024 anchor.

    Args:
        classification_cpia_reported_years: data.Series[int | str | None] of classification-window years aligned to the projection vintage on row 37.

    Returns:
        data.Series[int | str | None] of classification-window years aligned to the projection vintage on row 37.
    """
    data.CLASSIFICATION_CPIA_REPORTED_YEARS.schema.validate(classification_cpia_reported_years)
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(classification_cpia_reported_years[2024], 'int')
        elif time_period >= 2025:
            return as_measure(xl_add(imported_classification_years[time_period - 1], 1), 'int')
        return as_measure(xl_sub(imported_classification_years[time_period + 1], 1), 'int')

    imported_classification_years = CoordinateReader('imported_classification_years', data.IMPORTED_CLASSIFICATION_YEARS.required, formula)
    return data.IMPORTED_CLASSIFICATION_YEARS.collect((coord, imported_classification_years[coord]) for coord in data.IMPORTED_CLASSIFICATION_YEARS.required)

