@publish(data.IMPORTED_CLASSIFICATION_IDS.schema, cells=data.IMPORTED_CLASSIFICATION_IDS.cells)
def imported_classification_ids(*, imported_series_stub_cpia: str, imported_series_stub_gr_a: str, imported_series_stub_res_a: str, imported_series_stub_wgr: str, imported_components: data.Series[int | str | None]) -> data.Series[str | int | float | bool | None]:
    """Build imported classification lookup IDs by concatenating indicator-specific prefix stubs with component values.

    Produces INDEX/MATCH-ready classification keys over the required imported-classification coordinates.

    Args:
        imported_series_stub_cpia: String prefix for CPIA classification lookup keys.
        imported_series_stub_gr_a: String prefix for real growth rate classification lookup keys.
        imported_series_stub_res_a: String prefix for import coverage of reserves classification lookup keys.
        imported_series_stub_wgr: String prefix used as the fallback for other indicator classification lookup keys.
        imported_components: Typed data.Series of component values over catalog coordinates, concatenated with the matching indicator prefix to form each lookup key.

    Returns:
        Typed data.Series[str | int | float | bool | None] of constructed classification lookup keys over the required imported-classification coordinates.
    """
    def formula(indicator: str, time_period: int) -> str | int | float | bool | None:
        if indicator == 'CPIA':
            return as_measure(xl_concat(imported_series_stub_cpia, imported_components[time_period]), 'str')
        elif indicator == 'Real growth rate \n(in percent)':
            return as_measure(xl_concat(imported_series_stub_gr_a, imported_components[time_period]), 'str')
        elif indicator == 'Import coverage of reserves\n(in percent)':
            return as_measure(xl_concat(imported_series_stub_res_a, imported_components[time_period]), 'str')
        return as_measure(xl_concat(imported_series_stub_wgr, imported_components[time_period]), 'str')

    return data.IMPORTED_CLASSIFICATION_IDS.collect(evaluate(formula, data.IMPORTED_CLASSIFICATION_IDS.required))

