@publish(data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.schema, cells=data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.cells)
def realism1_public_current_vintage_projection(*, display_scale: str, baseline_pub_historical_indicators: data.Series[float | str | None], baseline_pub_year_before_projection: data.Series[float | str | None], baseline_pub_public_sector_debt: data.Series[float | str | None], baseline_pub_change_in_public_sector_debt: data.Series[float | str | None], baseline_pub_primary_deficit: data.Series[float | str | None], baseline_pub_of_which_contribution_from_average_real: data.Series[float | str | None], baseline_pub_of_which_contribution_from_real_gdp_growth: data.Series[float | str | None], baseline_pub_contribution_from_real_exchange_rate: data.Series[float | str | None], baseline_pub_other_identified_debt_creating_flows: data.Series[float | str | None], baseline_pub_residual: data.Series[float | str | None], baseline_pub_nominal_gdp_lc: data.Series[float | str | None], lookup_country_scale_phrase: data.Series[str | int | float | bool | None]) -> data.Series[float | str | None]:
    """Compute the Realism 1 public current-vintage debt projection.

    Assemble baseline public-debt indicator paths across historical, pre-projection, and projection years.

    Args:
        display_scale: A scalar string display scale label used to select country-specific scaling for local-currency nominal GDP.
        baseline_pub_historical_indicators: A data.Series[float | str | None] of historical public-debt indicators over named indicator and year coordinates.
        baseline_pub_year_before_projection: A data.Series[float | str | None] of public-debt indicators for the year immediately before the projection horizon.
        baseline_pub_public_sector_debt: A data.Series[float | str | None] of public sector debt ratios or fallback public sector debt values over named indicator and year coordinates.
        baseline_pub_change_in_public_sector_debt: A data.Series[float | str | None] of changes in public sector debt, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_primary_deficit: A data.Series[float | str | None] of primary deficit values, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_of_which_contribution_from_average_real: A data.Series[float | str | None] of contributions from the average real interest rate, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_of_which_contribution_from_real_gdp_growth: A data.Series[float | str | None] of contributions from real GDP growth, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_contribution_from_real_exchange_rate: A data.Series[float | str | None] of contributions from real exchange rate depreciation, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_other_identified_debt_creating_flows: A data.Series[float | str | None] of other identified debt-creating flows, in percent of GDP, over named indicator and year coordinates.
        baseline_pub_residual: A data.Series[float | str | None] of residual debt-creating flows over named indicator and year coordinates.
        baseline_pub_nominal_gdp_lc: A data.Series[float | str | None] of nominal GDP values in local currency over named indicator and year coordinates.
        lookup_country_scale_phrase: A data.Series[str | int | float | bool | None] lookup mapping country scale phrase keys to values used to determine whether local-currency GDP is rescaled.

    Returns:
        A data.Series[float | str | None] of the current-vintage public debt projection in local currency, by indicator and year.
    """
    def formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection['of which: contribution from average real interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection['of which: contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection['Contribution from real exchange rate depreciation', time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection['Change in public sector debt', time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection['Other identified debt-creating flows', time_period])
        elif indicator == 'Residual' and time_period == 2023:
            return as_measure(baseline_pub_year_before_projection[indicator, time_period])
        elif indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['of which: contribution from average real interest rate', time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['of which: contribution from real GDP growth', time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['Contribution from real exchange rate depreciation', time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['Change in public sector debt', time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['Other identified debt-creating flows', time_period])
        elif indicator == 'Residual' and 2019 <= time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators[indicator, time_period])
        elif indicator == 'of which: contribution from average real interest rate (in percent of GDP)' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_of_which_contribution_from_average_real[time_period])
        elif indicator == 'of which: contribution from real GDP growth (in percent of GDP)' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_of_which_contribution_from_real_gdp_growth[time_period])
        elif indicator == 'Contribution from real exchange rate depreciation (in percent of GDP)' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_contribution_from_real_exchange_rate[time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_change_in_public_sector_debt[time_period])
        elif indicator == 'Other identified debt-creating flows (in percent of GDP)' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_other_identified_debt_creating_flows[time_period])
        elif indicator == 'Residual' and 2024 <= time_period <= 2028:
            return as_measure(baseline_pub_residual[time_period])
        elif indicator == 'Nominal GDP (in billions of local currency)' and time_period <= 2022:
            return as_measure((xl_div(baseline_pub_nominal_gdp_lc[time_period], 1000) if xl_bool(xl_eq(display_scale, lookup_country_scale_phrase['CPV'])) else baseline_pub_nominal_gdp_lc[time_period]))
        elif indicator == 'Public sector debt (in percent of GDP)' and time_period <= 2022:
            return as_measure(baseline_pub_historical_indicators['Public sector debt 1/', time_period])
        elif indicator == 'Primary deficit (in percent of GDP)' and 2019 <= time_period <= 2028:
            return as_measure(baseline_pub_primary_deficit[time_period])
        return as_measure(baseline_pub_public_sector_debt[time_period])

    return data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.collect(evaluate(formula, data.REALISM1_PUBLIC_CURRENT_VINTAGE_PROJECTION.required))

