def scan_realism1_public_five_years_ago_rebased_projection(*, realism1_public_current_vintage_projection: data.Series[float | str | None], realism1_public_five_years_ago_projection: data.Series[float | str | None]) -> ScanRealism1PublicFiveYearsAgoRebasedProjectionResult:
    """Evaluate the recurrence group `realism1_public_five_years_ago_rebased_projection`, `realism1_public_lc_rebase_factors` and publish complete tensors."""
    def realism1_public_five_years_ago_rebased_projection_formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'Nominal GDP (in billions of local currency)' and time_period == 2017:
            return as_measure(realism1_public_current_vintage_projection[indicator, time_period])
        elif indicator == 'Change in public sector debt (in percent of GDP)' and 2019 <= time_period <= 2023:
            return as_measure(xl_sub(xl_mul(realism1_public_five_years_ago_projection['Public sector debt (in percent of GDP)', time_period], realism1_public_lc_rebase_factors['r: ratio of Old GDP / New GDP', time_period]), xl_mul(realism1_public_five_years_ago_projection['Public sector debt (in percent of GDP)', time_period - 1], realism1_public_lc_rebase_factors['r: ratio of Old GDP / New GDP', time_period - 1])))
        elif indicator == 'Residual' and 2019 <= time_period <= 2023:
            return as_measure(xl_sub(xl_sub(xl_sub(xl_sub(xl_sub(realism1_public_five_years_ago_rebased_projection['Change in public sector debt (in percent of GDP)', time_period], realism1_public_five_years_ago_rebased_projection['of which: contribution from average real interest rate (in percent of GDP)', time_period]), realism1_public_five_years_ago_rebased_projection['of which: contribution from real GDP growth (in percent of GDP)', time_period]), realism1_public_five_years_ago_rebased_projection['Contribution from real exchange rate depreciation (in percent of GDP)', time_period]), realism1_public_five_years_ago_rebased_projection['Other identified debt-creating flows (in percent of GDP)', time_period]), realism1_public_five_years_ago_rebased_projection['Primary deficit (in percent of GDP)', time_period]))
        elif indicator in ('of which: contribution from average real interest rate (in percent of GDP)', 'of which: contribution from real GDP growth (in percent of GDP)', 'Contribution from real exchange rate depreciation (in percent of GDP)') and 2019 <= time_period <= 2023:
            return as_measure(xl_mul(realism1_public_five_years_ago_projection[indicator, time_period], realism1_public_lc_rebase_factors['r: ratio of Old GDP / New GDP', time_period - 1]))
        elif indicator == 'Nominal GDP (in billions of local currency)' and time_period >= 2018:
            return as_measure(xl_mul(realism1_public_five_years_ago_rebased_projection[indicator, time_period - 1], xl_add(1, realism1_public_lc_rebase_factors['g: Nominal GDP growth (LC)', time_period])))
        return as_measure(xl_mul(realism1_public_five_years_ago_projection[indicator, time_period], realism1_public_lc_rebase_factors['r: ratio of Old GDP / New GDP', time_period]))

    realism1_public_five_years_ago_rebased_projection = CoordinateReader('realism1_public_five_years_ago_rebased_projection', data.REALISM1_PUBLIC_FIVE_YEARS_AGO_REBASED_PROJECTION.required, realism1_public_five_years_ago_rebased_projection_formula)
    def realism1_public_lc_rebase_factors_formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'g: Nominal GDP growth (LC)' and time_period >= 2018:
            return as_measure(xl_sub(xl_div(realism1_public_five_years_ago_projection['Nominal GDP (in billions of local currency)', time_period], realism1_public_five_years_ago_projection['Nominal GDP (in billions of local currency)', time_period - 1]), 1))
        return as_measure(xl_div(realism1_public_five_years_ago_projection['Nominal GDP (in billions of local currency)', time_period], realism1_public_five_years_ago_rebased_projection['Nominal GDP (in billions of local currency)', time_period]))

    realism1_public_lc_rebase_factors = CoordinateReader('realism1_public_lc_rebase_factors', data.REALISM1_PUBLIC_LC_REBASE_FACTORS.required, realism1_public_lc_rebase_factors_formula)
    return ScanRealism1PublicFiveYearsAgoRebasedProjectionResult(
        realism1_public_five_years_ago_rebased_projection=data.REALISM1_PUBLIC_FIVE_YEARS_AGO_REBASED_PROJECTION.collect((coord, realism1_public_five_years_ago_rebased_projection[coord]) for coord in data.REALISM1_PUBLIC_FIVE_YEARS_AGO_REBASED_PROJECTION.required),
        realism1_public_lc_rebase_factors=data.REALISM1_PUBLIC_LC_REBASE_FACTORS.collect((coord, realism1_public_lc_rebase_factors[coord]) for coord in data.REALISM1_PUBLIC_LC_REBASE_FACTORS.required),
    )

