@publish(data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.schema, cells=data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.cells)
def realism1_external_five_year_flow_changes(*, realism1_external_five_years_ago_rebased_projection: data.Series[float | str | None], realism1_external_private_debt_rebased_change: data.Series[float | str | None], realism1_external_debt_creating_flows: data.Realism1ExternalDebtCreatingFlows) -> data.Series[float | str | None]:
    """Compute five-year historical, projected, and difference flow changes for external debt under Realism 1.

    Supports external debt realism diagnostics by assembling aligned five-year change series over catalog coordinates.

    Args:
        realism1_external_five_years_ago_rebased_projection: data.Series[float | str | None] of rebased external projection contributions, including nominal interest, real GDP growth, price and exchange-rate changes, and PPG debt, aligned to catalog time coordinates.
        realism1_external_private_debt_rebased_change: data.Series[float | str | None] of rebased private-debt changes used to derive residual five-year projected changes.
        realism1_external_debt_creating_flows: data.Realism1ExternalDebtCreatingFlows dataclass of external debt-creating flow series across indicators and change variants.

    Returns:
        data.Series[float | str | None] containing the five-year historical change, five-year projected change, and their difference for external debt indicators.
    """
    _realism1_external_five_year_flow_changes_table_0 = view(realism1_external_five_years_ago_rebased_projection, rows=('Contribution from nominal interest rate (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_five_year_flow_changes_table_1 = view(realism1_external_five_years_ago_rebased_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_five_year_flow_changes_table_2 = view(realism1_external_five_years_ago_rebased_projection, rows=('Contribution from price and exchange rate changes (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_five_year_flow_changes_table_3 = view(realism1_external_private_debt_rebased_change, cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Current account + FDI' and variant == '5-year projected change':
            return as_measure(xl_sum(view(realism1_external_five_years_ago_rebased_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))))
        elif indicator == 'Nominal interest rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_0))
        elif indicator == 'Real GDP growth' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_1))
        elif indicator == 'Price and exchange rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_five_year_flow_changes_table_2))
        elif indicator == 'Change in PPG debt 3/' and variant == '5-year projected change':
            return as_measure(xl_sub(realism1_external_five_years_ago_rebased_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2023], realism1_external_five_years_ago_rebased_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2018]))
        elif indicator == 'Residual' and variant == '5-year projected change':
            return as_measure(xl_sub(xl_sum(view(realism1_external_five_years_ago_rebased_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))), xl_sum(_realism1_external_five_year_flow_changes_table_3)))
        elif variant == '5-year historical change':
            return as_measure(realism1_external_debt_creating_flows[indicator, variant])
        return as_measure(xl_sub(realism1_external_five_year_flow_changes[indicator, '5-year historical change'], realism1_external_five_year_flow_changes[indicator, '5-year projected change']))

    realism1_external_five_year_flow_changes = CoordinateReader('realism1_external_five_year_flow_changes', data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.required, formula)
    return data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.collect((coord, realism1_external_five_year_flow_changes[coord]) for coord in data.REALISM1_EXTERNAL_FIVE_YEAR_FLOW_CHANGES.required)

@publish(data.REALISM1_PUBLIC_FORECAST_ERROR_COMPONENT_NAMES.schema, cells=data.REALISM1_PUBLIC_FORECAST_ERROR_COMPONENT_NAMES.cells)
def realism1_public_forecast_error_component_names(*, realism1_public_debt_flow_components: data.Realism1PublicDebtFlowComponents) -> data.Series[str | int | float | bool | None]:
    """Return the public-debt forecast-error component names.

    Builds a typed series naming the Realism 1 public-debt forecast-error components from the provided flow component measures.

    Args:
        realism1_public_debt_flow_components: Keyword-only public-debt flow component series whose indicator measures supply the forecast-error component names.

    Returns:
        A data.Series of the public-debt forecast-error component names, with each value a str, int, float, bool, or None.
    """
    def formula(indicator: str) -> str | int | float | bool | None:
        return as_measure(realism1_public_debt_flow_components[indicator], 'str')

