    data.TRANSLATION_INPUT_2_DEBT_COVERAGE_EXTERNAL_DEBT_BURDEN_THRESHOLDS.schema.validate(translation_input_2_debt_coverage_external_debt_burden_thresholds)
    try:
        return as_measure((translation_input_2_debt_coverage_external_debt_burden_thresholds['English'] if xl_bool(xl_eq(start_debt_sustainability_analysis, 'English')) else (translation_input_2_debt_coverage_external_debt_burden_thresholds['French'] if xl_bool(xl_eq(start_debt_sustainability_analysis, 'French')) else (translation_input_2_debt_coverage_external_debt_burden_thresholds['Portuguese'] if xl_bool(xl_eq(start_debt_sustainability_analysis, 'Portuguese')) else translation_input_2_debt_coverage_external_debt_burden_thresholds['Spanish']))), 'str')
    except XlError as error:
        return error.code

