@publish(data.CI_SUMMARY_INDEX_COMPONENTS.schema, cells=data.CI_SUMMARY_INDEX_COMPONENTS.cells)
def ci_summary_index_components(*, ci_probit_coefficients: data.Series[float | str | None], ci_summary_components_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute CI summary index components from probit coefficients and annual summary series.

    Derives each indicator's coefficient, ten-year average, and weighted contribution as a series over the CI summary coordinate catalog.

    Args:
        ci_probit_coefficients: CI probit coefficient series over probit-row and indicator-coordinate axes, providing the per-indicator coefficient inputs.
        ci_summary_components_by_year: Annual CI summary components series over time-period and indicator-coordinate axes, providing ten-year averages for the index components.

    Returns:
        Series of CI summary index components over the CI summary coordinate catalog, containing per-indicator coefficients, ten-year averages, and weighted contributions.
    """
    data.CI_PROBIT_COEFFICIENTS.schema.validate(ci_probit_coefficients)
    _ci_summary_index_components_table_0 = view(ci_probit_coefficients, rows=('Governance',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_1 = view(ci_probit_coefficients, rows=('Growth',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_2 = view(ci_summary_components_by_year, rows=('Real growth rate \n(in percent)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2028))
    _ci_summary_index_components_table_3 = view(ci_probit_coefficients, rows=('Reserves',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_4 = view(ci_summary_components_by_year, rows=('Import coverage of reserves\n(in percent)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2028))
    _ci_summary_index_components_table_5 = view(ci_probit_coefficients, rows=('Reserves^2',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_6 = view(ci_probit_coefficients, rows=('FX INCOME3',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_7 = view(ci_summary_components_by_year, rows=('Remittances\n(in percent)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2028))
    _ci_summary_index_components_table_8 = view(ci_probit_coefficients, rows=('World Growth',), cols=span(data.INDICATOR_AXIS, 'PV of debt to GDP', 'Debt service to exports'))
    _ci_summary_index_components_table_9 = view(ci_summary_components_by_year, rows=('World economic growth \n(in percent)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2028))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'CPIA' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_0)), 3))
        elif indicator == 'CPIA' and variant == '10-year average values (B)':
            return as_measure(xl_average(view(ci_summary_components_by_year, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2028))))
        elif indicator == 'CPIA' and variant == 'CI Score components \n(A*B) = (C)':
            return as_measure(xl_mul(ci_summary_index_components[indicator, 'Coefficients (A)'], ci_summary_index_components[indicator, '10-year average values (B)']))
        elif indicator == 'Real growth rate (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_1)), 3))
        elif indicator == 'Real growth rate (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_2))
        elif indicator == 'Import coverage of reserves (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_3)), 3))
        elif indicator == 'Import coverage of reserves (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_4))
        elif indicator == 'Import coverage of reserves^2  (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_5)), 3))
        elif indicator == 'Import coverage of reserves^2  (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_div(xl_pow(xl_average(_ci_summary_index_components_table_4), 2), 100))
        elif indicator == 'Remittances (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_6)), 3))
        elif indicator == 'Remittances (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_7))
        elif indicator == 'World economic growth (in percent)' and variant == 'Coefficients (A)':
            return as_measure(xl_round(xl_neg(xl_average(_ci_summary_index_components_table_8)), 3))
        elif indicator == 'World economic growth (in percent)' and variant == '10-year average values (B)':
            return as_measure(xl_average(_ci_summary_index_components_table_9))
        return as_measure(xl_mul(xl_div(ci_summary_index_components[indicator, 'Coefficients (A)'], 100), ci_summary_index_components[indicator, '10-year average values (B)']))

    ci_summary_index_components = CoordinateReader('ci_summary_index_components', data.CI_SUMMARY_INDEX_COMPONENTS.required, formula)
    return data.CI_SUMMARY_INDEX_COMPONENTS.collect((coord, ci_summary_index_components[coord]) for coord in data.CI_SUMMARY_INDEX_COMPONENTS.required)

@publish(key=(), domain=None, cells=data.CI_SUMMARY_CI_SCORE_CELLS)
def ci_summary_ci_score(*, ci_summary_index_components: data.Series[float | str | None]) -> float | str:
    """Compute the CI summary CI score from indexed CI components.

    Sum the weighted CI-index contributions that form the CI score in the LIC-DSF CI summary.

    Args:
        ci_summary_index_components: Typed series of CI summary index components over catalog coordinates, carrying numeric CI-score contributions along with possible text or blank entries.

    Returns:
        Scalar CI score as a float, or the Excel error code string when the underlying sum cannot be evaluated.
    """
    _ci_summary_ci_score_table_0 = view(ci_summary_index_components, rows=('CPIA', 'Real growth rate (in percent)', 'Import coverage of reserves (in percent)', 'Import coverage of reserves^2  (in percent)', 'Remittances (in percent)', 'World economic growth (in percent)'), cols=('CI Score components \n(A*B) = (C)',))
    try:
        return as_measure(xl_sum(_ci_summary_ci_score_table_0))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.CI_SUMMARY_CI_RATING_CELLS)
def ci_summary_ci_rating(*, ci_cutoff_weak: float | str, ci_cutoff_strong: float | str, ci_class_labels_cutoffs: data.Series[str | None], ci_summary_ci_score: float | str) -> str | int | float | bool:
    """Return the CI rating label implied by a CI score relative to weak and strong cut-offs.

    Map a CI score to its weak, medium, or strong rating using authored cutoff identities.

    Args:
        ci_cutoff_weak: Scalar weak-rating score threshold; may be numeric or text.
        ci_cutoff_strong: Scalar strong-rating score threshold; may be numeric or text.
        ci_class_labels_cutoffs: String-valued series over catalog coordinates giving class labels for the weak, medium, and strong cutoff keys.
        ci_summary_ci_score: Scalar CI score to classify; may be numeric or text.

    Returns:
        The resulting CI rating label as a str, int, float, or bool scalar, or an error code string if evaluation raises XlError.
    """
    data.CI_CLASS_LABELS_CUTOFFS.schema.validate(ci_class_labels_cutoffs)
    try:
        return as_measure((ci_class_labels_cutoffs['Weak'] if xl_bool(xl_lt(ci_summary_ci_score, ci_cutoff_weak)) else (ci_class_labels_cutoffs['Strong'] if xl_bool(xl_gt(ci_summary_ci_score, ci_cutoff_strong)) else ci_class_labels_cutoffs['Medium'])), 'str')
    except XlError as error:
        return error.code

@publish(data.CI_SUMMARY_COMPONENTS_BY_YEAR.schema, cells=data.CI_SUMMARY_COMPONENTS_BY_YEAR.cells)
def ci_summary_components_by_year(*, ci_remittances_higher_cutoff: float | str, imported_classification_values: data.Series[float | str | None], ci_summary_gdp_us_dollars_billions: data.Series[float | str | None], ci_summary_remittances_gross_us_dollars_billions: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute CI summary components by year using authored coordinate identities.

    Evaluates the CI summary component formula for each year, applying the remittances cutoff logic.

    Args:
        ci_remittances_higher_cutoff: Scalar threshold for remittances as a percentage of GDP; if the computed ratio exceeds this cutoff, the cutoff is used instead.
        imported_classification_values: Typed data series over catalog coordinates providing imported classification values for each indicator and time period.
        ci_summary_gdp_us_dollars_billions: Typed data series over catalog coordinates representing GDP in billions of US dollars for each time period.
        ci_summary_remittances_gross_us_dollars_billions: Typed data series over catalog coordinates representing gross remittances in billions of US dollars for each time period.

    Returns:
        Typed data series over catalog coordinates containing the CI summary components by year, aligned to Imported data.
    """
    def formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'Remittances\n(in percent)':
            return as_measure((ci_remittances_higher_cutoff if xl_bool(xl_gt(xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100), ci_remittances_higher_cutoff)) else xl_mul(xl_div(ci_summary_remittances_gross_us_dollars_billions[time_period], ci_summary_gdp_us_dollars_billions[time_period]), 100)))
        return as_measure(imported_classification_values[indicator, time_period])

    return data.CI_SUMMARY_COMPONENTS_BY_YEAR.collect(evaluate(formula, data.CI_SUMMARY_COMPONENTS_BY_YEAR.required))

