@publish(data.TRIGGER_ISOCODE.schema, cells=data.TRIGGER_ISOCODE.cells)
def trigger_isocode(*, lookup_imf_country_code: data.Series[int | str | None], lookup_country_table_headers: data.Series[str | None], lookup_iso_alpha3: data.Series[str | None], lookup_country_name: data.Series[str | None], lookup_hipc_status: data.Series[str | None], trigger_ifscode_header: str | int | float | bool, trigger_ifscode: data.Series[int | str | None]) -> data.Series[str | int | float | bool | None]:
    """Compute the trigger ISO code for each reference area using authored coordinate identities.

    Maps a series of trigger country codes and a scalar header to the corresponding ISO code via indexed lookup in the country table.

    Args:
        lookup_imf_country_code: data.Series[int | str | None] of IMF country codes indexed by reference area, used as the match key against the country lookup table's country code column.
        lookup_country_table_headers: data.Series[str | None] of column headers for the country lookup table (e.g., 'Code2', 'HIPC status', 'MDRI').
        lookup_iso_alpha3: data.Series[str | None] of ISO Alpha-3 country codes indexed by reference area, providing the row index for the lookup table.
        lookup_country_name: data.Series[str | None] of country names indexed by reference area, included in the lookup table for completeness.
        lookup_hipc_status: data.Series[str | None] of HIPC status labels indexed by reference area, included in the lookup table for completeness.
        trigger_ifscode_header: Scalar header key (str | int | float | bool) used to select the target column from the country lookup table.
        trigger_ifscode: data.Series[int | str | None] of trigger country codes indexed by reference area, used to match rows in the country lookup table.

    Returns:
        data.Series[str | int | float | bool | None] of resolved trigger ISO codes (or None when no match) indexed by reference area, produced by indexing the matched country table row under the selected header.
    """
    data.LOOKUP_IMF_COUNTRY_CODE.schema.validate(lookup_imf_country_code)
    data.LOOKUP_COUNTRY_TABLE_HEADERS.schema.validate(lookup_country_table_headers)
    data.LOOKUP_ISO_ALPHA3.schema.validate(lookup_iso_alpha3)
    data.LOOKUP_COUNTRY_NAME.schema.validate(lookup_country_name)
    data.LOOKUP_HIPC_STATUS.schema.validate(lookup_hipc_status)
    _trigger_isocode_table_0 = lazy_table(((view(lookup_country_table_headers, cols=span(data.VARIANT_AXIS, 'Code2', 'HIPC status')),), (view(lookup_iso_alpha3, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_imf_country_code, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_country_name, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_hipc_status, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')))))
    _trigger_isocode_table_1 = lazy_table(((lambda: lookup_country_table_headers['Country code'],), (view(lookup_imf_country_code, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')),)))
    _trigger_isocode_table_2 = lazy_table(((view(lookup_country_table_headers, cols=span(data.VARIANT_AXIS, 'Code2', 'MDRI')), lambda: None),))
    def formula(ref_area: str) -> str | int | float | bool | None:
        return as_measure(xl_index(_trigger_isocode_table_0, xl_match(trigger_ifscode[ref_area], _trigger_isocode_table_1, 0), xl_match(trigger_ifscode_header, _trigger_isocode_table_2, 0)), 'str')

    return data.TRIGGER_ISOCODE.collect(evaluate(formula, data.TRIGGER_ISOCODE.required))

@publish(data.TRIGGER_COUNTRY_NAME.schema, cells=data.TRIGGER_COUNTRY_NAME.cells)
def trigger_country_name(*, lookup_imf_country_code: data.Series[int | str | None], lookup_country_table_headers: data.Series[str | None], lookup_iso_alpha3: data.Series[str | None], lookup_country_name: data.Series[str | None], lookup_hipc_status: data.Series[str | None], trigger_country_header: str | int | float | bool, trigger_ifscode: data.Series[int | str | None]) -> data.Series[str | int | float | bool | None]:
    """Resolve country names for the LIC-DSF country list from coordinated lookup tables using INDEX/MATCH.

    Produce the trigger country-name series by matching a scalar header and per-area country-code triggers against the authored lookup coordinates.

    Args:
        lookup_imf_country_code: IMF country-code lookup series over reference-area coordinates, supplying row keys for the country-table lookup.
        lookup_country_table_headers: Country-table header series over variant-axis coordinates, supplying the header labels and column identifiers used to build the lookup tables.
        lookup_iso_alpha3: ISO alpha-3 country-code series over reference areas AFG through ZWE, forming the first data row of the indexed country table.
        lookup_country_name: Country-name series over reference areas AFG through ZWE, providing the values returned when the matched header selects country names.
        lookup_hipc_status: HIPC-status series over reference areas AFG through ZWE, providing a further column in the indexed country table.
        trigger_country_header: Scalar header selector matched against the available country-table headers to choose the output column.
        trigger_ifscode: IMF country-code trigger series keyed by reference area, matched against the country-code column to choose the output row.

    Returns:
        A data.Series[str | int | float | bool | None] of resolved country names for the LIC-DSF country list, keyed by the trigger country-name coordinates; values may be missing when the INDEX/MATCH lookups do not resolve.
    """
    data.LOOKUP_IMF_COUNTRY_CODE.schema.validate(lookup_imf_country_code)
    data.LOOKUP_COUNTRY_TABLE_HEADERS.schema.validate(lookup_country_table_headers)
    data.LOOKUP_ISO_ALPHA3.schema.validate(lookup_iso_alpha3)
    data.LOOKUP_COUNTRY_NAME.schema.validate(lookup_country_name)
    data.LOOKUP_HIPC_STATUS.schema.validate(lookup_hipc_status)
    _trigger_country_name_table_0 = lazy_table(((view(lookup_country_table_headers, cols=span(data.VARIANT_AXIS, 'Code2', 'HIPC status')),), (view(lookup_iso_alpha3, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_imf_country_code, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_country_name, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')), view(lookup_hipc_status, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')))))
    _trigger_country_name_table_1 = lazy_table(((lambda: lookup_country_table_headers['Country code'],), (view(lookup_imf_country_code, rows=span(data.REF_AREA_AXIS, 'AFG', 'ZWE')),)))
    _trigger_country_name_table_2 = lazy_table(((view(lookup_country_table_headers, cols=span(data.VARIANT_AXIS, 'Code2', 'MDRI')), lambda: None),))
    def formula(ref_area: str) -> str | int | float | bool | None:
        return as_measure(xl_index(_trigger_country_name_table_0, xl_match(trigger_ifscode[ref_area], _trigger_country_name_table_1, 0), xl_match(trigger_country_header, _trigger_country_name_table_2, 0)), 'str')

    return data.TRIGGER_COUNTRY_NAME.collect(evaluate(formula, data.TRIGGER_COUNTRY_NAME.required))

@publish(data.TRIGGER_PPP_YEAR.schema, cells=data.TRIGGER_PPP_YEAR.cells)
def trigger_ppp_year(*, trigger_left_headers: data.Series[str | None], imported_ppp_headers: data.Series[str | None], imported_ppp_ifs_code: data.Series[int | str | None], imported_ppp_country_name: data.Series[str | None], imported_ppp_year: data.Series[int | str | None], imported_ppp_incgr: data.Series[int | str | None], imported_ppp_licdsf: data.Series[int | str | None], imported_ppp_kppp: data.Series[str | None], imported_ppp_gdp: data.Series[float | str | None], imported_ppp_ratio: data.Series[str | None]) -> data.Series[int | str | None]:
    """Resolve each reference area's PPP capital-stock vintage year from the imported PPP table.

    Match each country's IFS code and the left-hand 'year' header against the imported PPP table to return that reference area's PPP vintage year.

    Args:
        trigger_left_headers: Named-axis series of left-hand row header labels, including the 'year' key, aligned to catalog coordinates and used as lookup keys into the imported PPP column headers.
        imported_ppp_headers: Named-axis series of imported PPP column header labels (ifscode, country, year, incgr, licdsf, kppp_rppp, GDP_rppp, PPP%GDP) spanning catalog coordinates.
        imported_ppp_ifs_code: Named-axis series of IMF IFS country codes from the imported PPP table, indexed over reference-area catalog coordinates.
        imported_ppp_country_name: Named-axis series of country names from the imported PPP table, aligned to the reference-area axis.
        imported_ppp_year: Named-axis series of PPP vintage/benchmark years per country taken from the imported PPP table.
        imported_ppp_incgr: Named-axis series of income-group classifications per country from the imported PPP table.
        imported_ppp_licdsf: Named-axis series of LIC-DSF eligibility indicators per country from the imported PPP table.
        imported_ppp_kppp: Named-axis series of PPP conversion-factor (kppp_rppp) values per country, carrying blanks and '-' placeholders alongside numeric entries.
        imported_ppp_gdp: Named-axis series of GDP (rppp basis) values per country from the imported PPP table, which may mix floats, strings, and blanks.
        imported_ppp_ratio: Named-axis series of PPP-to-GDP ratios per country, including error sentinels such as '#VALUE!' and '#N/A' alongside numeric entries.

    Returns:
        A typed data.Series[int | str | None] keyed by reference area giving each country's PPP capital-stock vintage year, resolved through the imported PPP table lookup, with int, string, or None entries where the lookup yields text, a sentinel, or no match.
    """
    data.TRIGGER_LEFT_HEADERS.schema.validate(trigger_left_headers)
    data.IMPORTED_PPP_HEADERS.schema.validate(imported_ppp_headers)
    data.IMPORTED_PPP_IFS_CODE.schema.validate(imported_ppp_ifs_code)
    data.IMPORTED_PPP_COUNTRY_NAME.schema.validate(imported_ppp_country_name)
    data.IMPORTED_PPP_YEAR.schema.validate(imported_ppp_year)
    data.IMPORTED_PPP_INCGR.schema.validate(imported_ppp_incgr)
    data.IMPORTED_PPP_LICDSF.schema.validate(imported_ppp_licdsf)
    data.IMPORTED_PPP_KPPP.schema.validate(imported_ppp_kppp)
