    return data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO_B3_EXPORTS.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO_B3_EXPORTS.required))

