    return data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO_C4_MKT_FIN.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_REVENUE_GRANTS_RATIO_C4_MKT_FIN.required))

