    return data.BASELINE_PUB_DEBT_SERVICE_GDP_RATIO_B4_OTHER_FLOWS.collect(evaluate(formula, data.BASELINE_PUB_DEBT_SERVICE_GDP_RATIO_B4_OTHER_FLOWS.required))

