@publish(data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.schema, cells=data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.cells)
def custom_pub_please_do_not_change_these_numbers(*, customized_public_template_anchor: float | str) -> data.Series[int | str | None]:
    """Build the customized public scenario 'please do not change these numbers' series.

    Derive the public customized-scenario anchor series by incrementing the supplied template anchor across projection years.

    Args:
        customized_public_template_anchor: Scalar anchor value for the customized public scenario template, used as the 2025 starting point from which each subsequent projection year increases by one.

    Returns:
        data.Series[int | str | None] keyed by projection years from row 7, containing the customized public scenario numbers generated from the anchor.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2025:
            return as_measure(xl_add(customized_public_template_anchor, 1), 'int')
        return as_measure(xl_add(custom_pub_please_do_not_change_these_numbers[time_period - 1], 1), 'int')

    custom_pub_please_do_not_change_these_numbers = CoordinateReader('custom_pub_please_do_not_change_these_numbers', data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.required, formula)
    return data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.collect((coord, custom_pub_please_do_not_change_these_numbers[coord]) for coord in data.CUSTOM_PUB_PLEASE_DO_NOT_CHANGE_THESE_NUMBERS.required)

