@publish(data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.schema, cells=data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.cells)
def custom_pub_usd_discount_rate_by_year(*, customized_public_external_mlt_disbursement_profile: float | str, custom_pub_avg_maturity_incl_grace_period_by_year: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Derive the customized-scenario public USD discount rate by year.

    Rolls the customized public external MLT disbursement profile and per-year average maturity into a year-keyed USD discount rate series for the tailored public scenario.

    Args:
        customized_public_external_mlt_disbursement_profile: Customized public external MLT disbursement profile as a scalar float or str.
        custom_pub_avg_maturity_incl_grace_period_by_year: Customized public average maturity including grace period by year, as a data.Series over catalog projection years with int, str, or None values.

    Returns:
        USD discount rate (Customized Scenario - public) as a data.Series keyed by projection years from row 60, holding int, str, or None values.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(customized_public_external_mlt_disbursement_profile, custom_pub_avg_maturity_incl_grace_period_by_year[time_period]), 'int')
        return as_measure(xl_sub(custom_pub_usd_discount_rate_by_year[time_period - 1], custom_pub_avg_maturity_incl_grace_period_by_year[time_period]), 'int')

    custom_pub_usd_discount_rate_by_year = CoordinateReader('custom_pub_usd_discount_rate_by_year', data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.required, formula)
    return data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.collect((coord, custom_pub_usd_discount_rate_by_year[coord]) for coord in data.CUSTOM_PUB_USD_DISCOUNT_RATE_BY_YEAR.required)

@publish(data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.schema, cells=data.CUSTOM_PUB_AVG_MATURITY_INCL_GRACE_PERIOD_BY_YEAR.cells)
def custom_pub_avg_maturity_incl_grace_period_by_year(*, customized_public_external_mlt_disbursement_profile: float | str, custom_pub_period: data.Series[int | str | None], custom_pub_avg_grace_period: int | str, custom_pub_avg_maturity_incl_grace_period: int | str) -> data.Series[int | str | None]:
    """Compute customized public average maturity including grace period by projection year.

    Derive per-year average maturity including grace period for the customized public external MLT disbursement scenario.

    Args:
        customized_public_external_mlt_disbursement_profile: Scalar disbursement amount for the customized public external MLT profile; may be a float or a str reference.
        custom_pub_period: Named-axis series of projection periods (years) over catalog coordinates, used to compute years since 2024.
        custom_pub_avg_grace_period: Scalar average grace period in years for the customized public scenario.
        custom_pub_avg_maturity_incl_grace_period: Scalar average maturity including grace period in years for the customized public scenario.

    Returns:
        A data.Series of int, str, or None, keyed by projection years from row 60, giving the customized public average maturity including grace period per year.
    """
    def formula(time_period: int) -> int | str | None:
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(custom_pub_period[time_period], custom_pub_period[2024]), 1), custom_pub_avg_grace_period)) else (xl_div(customized_public_external_mlt_disbursement_profile, xl_sub(custom_pub_avg_maturity_incl_grace_period, custom_pub_avg_grace_period)) if xl_bool(xl_lt(xl_sub(xl_sub(custom_pub_period[time_period], custom_pub_period[2024]), 1), custom_pub_avg_maturity_incl_grace_period)) else 0)), 'int')

