@publish(data.CUSTOM_EXT_PPG_DEBT_SERVICE_TO_REVENUE.schema, cells=data.CUSTOM_EXT_PPG_DEBT_SERVICE_TO_REVENUE.cells)
def custom_ext_ppg_debt_service_to_revenue(*, custom_ext_ppg_debt_service_stress: data.Series[float | str | None], custom_ext_revenue: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the customized external PPG debt service-to-revenue ratio as a percentage.

    Scales the customized external PPG debt-service-to-revenue quotient by 100 to produce a projection-year percentage series.

    Args:
        custom_ext_ppg_debt_service_stress: Customized Scenario-External PPG debt-service stress series keyed by projection-year catalog coordinates, with float, string, or None values.
        custom_ext_revenue: Customized Scenario-External revenue series keyed by the same projection-year catalog coordinates, with float, string, or None values.

    Returns:
        A data.Series[float | str | None] of customized external PPG debt service-to-revenue percentages, keyed by projection years from row 8.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(custom_ext_ppg_debt_service_stress[time_period], custom_ext_revenue[time_period]), 100))

    return data.CUSTOM_EXT_PPG_DEBT_SERVICE_TO_REVENUE.collect(evaluate(formula, data.CUSTOM_EXT_PPG_DEBT_SERVICE_TO_REVENUE.required))

@publish(data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS.schema, cells=data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS.cells)
def custom_ext_nominal_gdp_million_of_us_dollars(*, custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: float | str, custom_ext_real_gdp_growth_by_year: data.Series[float | str | None], custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Project customized external-scenario nominal GDP in millions of US dollars by compounding real GDP growth and the US-dollar GDP deflator from the 2024 base.

    Provide the year-indexed nominal GDP path used by downstream customized external-scenario calculations.

    Args:
        custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: 2024 base-year nominal GDP in millions of US dollars, supplied as a scalar value or text.
        custom_ext_real_gdp_growth_by_year: Real GDP growth by projection year, in percent, as a catalog-keyed series.
        custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year: Change in the GDP deflator in US dollar terms by projection year, in percent, as a catalog-keyed series.

    Returns:
        Nominal GDP (millions of US dollars) for the customized external scenario, as a year-keyed series of floats, text, or missing values.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_mul(custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars, xl_add(1, xl_div(custom_ext_real_gdp_growth_by_year[time_period], 100))), xl_add(1, xl_div(custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year[time_period], 100))))
        return as_measure(xl_mul(xl_mul(custom_ext_nominal_gdp_million_of_us_dollars[time_period - 1], xl_add(1, xl_div(custom_ext_real_gdp_growth_by_year[time_period], 100))), xl_add(1, xl_div(custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year[time_period], 100))))

    custom_ext_nominal_gdp_million_of_us_dollars = CoordinateReader('custom_ext_nominal_gdp_million_of_us_dollars', data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS.required, formula)
    return data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS.collect((coord, custom_ext_nominal_gdp_million_of_us_dollars[coord]) for coord in data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS.required)

@publish(data.CUSTOM_EXT_REAL_GDP_GROWTH_BY_YEAR.schema, cells=data.CUSTOM_EXT_REAL_GDP_GROWTH_BY_YEAR.cells)
def custom_ext_real_gdp_growth_by_year(*, customized_public_template_anchor: float | str, customized_public_natural_disaster_year: int | str, custom_pub_please_do_not_change_these_numbers: data.Series[int | str | None], custom_ext_real_gdp_growth: data.Series[float | str | None], customized_scenario_spec: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive the annual customized-scenario external real GDP growth path by subtracting a natural-disaster shock from the published growth series.

    Produce the year-by-year customized external real GDP growth series used in the LIC-DSF chart and stress outputs, conditional on natural-disaster applicability.

    Args:
        customized_public_template_anchor: Scalar anchor value (float or str) identifying the customized public template year; for the 2024 row it is compared with the natural-disaster year to decide whether the shock is applied across that entry.
        customized_public_natural_disaster_year: Scalar natural-disaster year (int or str) used as the comparison target that determines whether the associated real GDP growth shock is subtracted.
        custom_pub_please_do_not_change_these_numbers: A data.Series of integer, string, or null values whose per-year entries are compared against the natural-disaster year to gate shock subtraction in each projection year.
        custom_ext_real_gdp_growth: A data.Series of float, string, or null real GDP growth values (customized scenario-external) keyed by projection year, from which the shock amount is subtracted.
        customized_scenario_spec: A data.Series of float, string, or null customized-scenario values containing the size of the associated real GDP growth shock in 2022.

    Returns:
        A data.Series[float | str | None] of real GDP growth in percent (Customized Scenario-External), keyed by projection years from row 8, with the natural-disaster shock subtracted where the year condition holds.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(custom_ext_real_gdp_growth[time_period], (customized_scenario_spec['size_of_associated_real_gdp_growth_shock', 2022] if xl_bool(xl_eq(customized_public_template_anchor, customized_public_natural_disaster_year)) else 0)))
        return as_measure(xl_sub(custom_ext_real_gdp_growth[time_period], (customized_scenario_spec['size_of_associated_real_gdp_growth_shock', 2022] if xl_bool(xl_eq(custom_pub_please_do_not_change_these_numbers[time_period], customized_public_natural_disaster_year)) else 0)))

    return data.CUSTOM_EXT_REAL_GDP_GROWTH_BY_YEAR.collect(evaluate(formula, data.CUSTOM_EXT_REAL_GDP_GROWTH_BY_YEAR.required))

@publish(data.CUSTOM_EXT_PV_PPG_STRESS.schema, cells=data.CUSTOM_EXT_PV_PPG_STRESS.cells)
def custom_ext_pv_ppg_stress(*, custom_ext_pv_of_additional_borrowing: data.Series[float | str | None], custom_ext_pv_ppg_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the customized-scenario external PV PPG stress series.

    Add additional external borrowing to the baseline PV PPG path to produce the customized-scenario stress path keyed by projection years.

    Args:
        custom_ext_pv_of_additional_borrowing: Customized-scenario external PV of additional borrowing, as a typed data.Series over projection-year coordinates with float, str, or None entries.
        custom_ext_pv_ppg_baseline: Baseline external PV PPG series, as a typed data.Series over projection-year coordinates with float, str, or None entries.

    Returns:
        A typed data.Series[float | str | None] of customized external PV PPG stress keyed by projection years, formed by adding the additional-borrowing series to the baseline series per year.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_ext_pv_ppg_baseline[time_period], custom_ext_pv_of_additional_borrowing[time_period]))

    return data.CUSTOM_EXT_PV_PPG_STRESS.collect(evaluate(formula, data.CUSTOM_EXT_PV_PPG_STRESS.required))

@publish(data.CUSTOM_EXT_PPG_DEBT_SERVICE_STRESS.schema, cells=data.CUSTOM_EXT_PPG_DEBT_SERVICE_STRESS.cells)
def custom_ext_ppg_debt_service_stress(*, custom_ext_additional_debt_service_stress: data.Series[float | str | None], custom_ext_debt_service_ppg_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute customized external PPG debt service stress by adding additional debt service stress to the PPG baseline.

    Derive the stressed PPG debt service path for the customized external scenario over projection years.

    Args:
        custom_ext_additional_debt_service_stress: Additional debt service stress over projection years as a data.Series of float, str, or None values.
        custom_ext_debt_service_ppg_baseline: PPG debt service baseline over projection years as a data.Series of float, str, or None values.

    Returns:
        data.Series[float | str | None] keyed by projection years from row 8 representing the stressed PPG debt service path.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_add(custom_ext_debt_service_ppg_baseline[time_period], custom_ext_additional_debt_service_stress[time_period]))

    return data.CUSTOM_EXT_PPG_DEBT_SERVICE_STRESS.collect(evaluate(formula, data.CUSTOM_EXT_PPG_DEBT_SERVICE_STRESS.required))

@publish(data.CUSTOM_EXT_Y7_LONG_RUN_CONSTANT_EXPORTS.schema, cells=data.CUSTOM_EXT_Y7_LONG_RUN_CONSTANT_EXPORTS.cells)
def custom_ext_y7_long_run_constant_exports(*, custom_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], custom_ext_exports_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive long-run constant customized-scenario exports from the exports share and nominal GDP series.

    Hold exports at the assumptions-sheet share of GDP so the customized external scenario has a level path in millions of US dollars across the projection years.

    Args:
        custom_ext_nominal_gdp_million_of_us_dollars: Nominal GDP in millions of US dollars, a named-axis data.Series over projection years.
        custom_ext_exports_by_year: Customized-scenario exports expressed as a percent share of GDP, a named-axis data.Series keyed by projection years.

    Returns:
        A data.Series of long-run constant customized-scenario exports in millions of US dollars, keyed by projection years.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(custom_ext_exports_by_year[time_period], 100), custom_ext_nominal_gdp_million_of_us_dollars[time_period]))

    return data.CUSTOM_EXT_Y7_LONG_RUN_CONSTANT_EXPORTS.collect(evaluate(formula, data.CUSTOM_EXT_Y7_LONG_RUN_CONSTANT_EXPORTS.required))

@publish(data.CUSTOM_EXT_REVENUE.schema, cells=data.CUSTOM_EXT_REVENUE.cells)
def custom_ext_revenue(*, custom_pub_revenue_grants: data.Series[float | str | None], custom_pub_grants: data.Series[float | str | None], custom_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the customized-scenario external revenue series keyed by projection years.

    Convert customized-scenario public revenue-and-grants and grants shares into a nominal external revenue amount in millions of U.S. dollars.

    Args:
        custom_pub_revenue_grants: Customized-scenario public revenue-and-grants series over projection years, expressed as a percent-of-GDP share.
        custom_pub_grants: Customized-scenario public grants series over projection years, as a percent-of-GDP share, subtracted to isolate revenue.
        custom_ext_nominal_gdp_million_of_us_dollars: Customized-scenario external nominal GDP series over projection years, in millions of U.S. dollars.

    Returns:
        Customized-scenario external revenue as a typed data.Series[float | str | None], keyed by projection years from row 8.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(xl_sub(custom_pub_revenue_grants[time_period], custom_pub_grants[time_period]), 100), custom_ext_nominal_gdp_million_of_us_dollars[time_period]))

    return data.CUSTOM_EXT_REVENUE.collect(evaluate(formula, data.CUSTOM_EXT_REVENUE.required))

@publish(data.CUSTOM_EXT_PPG_NOMINAL_DEBT_BASELINE.schema, cells=data.CUSTOM_EXT_PPG_NOMINAL_DEBT_BASELINE.cells)
def custom_ext_ppg_nominal_debt_baseline(*, dsa_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], dsa_ext_of_which_public_and_publicly_guaranteed_ppg: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Customized external PPG nominal debt baseline series.

    Computes nominal PPG debt in millions of USD by scaling external nominal GDP by the PPG share of GDP for the Baseline scenario.

    Args:
        dsa_ext_nominal_gdp_million_of_us_dollars: External nominal GDP in millions of US dollars, a data.Series[float | str | None] indexed by projection years (Baseline scenario).
        dsa_ext_of_which_public_and_publicly_guaranteed_ppg: External public and publicly guaranteed (PPG) debt as a percentage of GDP, a data.Series[float | str | None] indexed by projection years (Baseline scenario).

    Returns:
        A data.Series[float | str | None] of customized external PPG nominal debt baseline in millions of US dollars, keyed by projection years from row 55.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(dsa_ext_of_which_public_and_publicly_guaranteed_ppg['Baseline', time_period], 100), dsa_ext_nominal_gdp_million_of_us_dollars['Baseline', time_period]))

    return data.CUSTOM_EXT_PPG_NOMINAL_DEBT_BASELINE.collect(evaluate(formula, data.CUSTOM_EXT_PPG_NOMINAL_DEBT_BASELINE.required))

@publish(data.CUSTOM_EXT_INCREASE.schema, cells=data.CUSTOM_EXT_INCREASE.cells)
def custom_ext_increase(*, custom_ext_ppg_nominal_debt_baseline: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the customized external PPG nominal debt increase series.

    Derive the year-over-year customized scenario external nominal debt increase from the baseline projection path.

    Args:
        custom_ext_ppg_nominal_debt_baseline: Projection-year series of customized-scenario external PPG nominal debt baseline values, carrying floats, string flags, or None for missing entries.

    Returns:
        A data.Series[float | str | None] keyed by projection years, holding the customized external PPG nominal debt increase.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(custom_ext_ppg_nominal_debt_baseline[time_period], custom_ext_ppg_nominal_debt_baseline[time_period - 1]))

    return data.CUSTOM_EXT_INCREASE.collect(evaluate(formula, data.CUSTOM_EXT_INCREASE.required))

@publish(data.CUSTOM_EXT_PPG_NOMINAL_DEBT_STRESS.schema, cells=data.CUSTOM_EXT_PPG_NOMINAL_DEBT_STRESS.cells)
def custom_ext_ppg_nominal_debt_stress(*, custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: float | str, custom_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], custom_ext_of_which_public_publicly_guaranteed_ppg: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the customized-scenario external PPG nominal debt stress path from PPG shares and nominal GDP.

    Derives the customized-scenario external debt stress indicator by scaling each year's public and publicly guaranteed PPG share against the corresponding nominal GDP level.

    Args:
        custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: Scalar nominal GDP in millions of U.S. dollars applying to the 2023 anchor year, used to scale the PPG share for that period.
        custom_ext_nominal_gdp_million_of_us_dollars: Nominal GDP in millions of U.S. dollars as a named-axis series over catalog coordinates, supplying the per-period scaling denominator for projection years other than the 2023 anchor.
        custom_ext_of_which_public_publicly_guaranteed_ppg: Public and publicly guaranteed PPG expressed in percent as a named-axis series over catalog coordinates, divided by 100 and multiplied by the GDP level for each period.

    Returns:
        A data.Series of the customized-scenario external PPG nominal debt stress, keyed by projection years starting at row 55, holding floats with possible string or null entries.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_mul(xl_div(custom_ext_of_which_public_publicly_guaranteed_ppg[time_period], 100), custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars))
        return as_measure(xl_mul(xl_div(custom_ext_of_which_public_publicly_guaranteed_ppg[time_period], 100), custom_ext_nominal_gdp_million_of_us_dollars[time_period]))

    return data.CUSTOM_EXT_PPG_NOMINAL_DEBT_STRESS.collect(evaluate(formula, data.CUSTOM_EXT_PPG_NOMINAL_DEBT_STRESS.required))

@publish(data.CUSTOM_EXT_INCREASE_BY_YEAR.schema, cells=data.CUSTOM_EXT_INCREASE_BY_YEAR.cells)
def custom_ext_increase_by_year(*, custom_ext_ppg_nominal_debt_stress: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the customized external PPG nominal debt stress increase by projection year.

    Derive year-over-year changes in the customized external PPG nominal debt stress series.

    Args:
        custom_ext_ppg_nominal_debt_stress: Customized Scenario-External PPG nominal debt stress series keyed by projection years, with numeric, text, or missing values.

    Returns:
        Customized Scenario-External increase series keyed by projection years, where each value is the current year's nominal debt stress minus the prior year's.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(custom_ext_ppg_nominal_debt_stress[time_period], custom_ext_ppg_nominal_debt_stress[time_period - 1]))

    return data.CUSTOM_EXT_INCREASE_BY_YEAR.collect(evaluate(formula, data.CUSTOM_EXT_INCREASE_BY_YEAR.required))

@publish(data.CUSTOM_EXT_RESIDUAL_GROSS_BORROWING.schema, cells=data.CUSTOM_EXT_RESIDUAL_GROSS_BORROWING.cells)
def custom_ext_residual_gross_borrowing(*, custom_ext_increase: data.Series[float | str | None], custom_ext_increase_by_year: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute residual gross borrowing for the customized external scenario.

    Provide the customized external scenario's residual gross borrowing series by subtracting the custom external increase from its by-year counterpart.

    Args:
        custom_ext_increase: Customized external increase series over projection years, representing the amount subtracted in the residual calculation.
        custom_ext_increase_by_year: Customized external increase-by-year series over projection years, representing the annual amount from which the increase is subtracted.

    Returns:
        A data.Series[float | str | None] of residual gross borrowing for the customized external scenario, keyed by projection years from row 8.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_sub(custom_ext_increase_by_year[time_period], custom_ext_increase[time_period]))

    return data.CUSTOM_EXT_RESIDUAL_GROSS_BORROWING.collect(evaluate(formula, data.CUSTOM_EXT_RESIDUAL_GROSS_BORROWING.required))

@dataclass(frozen=True, slots=True)
class ScanCustomExtExportsUsdResult:
    """Complete named results of one recurrence group evaluation."""
    custom_ext_exports_usd: data.Series[float | str | None]
    custom_ext_exports_growth: data.Series[float | str | None]
    custom_ext_exports_usd_stress: data.Series[float | str | None]
    custom_ext_exports_in_of_gdp_stress: data.Series[float | str | None]
    custom_ext_exports_by_year: data.Series[float | str | None]

def scan_custom_ext_exports_usd(*, dsa_ext_exports: data.Series[float | str | None], customized_public_template_anchor: float | str, customized_public_natural_disaster_year: int | str, custom_pub_please_do_not_change_these_numbers: data.Series[int | str | None], custom_ext_nominal_gdp_million_of_us_dollars: data.Series[float | str | None], custom_ext_nominal_gdp_million_of_us_dollars_by_year: data.Series[float | str | None], custom_ext_exports: data.Series[float | str | None], customized_scenario_spec: data.Series[float | str | None], custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars: float | str) -> ScanCustomExtExportsUsdResult:
    """Evaluate the recurrence group `custom_ext_exports_usd`, `custom_ext_exports_growth`, `custom_ext_exports_usd_stress`, `custom_ext_exports_in_of_gdp_stress`, `custom_ext_exports_by_year` and publish complete tensors."""
    def custom_ext_exports_usd_formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(xl_mul(xl_div(custom_ext_exports_by_year[time_period], 100), custom_ext_ii_key_macroeconomic_nominal_gdp_million_of_us_dollars))
        return as_measure(xl_mul(xl_div(custom_ext_exports[time_period], 100), custom_ext_nominal_gdp_million_of_us_dollars_by_year[time_period]))

    custom_ext_exports_usd = CoordinateReader('custom_ext_exports_usd', data.CUSTOM_EXT_EXPORTS_USD.required, custom_ext_exports_usd_formula)
    def custom_ext_exports_growth_formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_sub(xl_mul(xl_sub(xl_div(custom_ext_exports_usd[time_period], custom_ext_exports_usd[time_period - 1]), 1), 100), (customized_scenario_spec['size_of_associated_exports_growth_shock', 2022] if xl_bool(xl_eq(customized_public_template_anchor, customized_public_natural_disaster_year)) else 0)))
        return as_measure(xl_sub(xl_mul(xl_sub(xl_div(custom_ext_exports_usd[time_period], custom_ext_exports_usd[time_period - 1]), 1), 100), (customized_scenario_spec['size_of_associated_exports_growth_shock', 2022] if xl_bool(xl_eq(custom_pub_please_do_not_change_these_numbers[time_period], customized_public_natural_disaster_year)) else 0)))

    custom_ext_exports_growth = CoordinateReader('custom_ext_exports_growth', data.CUSTOM_EXT_EXPORTS_GROWTH.required, custom_ext_exports_growth_formula)
    def custom_ext_exports_usd_stress_formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(custom_ext_exports_usd[time_period - 1], xl_add(1, xl_div(custom_ext_exports_growth[time_period], 100))))
        return as_measure(xl_mul(custom_ext_exports_usd_stress[time_period - 1], xl_add(1, xl_div(custom_ext_exports_growth[time_period], 100))))

    custom_ext_exports_usd_stress = CoordinateReader('custom_ext_exports_usd_stress', data.CUSTOM_EXT_EXPORTS_USD_STRESS.required, custom_ext_exports_usd_stress_formula)
    def custom_ext_exports_in_of_gdp_stress_formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(custom_ext_exports_usd_stress[time_period], custom_ext_nominal_gdp_million_of_us_dollars[time_period]), 100))

    custom_ext_exports_in_of_gdp_stress = CoordinateReader('custom_ext_exports_in_of_gdp_stress', data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.required, custom_ext_exports_in_of_gdp_stress_formula)
    def custom_ext_exports_by_year_formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(dsa_ext_exports['Baseline', time_period])
        return as_measure(custom_ext_exports_in_of_gdp_stress[time_period])

    custom_ext_exports_by_year = CoordinateReader('custom_ext_exports_by_year', data.CUSTOM_EXT_EXPORTS_BY_YEAR.required, custom_ext_exports_by_year_formula)
    return ScanCustomExtExportsUsdResult(
        custom_ext_exports_usd=data.CUSTOM_EXT_EXPORTS_USD.collect((coord, custom_ext_exports_usd[coord]) for coord in data.CUSTOM_EXT_EXPORTS_USD.required),
        custom_ext_exports_growth=data.CUSTOM_EXT_EXPORTS_GROWTH.collect((coord, custom_ext_exports_growth[coord]) for coord in data.CUSTOM_EXT_EXPORTS_GROWTH.required),
        custom_ext_exports_usd_stress=data.CUSTOM_EXT_EXPORTS_USD_STRESS.collect((coord, custom_ext_exports_usd_stress[coord]) for coord in data.CUSTOM_EXT_EXPORTS_USD_STRESS.required),
        custom_ext_exports_in_of_gdp_stress=data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.collect((coord, custom_ext_exports_in_of_gdp_stress[coord]) for coord in data.CUSTOM_EXT_EXPORTS_IN_OF_GDP_STRESS.required),
        custom_ext_exports_by_year=data.CUSTOM_EXT_EXPORTS_BY_YEAR.collect((coord, custom_ext_exports_by_year[coord]) for coord in data.CUSTOM_EXT_EXPORTS_BY_YEAR.required),
    )

@publish(data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.schema, cells=data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.cells)
def custom_ext_nominal_gdp_million_of_us_dollars_by_year(*, custom_ext_y7_long_run_constant_nominal_gdp_million_of_us_dollars: float | str, custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year: data.Series[float | str | None], custom_ext_real_gdp_growth: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute customized external nominal GDP in millions of US dollars by projection year.

    Builds the customized external nominal GDP path by compounding the long-run constant nominal GDP scalar with annual real GDP growth and US dollar GDP deflator changes.

    Args:
        custom_ext_y7_long_run_constant_nominal_gdp_million_of_us_dollars: Long-run constant nominal GDP in millions of US dollars for the customized external scenario, supplied as a float or string scalar.
        custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year: Typed data series of annual percentage changes in the GDP deflator in US dollar terms for the customized external scenario, keyed by projection year; each entry is a float, string, or None.
        custom_ext_real_gdp_growth: Typed data series of annual real GDP growth rates for the customized external scenario, keyed by projection year; each entry is a float, string, or None.

    Returns:
        Typed data series of customized external nominal GDP in millions of US dollars, keyed by projection year from row 55, with float, string, or None entries.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(xl_mul(xl_mul(custom_ext_y7_long_run_constant_nominal_gdp_million_of_us_dollars, xl_add(1, xl_div(custom_ext_real_gdp_growth[time_period], 100))), xl_add(1, xl_div(custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year[time_period], 100))))
        return as_measure(xl_mul(xl_mul(custom_ext_nominal_gdp_million_of_us_dollars_by_year[time_period - 1], xl_add(1, xl_div(custom_ext_real_gdp_growth[time_period], 100))), xl_add(1, xl_div(custom_ext_gdp_deflator_in_us_dollar_terms_change_pct_by_year[time_period], 100))))

    custom_ext_nominal_gdp_million_of_us_dollars_by_year = CoordinateReader('custom_ext_nominal_gdp_million_of_us_dollars_by_year', data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.required, formula)
    return data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.collect((coord, custom_ext_nominal_gdp_million_of_us_dollars_by_year[coord]) for coord in data.CUSTOM_EXT_NOMINAL_GDP_MILLION_OF_US_DOLLARS_BY_YEAR.required)

@publish(key=(), domain=None, cells=data.IN1_BASICS_AUTOFILL_NOTE_CELLS)
def in1_basics_autofill_note(*, translation_input_1_basics_blue_cells_are_populated_automatically: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> str | int | float | bool:
    """Extract the English-language Input 1 – Basics autofill note for a selected debt-sustainability analysis start period.

    Provide the template text that marks automatically populated blue cells on the Input 1 – Basics sheet.

    Args:
        translation_input_1_basics_blue_cells_are_populated_automatically: A named-axis series of optional text values over catalog coordinates, anchored at the single-cell Input 1 – Basics note stating that blue cells are populated automatically.
        start_debt_sustainability_analysis_m: Scalar debt-sustainability analysis start-period selector, either an integer index or text key, used to step the language axis.

    Returns:
        The English note text as a string, or the corresponding error/measure code as an integer, float, or boolean scalar when the lookup fails, matching the `str | int | float | bool` return annotation.
    """
    data.TRANSLATION_INPUT_1_BASICS_BLUE_CELLS_ARE_POPULATED_AUTOMATICALLY.schema.validate(translation_input_1_basics_blue_cells_are_populated_automatically)
    try:
        return as_measure(translation_input_1_basics_blue_cells_are_populated_automatically[axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')
    except XlError as error:
        return error.code

