@publish(data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS.schema, cells=data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS.cells)
def in6_tailored_natdisaster_interaction_defaults(*, input6_tailored_tests_enabled: str) -> data.Series[float | str | None]:
    """Compute the natural-disaster tailored stress-test interaction defaults for Input 6.

    Provides the standard GDP and export growth shock defaults applied when tailored natural-disaster tests are enabled.

    Args:
        input6_tailored_tests_enabled: Scalar toggle flag indicating whether Input 6 tailored tests are enabled ('On' activates the shock defaults).

    Returns:
        data.Series[float | str | None] indexed over the tailored natural-disaster interaction coordinates, holding the GDP growth shock size and the paired export growth shock value, or zero when tailored tests are off.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Size of associated real GDP growth shock':
            return as_measure((1.5 if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))
        return as_measure((3.5 if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))

    return data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS.collect(evaluate(formula, data.IN6_TAILORED_NATDISASTER_INTERACTION_DEFAULTS.required))

