@publish(data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS.schema, cells=data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS.cells)
def in6_tailored_commodity_interaction_defaults(*, in6_tailored_average_of_prices_shock_default: float | str, input6_tailored_tests_enabled: str) -> data.Series[float | str | None]:
    """Compute the Input 6 tailored-commodity interaction default shock series.

    Produces the standard commodity-price GDP-growth and revenue-drop interaction shocks used when Input 6 tailored tests are enabled.

    Args:
        in6_tailored_average_of_prices_shock_default: Scalar average-of-prices shock default, supplied as a numeric value or string sentinel used by the interaction formulas.
        input6_tailored_tests_enabled: Scalar text flag indicating whether Input 6 tailored tests are enabled, such as 'On'.

    Returns:
        A data.Series of float | str | None over the tailored-commodity interaction coordinates, yielding the standard commodity-price GDP-growth and revenue-drop interaction shock defaults when tailored tests are enabled and zero otherwise.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'Size of associated real GDP growth shock':
            return as_measure((xl_div(xl_mul(in6_tailored_average_of_prices_shock_default, 0.5), xl_neg(xl_div(10, 100))) if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))
        return as_measure((xl_div(xl_mul(in6_tailored_average_of_prices_shock_default, 0.75), xl_neg(xl_div(10, 100))) if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))

    return data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS.collect(evaluate(formula, data.IN6_TAILORED_COMMODITY_INTERACTION_DEFAULTS.required))

