@publish(data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS.schema, cells=data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS.cells)
def in6_tailored_mkt_fin_maturity_defaults(*, input6_tailored_tests_enabled: str) -> data.Series[float | str | None]:
    """Return tailored market-financing maturity and grace-period default shortenings for Input 6.

    Computes the standard commercial-maturity and grace-period default values used when tailored tests are enabled, otherwise returns zero defaults.

    Args:
        input6_tailored_tests_enabled: Scalar string toggle indicating whether tailored tests are enabled; 'On' activates the shortenings, and any other value yields zero defaults.

    Returns:
        A typed data.Series[float | str | None] over the authored IN6 tailored market-financing maturity-default indicator coordinates, containing the 5-year or two-thirds maturity shortening when enabled and 0 otherwise.
    """
    def formula(indicator: str) -> float | str | None:
        if indicator == 'If original maturity is greater than 5 years, new maturity is':
            return as_measure((5 if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))
        return as_measure((xl_div(2, 3) if xl_bool(xl_eq(input6_tailored_tests_enabled, 'On')) else 0))

    return data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS.collect(evaluate(formula, data.IN6_TAILORED_MKT_FIN_MATURITY_DEFAULTS.required))

