@publish(data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.schema, cells=data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.cells)
def in6opt_standard_nominal_depreciation_close_real_overvaluation(*, input6_standard_size_threshold_mode: str, baseline_pub_inflation_rate_gdp_deflator_pct: data.Series[float | str | None], in6opt_standard_one_time_30_percent_nominal_depreciation_of: int | str, in6opt_standard_us_inflation_default: float | str, input6_standard_params_2: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the nominal depreciation required to close the real overvaluation gap for the Input 6(optional)-Standard Test.

    Return the standard-test depreciation adjustment as a typed series keyed by the row-14 column labels.

    Args:
        input6_standard_size_threshold_mode: Mode selecting the standard-test size-threshold treatment; the default variant applies the one-time depreciation and US-inflation adjustment only when this equals 'NEW'.
        baseline_pub_inflation_rate_gdp_deflator_pct: Baseline public inflation rate (GDP deflator, percent) series over catalog coordinates; its 2025 coordinate is added to the one-time nominal depreciation.
        in6opt_standard_one_time_30_percent_nominal_depreciation_of: Scalar one-time 30 percent nominal depreciation magnitude for the standard test.
        in6opt_standard_us_inflation_default: Default US inflation scalar used in the default variant of the calculation.
        input6_standard_params_2: Input 6 standard parameters series over catalog coordinates; its 'b5_depreciation_3', 'default' entry supplies the depreciation baseline for non-default variants.

    Returns:
        A data.Series[float | str | None] of nominal depreciation values needed to close the real overvaluation gap under the Input 6(optional)-Standard Test, keyed by column labels from row 14.
    """
    def formula(variant: str) -> float | str | None:
        if variant == 'Default':
            return as_measure((xl_sub(xl_add(in6opt_standard_one_time_30_percent_nominal_depreciation_of, baseline_pub_inflation_rate_gdp_deflator_pct[2025]), in6opt_standard_us_inflation_default) if xl_bool(xl_eq(input6_standard_size_threshold_mode, 'NEW')) else 0))
        return as_measure(xl_sub(xl_add(in6opt_standard_one_time_30_percent_nominal_depreciation_of, baseline_pub_inflation_rate_gdp_deflator_pct[2025]), input6_standard_params_2['b5_depreciation_3', 'default']))

    return data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.collect(evaluate(formula, data.IN6OPT_STANDARD_NOMINAL_DEPRECIATION_CLOSE_REAL_OVERVALUATION.required))

