@publish(data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.schema, cells=data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.cells)
def macro_debt_total_mlt_public_domestic_debt_amortization_debt(*, input5_summary_principal_payment: data.Series[float | str | None], macro_debt_public_domestic_st: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total MLT public domestic debt amortization by differencing principal payments against prior-period domestic debt stock and converting to US dollars.

    Derive the Macro-Debt_Data amortization series over the projection-year axis.

    Args:
        input5_summary_principal_payment: Summary principal-payment series by projection year from Input 5, expressed in US dollars on the Macro-Debt_Data keyed grid.
        macro_debt_public_domestic_st: Public domestic debt stock series by projection year in US dollars on the Macro-Debt_Data keyed grid, lagged one period for the amortization difference.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: National-currency-per-US-dollar exchange rate series by projection year, applied to convert the dollar-denominated difference into domestic currency.

    Returns:
        Typed data.Series[float | str | None] for MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT, keyed by projection years in US dollars.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_div(xl_sub(input5_summary_principal_payment[time_period], macro_debt_public_domestic_st[time_period - 1]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.collect(evaluate(formula, data.MACRO_DEBT_TOTAL_MLT_PUBLIC_DOMESTIC_DEBT_AMORTIZATION_DEBT.required))

