def macro_debt_share_of_commodity_exports_fuel_of_exports_of_g(*, input3_input_3_macro_exports_of_goods_and_services: data.Input3Input3MacroExportsOfGoodsAndServices, input3_input_3_macro_exports_commodity_fuel: data.Input3Input3MacroExportsCommodityFuel) -> data.Series[float | str | None]:
    """Calculate the fuel share of commodity exports as a percentage of exports of goods and services.

    Derive the Macro-Debt indicator series for the LIC-DSF IDA21 template by dividing fuel commodity exports by total exports of goods and services for each projection year.

    Args:
        input3_input_3_macro_exports_of_goods_and_services: Macro exports of goods and services, a named-axis data series keyed by projection year.
        input3_input_3_macro_exports_commodity_fuel: Macro commodity fuel exports, a named-axis data series keyed by projection year over the same coordinate grid.

    Returns:
        A data series of the fuel share of commodity exports as a percentage of exports of goods and services, keyed by projection year; entries are float, str, or None.
    """
    data.INPUT3_INPUT_3_MACRO_EXPORTS_OF_GOODS_AND_SERVICES.schema.validate(input3_input_3_macro_exports_of_goods_and_services)
    data.INPUT3_INPUT_3_MACRO_EXPORTS_COMMODITY_FUEL.schema.validate(input3_input_3_macro_exports_commodity_fuel)
    def formula(time_period: int) -> float | str | None:
        return as_measure((xl_div(input3_input_3_macro_exports_commodity_fuel[time_period], input3_input_3_macro_exports_of_goods_and_services[time_period]) if xl_bool(xl_isnumber(lambda: xl_div(input3_input_3_macro_exports_commodity_fuel[time_period], input3_input_3_macro_exports_of_goods_and_services[time_period]))) else 0))

    return data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_FUEL_OF_EXPORTS_OF_G.collect(evaluate(formula, data.MACRO_DEBT_SHARE_OF_COMMODITY_EXPORTS_FUEL_OF_EXPORTS_OF_G.required))

