@publish(data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.schema, cells=data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.cells)
def macro_debt_privatization_receipts(*, input3_other_debt_flows: data.Series[float | str | None], input3_input_3_macro_privatization_proceeds: data.Input3Input3MacroPrivatizationProceeds) -> data.Series[float | str | None]:
    """Compute macro-debt privatization receipts by combining historical other debt flows and projected Input 3 privatization proceeds.

    Produces a projection-year series of privatization receipts in national currency, using pre-2024 history and post-2023 projections.

    Args:
        input3_other_debt_flows: Typed data series of other debt flows keyed by catalog coordinates, including the privatization proceeds row used for years through 2023; numeric entries are read and nonnumeric entries become zero.
        input3_input_3_macro_privatization_proceeds: Typed Input 3 macro privatization proceeds series indexed by projection year, supplying receipts from 2024 onward; numeric entries are read and nonnumeric entries become zero.

    Returns:
        Typed data series of macro-debt privatization receipts in national currency, keyed by projection years from row 1.
    """
    data.INPUT3_OTHER_DEBT_FLOWS.schema.validate(input3_other_debt_flows)
    data.INPUT3_INPUT_3_MACRO_PRIVATIZATION_PROCEEDS.schema.validate(input3_input_3_macro_privatization_proceeds)
    def formula(time_period: int) -> float | str | None:
        if time_period <= 2023:
            return as_measure((input3_other_debt_flows['Privatization Proceeds', time_period] if xl_bool(xl_isnumber(lambda: input3_other_debt_flows['Privatization Proceeds', time_period])) else 0))
        return as_measure((input3_input_3_macro_privatization_proceeds[time_period] if xl_bool(xl_isnumber(lambda: input3_input_3_macro_privatization_proceeds[time_period])) else 0))

    return data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.collect(evaluate(formula, data.MACRO_DEBT_PRIVATIZATION_RECEIPTS.required))

