@publish(data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.schema, cells=data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.cells)
def macro_debt_public_sector_interest_expenditure(*, macro_debt_ppg_interest_due: data.Series[float | str | None], macro_debt_total_public_domestic_debt_interest_due: data.Series[float | str | None], macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute public sector interest expenditure in national currency from PPG and domestic debt interest due.

    Derive the Macro-Debt_Data public-sector interest expenditure series by summing PPG interest due and total public domestic debt interest due, converted at the national-currency-per-USD exchange rate.

    Args:
        macro_debt_ppg_interest_due: Series of interest due on public and publicly guaranteed (PPG) external debt, indexed by projection-year coordinates on the Macro-Debt_Data national-currency grid.
        macro_debt_total_public_domestic_debt_interest_due: Series of interest due on total public domestic debt, indexed by the same projection-year coordinates.
        macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: Series of the exchange rate in national currency per U.S. dollar, indexed by the same projection-year coordinates.

    Returns:
        A data.Series[float | str | None] holding the computed total public sector interest expenditure in national currency, aligned to the Macro-Debt_Data projection-year coordinates, with numeric values where the operand series permit computation and str or None propagated from textual or blank cells.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(xl_mul(xl_add(macro_debt_ppg_interest_due[time_period], macro_debt_total_public_domestic_debt_interest_due[time_period]), macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period]))

    return data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.collect(evaluate(formula, data.MACRO_DEBT_PUBLIC_SECTOR_INTEREST_EXPENDITURE.required))

