def macro_debt_recognition_of_contingent_liab_e_g_bank(*, input3_other_debt_flows: data.Series[float | str | None], in3_macro_recognition_of_contingent_liab_e_g_bank: data.In3MacroRecognitionOfContingentLiabEGBank) -> data.Series[int | str | None]:
    """Computes the macro-debt recognition of contingent liabilities (e.g., bank recapitalization) series by projection year.

    To produce the recognized contingent-liability path used in macro-debt calculations, drawing on historical other-debt-flow input through 2023 and Input 3 projections thereafter.

    Args:
        input3_other_debt_flows: A data.Series[float | str | None] of other debt flows over National Currency (Macro-Debt_Data) coordinates, keyed by projection years from row 1; its recognition-of-contingent-liabilities row supplies values through time period 2023.
        in3_macro_recognition_of_contingent_liab_e_g_bank: A data.In3MacroRecognitionOfContingentLiabEGBank series of macro recognition of contingent liabilities (e.g., bank recapitalization) over projection-year coordinates, supplying values from time period 2024 onward.

    Returns:
        A data.Series[int | str | None] keyed by projection year over National Currency (Macro-Debt_Data) coordinates, containing the computed macro-debt recognition of contingent liabilities as integers or string/None placeholders where nonnumeric.
    """
    data.INPUT3_OTHER_DEBT_FLOWS.schema.validate(input3_other_debt_flows)
    data.IN3_MACRO_RECOGNITION_OF_CONTINGENT_LIAB_E_G_BANK.schema.validate(in3_macro_recognition_of_contingent_liab_e_g_bank)
    def formula(time_period: int) -> int | str | None:
        if time_period <= 2023:
            return as_measure((input3_other_debt_flows['Recognition of contingent liabilities (e.g., bank recapitalization)', time_period] if xl_bool(xl_isnumber(lambda: input3_other_debt_flows['Recognition of contingent liabilities (e.g., bank recapitalization)', time_period])) else 0), 'int')
        return as_measure((in3_macro_recognition_of_contingent_liab_e_g_bank[time_period] if xl_bool(xl_isnumber(lambda: in3_macro_recognition_of_contingent_liab_e_g_bank[time_period])) else 0), 'int')

    return data.MACRO_DEBT_RECOGNITION_OF_CONTINGENT_LIAB_E_G_BANK.collect(evaluate(formula, data.MACRO_DEBT_RECOGNITION_OF_CONTINGENT_LIAB_E_G_BANK.required))

