@publish(data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.schema, cells=data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.cells)
def macro_debt_previous_vintage_investment(*, input3_investment: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Derive previous-vintage investment measures from Input 3.

    Produce the macro-debt previous-vintage investment series used by the DSA framework from authored Input 3 coordinates.

    Args:
        input3_investment: data.Series over catalog coordinates holding public and private investment, in constant prices and in percent of GDP, from the previous DSA vintage.

    Returns:
        data.Series aligned to the same catalog coordinates, containing previous-vintage investment measures as floats, strings, or None.
    """
    data.INPUT3_INVESTMENT.schema.validate(input3_investment)
    def formula(indicator: str, time_period: int) -> float | str | None:
        if indicator == 'Public Investment, constant prices' and time_period <= 2017:
            return as_measure((input3_investment['Public Investment, constant prices', time_period] if xl_bool(xl_isnumber(lambda: input3_investment['Public Investment, constant prices', time_period])) else 0))
        elif indicator == 'Public Investment in percent of GDP (real), previous DSA vintage' and time_period <= 2017:
            return as_measure((input3_investment['Public Investment in percent of GDP (real), previous DSA vintage', time_period] if xl_bool(xl_isnumber(lambda: input3_investment['Public Investment in percent of GDP (real), previous DSA vintage', time_period])) else 0))
        return as_measure((input3_investment[indicator, time_period] if xl_bool(xl_isnumber(lambda: input3_investment[indicator, time_period])) else 0))

    return data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.collect(evaluate(formula, data.MACRO_DEBT_PREVIOUS_VINTAGE_INVESTMENT.required))

