@publish(data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.schema, cells=data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.cells)
def c4_market_path_nominal_gdp_stress(*, c4_market_path_nominal_gdp: float | str, c4_mkt_fin_nominal_gdp: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Builds the C4 market-financing stress path for nominal GDP.

    Combines the 2024 nominal GDP anchor with projected market-financing nominal GDP values to produce the C4_Market nominal_gdp_stress series.

    Args:
        c4_market_path_nominal_gdp: Scalar nominal GDP anchor used for the 2024 time period.
        c4_mkt_fin_nominal_gdp: Named-axis series of nominal GDP values over catalog time periods, supplying non-2024 entries for the C4_Market stress path.

    Returns:
        Named-axis series of C4 market-path nominal GDP stress values, aligned to the scenario and time-period coordinates and allowing float, string, or missing entries.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if time_period == 2024:
            return as_measure(c4_market_path_nominal_gdp)
        return as_measure(c4_mkt_fin_nominal_gdp[time_period])

    return data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.collect(evaluate(formula, data.C4_MARKET_PATH_NOMINAL_GDP_STRESS.required))

