@publish(data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.schema, cells=data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.cells)
def custom_pub_avg_real_interest_rate_by_year(*, custom_pub_avg_real_interest_rate: float | str) -> data.Series[float | str | None]:
    """Return the custom public average real interest rate by year as a typed series.

    Build the catalog-aligned average real interest rate series by anchoring the custom public input and propagating it across required years.

    Args:
        custom_pub_avg_real_interest_rate: Custom public average real interest rate provided as a scalar float or string override, used as the initial anchor for the by-year series.

    Returns:
        A data.Series[float | str | None] over the required catalog coordinates, containing the custom public average real interest rate for each year.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2025:
            return as_measure(custom_pub_avg_real_interest_rate)
        return as_measure(custom_pub_avg_real_interest_rate_by_year[time_period - 1])

    custom_pub_avg_real_interest_rate_by_year = CoordinateReader('custom_pub_avg_real_interest_rate_by_year', data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.required, formula)
    return data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.collect((coord, custom_pub_avg_real_interest_rate_by_year[coord]) for coord in data.CUSTOM_PUB_AVG_REAL_INTEREST_RATE_BY_YEAR.required)

