@publish(data.C4_MARKET_INSTRUMENTS.schema, cells=data.C4_MARKET_INSTRUMENTS.cells)
def c4_market_instruments(*, input4_grace_period: data.Input4GracePeriod, input4_loan_maturity: data.Input4LoanMaturity) -> data.Series[int | str | None]:
    """Build the C4 market-instrument series for commercial loans by selecting grace-period terms for 2023 and loan-maturity terms for later years.

    Populate the C4 INSTRUMENT coordinate used in market-financing calculations with the appropriate commercial-loan term per period.

    Args:
        input4_grace_period: Keyword-only data.Input4GracePeriod series over commercial-loan instrument names (C:D terms), supplying the 2023 grace-period measure.
        input4_loan_maturity: Keyword-only data.Input4LoanMaturity series over commercial-loan instrument names (C:D terms), supplying the loan-maturity measure for all non-2023 periods.

    Returns:
        data.Series[int | str | None] keyed by C4 commercial-loan INSTRUMENT names, not INDICATOR, with each value taken from the grace-period series for 2023 or the loan-maturity series otherwise.
    """
    data.INPUT4_GRACE_PERIOD.schema.validate(input4_grace_period)
    data.INPUT4_LOAN_MATURITY.schema.validate(input4_loan_maturity)
    def formula(instrument: str, time_period: int) -> int | str | None:
        if time_period == 2023:
            return as_measure(input4_grace_period[instrument], 'int')
        return as_measure(input4_loan_maturity[instrument], 'int')

    return data.C4_MARKET_INSTRUMENTS.collect(evaluate(formula, data.C4_MARKET_INSTRUMENTS.required))

