def realism1_external_debt_flow_components(*, translation_external_flow_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism1ExternalDebtFlowComponents:
    """Compute Realism 1 external debt-creating-flow component labels from translated external flow phrases at the debt sustainability analysis start month.

    Produce the Realism 1 external debt flow decomposition components used by the LIC-DSF realism tools.

    Args:
        translation_external_flow_phrases: Named-axis data.Series of translated component labels for the external debt-creating-flow decomposition, with string or missing values over catalog coordinates and validation against the translation external flow phrases schema.
        start_debt_sustainability_analysis_m: Scalar integer or string identifying the starting month of the debt sustainability analysis, used to select the corresponding coordinate along the language axis when resolving each translated phrase.

    Returns:
        A data.Realism1ExternalDebtFlowComponents dataclass whose fields are typed data.Series over the required Realism 1 external debt flow component coordinates, containing the evaluated translated labels for the external debt-creating-flow decomposition.
    """
    data.TRANSLATION_EXTERNAL_FLOW_PHRASES.schema.validate(translation_external_flow_phrases)
    def formula(indicator: str) -> str | int | float | bool | None:
        return as_measure(translation_external_flow_phrases[indicator, axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')

    return data.REALISM1_EXTERNAL_DEBT_FLOW_COMPONENTS.collect(evaluate(formula, data.REALISM1_EXTERNAL_DEBT_FLOW_COMPONENTS.required))

@publish(data.REALISM1_EXTERNAL_DEBT_CREATING_FLOWS.schema, cells=data.REALISM1_EXTERNAL_DEBT_CREATING_FLOWS.cells)
def realism1_external_debt_creating_flows(*, realism1_external_current_vintage_projection: data.Series[float | str | None]) -> data.Realism1ExternalDebtCreatingFlows:
    """Compute the Realism 1 external debt-creating-flow decomposition from current-vintage projection data.

    Derives the 5-year historical and projected external PPG debt-creating-flow contributions used by the Realism 1 tool.

    Args:
        realism1_external_current_vintage_projection: A named-axis data.Series[float | str | None] over catalog coordinates containing the external PPG debt-creating-flow decomposition, with 5-year historical and projected values for the relevant indicator rows.

    Returns:
        A data.Realism1ExternalDebtCreatingFlows dataclass of series containing the collected Realism 1 external debt-creating-flow decomposition across the required indicator and 5-year historical/projected variant keys.
    """
    _realism1_external_debt_creating_flows_table_0 = view(realism1_external_current_vintage_projection, rows=('Contribution from nominal interest rate (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_debt_creating_flows_table_1 = view(realism1_external_current_vintage_projection, rows=('Contribution from nominal interest rate (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_external_debt_creating_flows_table_2 = view(realism1_external_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_debt_creating_flows_table_3 = view(realism1_external_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_external_debt_creating_flows_table_4 = view(realism1_external_current_vintage_projection, rows=('Contribution from price and exchange rate changes (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_debt_creating_flows_table_5 = view(realism1_external_current_vintage_projection, rows=('Contribution from price and exchange rate changes (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_external_debt_creating_flows_table_6 = view(realism1_external_current_vintage_projection, rows=('Change in external debt (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_debt_creating_flows_table_7 = view(realism1_external_current_vintage_projection, rows=('Change in external debt (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_external_debt_creating_flows_table_8 = view(realism1_external_current_vintage_projection, rows=('change in private sector debt (ppt change)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_external_debt_creating_flows_table_9 = view(realism1_external_current_vintage_projection, rows=('change in private sector debt (ppt change)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Change in PPG debt 3/' and variant == '5-year historical change':
            return as_measure(xl_sub(realism1_external_current_vintage_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2023], realism1_external_current_vintage_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2018]))
        elif indicator == 'Change in PPG debt 3/' and variant == '5-year projected change':
            return as_measure(xl_sub(realism1_external_current_vintage_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2028], realism1_external_current_vintage_projection['External debt o/w public and publicly guaranteed (in percent of GDP)', 2023]))
        elif indicator == 'Current account + FDI' and variant == '5-year historical change':
            return as_measure(xl_sum(view(realism1_external_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))))
        elif indicator == 'Current account + FDI' and variant == '5-year projected change':
            return as_measure(xl_sum(view(realism1_external_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))))
        elif indicator == 'Nominal interest rate' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_0))
        elif indicator == 'Nominal interest rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_1))
        elif indicator == 'Real GDP growth' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_2))
        elif indicator == 'Real GDP growth' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_3))
        elif indicator == 'Price and exchange rate' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_4))
        elif indicator == 'Price and exchange rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_5))
        elif indicator == 'Change in debt' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_6))
        elif indicator == 'Change in debt' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_external_debt_creating_flows_table_7))
        elif indicator == 'Residual' and variant == '5-year historical change':
            return as_measure(xl_sub(xl_sum(view(realism1_external_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))), xl_sum(_realism1_external_debt_creating_flows_table_8)))
        return as_measure(xl_sub(xl_sum(view(realism1_external_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))), xl_sum(_realism1_external_debt_creating_flows_table_9)))

    return data.REALISM1_EXTERNAL_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.REALISM1_EXTERNAL_DEBT_CREATING_FLOWS.required))

