@publish(data.REALISM1_EXTERNAL_FORECAST_ERROR_DISTRIBUTION_LABELS.schema, cells=data.REALISM1_EXTERNAL_FORECAST_ERROR_DISTRIBUTION_LABELS.cells)
def realism1_external_forecast_error_distribution_labels(*, realism1_external_median_label: str | int | float | bool, translation_debt_change_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism1ExternalForecastErrorDistributionLabels:
    """Build labels for the Realism 1 external forecast-error distribution chart.

    Provides the label series for the external forecast-error median and PPG-debt-change overlay.

    Args:
        realism1_external_median_label: Scalar label for the external forecast-error median variant, accepted as string, integer, float, or boolean.
        translation_debt_change_phrases: Named-axis string series of translation phrases for debt-change overlays, with nullable values per language coordinate.
        start_debt_sustainability_analysis_m: Integer or string coordinate identifying the start of the debt sustainability analysis within the language axis.

    Returns:
        A data.Realism1ExternalForecastErrorDistributionLabels instance containing the computed label series for the external forecast-error distribution.
    """
    data.TRANSLATION_DEBT_CHANGE_PHRASES.schema.validate(translation_debt_change_phrases)
    def formula(variant: str) -> str | int | float | bool | None:
        if variant == 'Median':
            return as_measure(realism1_external_median_label, 'str')
        return as_measure(xl_concat(translation_debt_change_phrases['Change in PPG debt', axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], ' 3/'), 'str')

    return data.REALISM1_EXTERNAL_FORECAST_ERROR_DISTRIBUTION_LABELS.collect(evaluate(formula, data.REALISM1_EXTERNAL_FORECAST_ERROR_DISTRIBUTION_LABELS.required))

