@publish(data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.schema, cells=data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.cells)
def realism1_public_debt_creating_flows(*, realism1_public_current_vintage_projection: data.Series[float | str | None]) -> data.Realism1PublicDebtCreatingFlows:
    """Aggregate Realism 1 public current-vintage projections into a debt-creating-flow decomposition over the five-year historical and five-year projected windows.

    Sum each public debt-creating-flow row over the 2019–2023 and 2024–2028 spans so the workbook's Realism 1 decomposition can be reported against the current vintage.

    Args:
        realism1_public_current_vintage_projection: Named-axis series of Realism 1 public current-vintage projection values, indexed by row (indicator) labels and time-period axis years, where each cell holds a float, a text label, or None for blanks.

    Returns:
        A data.Realism1PublicDebtCreatingFlows dataclass whose series carry the five-year historical and five-year projected contributions of the primary deficit, real interest rate, real GDP growth, real exchange-rate depreciation, change in public sector debt, other identified debt-creating flows, and the residual.
    """
    _realism1_public_debt_creating_flows_table_0 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from average real interest rate (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_public_debt_creating_flows_table_1 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from average real interest rate (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_public_debt_creating_flows_table_2 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_public_debt_creating_flows_table_3 = view(realism1_public_current_vintage_projection, rows=('of which: contribution from real GDP growth (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_public_debt_creating_flows_table_4 = view(realism1_public_current_vintage_projection, rows=('Contribution from real exchange rate depreciation (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_public_debt_creating_flows_table_5 = view(realism1_public_current_vintage_projection, rows=('Contribution from real exchange rate depreciation (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_public_debt_creating_flows_table_6 = view(realism1_public_current_vintage_projection, rows=('Change in public sector debt (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_public_debt_creating_flows_table_7 = view(realism1_public_current_vintage_projection, rows=('Change in public sector debt (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    _realism1_public_debt_creating_flows_table_8 = view(realism1_public_current_vintage_projection, rows=('Other identified debt-creating flows (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))
    _realism1_public_debt_creating_flows_table_9 = view(realism1_public_current_vintage_projection, rows=('Other identified debt-creating flows (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))
    def formula(indicator: str, variant: str) -> float | str | None:
        if indicator == 'Primary deficit' and variant == '5-year historical change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(f'{indicator} (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))))
        elif indicator == 'Primary deficit' and variant == '5-year projected change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(f'{indicator} (in percent of GDP)',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))))
        elif indicator == 'Real interest rate' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_0))
        elif indicator == 'Real interest rate' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_1))
        elif indicator == 'Real GDP growth' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_2))
        elif indicator == 'Real GDP growth' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_3))
        elif indicator == 'Real Exchange rate depreciation' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_4))
        elif indicator == 'Real Exchange rate depreciation' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_5))
        elif indicator == 'Change in debt' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_6))
        elif indicator == 'Change in debt' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_7))
        elif indicator == 'Other debt creating flows' and variant == '5-year historical change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_8))
        elif indicator == 'Other debt creating flows' and variant == '5-year projected change':
            return as_measure(xl_sum(_realism1_public_debt_creating_flows_table_9))
        elif indicator == 'Residual' and variant == '5-year historical change':
            return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2019, 2023))))
        return as_measure(xl_sum(view(realism1_public_current_vintage_projection, rows=(indicator,), cols=span(data.TIME_PERIOD_AXIS, 2024, 2028))))

    return data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.collect(evaluate(formula, data.REALISM1_PUBLIC_DEBT_CREATING_FLOWS.required))

