@publish(data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.schema, cells=data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.cells)
def realism1_public_vintage_debt_paths(*, realism1_public_current_vintage_projection: data.Series[float | str | None], realism1_public_five_years_ago_rebased_projection: data.Series[float | str | None], realism1_public_last_vintage_stock_copies: data.Series[float | str | None]) -> data.Realism1PublicVintageDebtPaths:
    """Compute Realism 1 public-debt vintage paths across current, previous, and five-years-ago DSA baselines.

    Assemble the public sector debt-to-GDP paths used in Realism 1 vintage comparisons.

    Args:
        realism1_public_current_vintage_projection: Keyword-only data.Series[float | str | None] of the current DSA projection of public sector debt as a percent of GDP, indexed by catalog coordinates.
        realism1_public_five_years_ago_rebased_projection: Keyword-only data.Series[float | str | None] of the five-years-ago rebased projection of public sector debt as a percent of GDP, indexed by catalog coordinates.
        realism1_public_last_vintage_stock_copies: Keyword-only data.Series[float | str | None] of the last-vintage stock copies of public sector debt as a percent of GDP, indexed by catalog coordinates.

    Returns:
        data.Realism1PublicVintageDebtPaths dataclass of series containing the current, previous, and five-years-ago public sector debt-to-GDP paths keyed by scenario and time period.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Current DSA':
            return as_measure(realism1_public_current_vintage_projection['Public sector debt (in percent of GDP)', time_period])
        elif scenario == 'Previous DSA':
            return as_measure(realism1_public_last_vintage_stock_copies['Public sector debt (in percent of GDP)', time_period])
        return as_measure(realism1_public_five_years_ago_rebased_projection['Public sector debt (in percent of GDP)', time_period])

    return data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.collect(evaluate(formula, data.REALISM1_PUBLIC_VINTAGE_DEBT_PATHS.required))

