@publish(data.REALISM2_FISCAL_ADJUSTMENT_YEARS.schema, cells=data.REALISM2_FISCAL_ADJUSTMENT_YEARS.cells)
def realism2_fiscal_adjustment_years(*, realism2_history_years: data.Series[int | str | None]) -> data.Realism2FiscalAdjustmentYears:
    """Derive the Realism 2 fiscal-adjustment year for each required catalog year.

    Build the year axis consumed by the fiscal-adjustment-on-growth panel.

    Args:
        realism2_history_years: Year-indexed history series over the Realism 2 coordinate catalog; its 2024 value seeds the sequence, and subsequent years are propagated by adding one year at a time.

    Returns:
        A `data.Realism2FiscalAdjustmentYears` series mapping each required catalog year to its derived fiscal-adjustment year.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(realism2_history_years[time_period], 'int')
        elif time_period == 2025:
            return as_measure(xl_add(realism2_fiscal_adjustment_years[time_period - 1], 1), 'int')
        return as_measure(xl_sub(realism2_fiscal_adjustment_years[time_period + 1], 1), 'int')

    realism2_fiscal_adjustment_years = CoordinateReader('realism2_fiscal_adjustment_years', data.REALISM2_FISCAL_ADJUSTMENT_YEARS.required, formula)
    return data.REALISM2_FISCAL_ADJUSTMENT_YEARS.collect((coord, realism2_fiscal_adjustment_years[coord]) for coord in data.REALISM2_FISCAL_ADJUSTMENT_YEARS.required)

@publish(data.REALISM2_UNDERLYING_GROWTH_YEARS.schema, cells=data.REALISM2_UNDERLYING_GROWTH_YEARS.cells)
def realism2_underlying_growth_years(*, realism2_fiscal_adjustment_years: data.Realism2FiscalAdjustmentYears) -> data.Realism2UnderlyingGrowthYears:
    """Return Realism 2 underlying-growth years derived from the fiscal-adjustment year series.

    Copies the Realism 2 fiscal-adjustment year axis into the underlying-growth panel, coercing each year value to an integer.

    Args:
        realism2_fiscal_adjustment_years: Fiscal-adjustment year series over catalog time coordinates; each required period is converted to an integer year.

    Returns:
        Underlying-growth year series over catalog time coordinates, with the fiscal-adjustment year axis copied into the underlying-growth panel.
    """
    def formula(time_period: int) -> int | str | None:
        return as_measure(realism2_fiscal_adjustment_years[time_period], 'int')

    return data.REALISM2_UNDERLYING_GROWTH_YEARS.collect(evaluate(formula, data.REALISM2_UNDERLYING_GROWTH_YEARS.required))

@publish(data.REALISM2_BASELINE_GROWTH.schema, cells=data.REALISM2_BASELINE_GROWTH.cells)
def realism2_baseline_growth(*, realism2_real_gdp_growth: data.Series[float | str | None]) -> data.Realism2BaselineGrowth:
    """Compute the Realism 2 baseline real GDP growth path.

    Produces the baseline real GDP growth series shown on the fiscal-multiplier chart.

    Args:
        realism2_real_gdp_growth: Keyword-only typed data.Series[float | str | None] of real GDP growth values over catalog coordinate time periods, used as the input growth path.

    Returns:
        The data.Realism2BaselineGrowth dataclass of series containing the baseline real GDP growth path for the fiscal-multiplier chart.
    """
    def formula(time_period: int) -> float | str | None:
        return as_measure(realism2_real_gdp_growth[time_period])

    return data.REALISM2_BASELINE_GROWTH.collect(evaluate(formula, data.REALISM2_BASELINE_GROWTH.required))

@publish(data.REALISM2_GROWTH_T_MINUS_1.schema, cells=data.REALISM2_GROWTH_T_MINUS_1.cells)
def realism2_growth_t_minus_1(*, realism2_baseline_growth: data.Realism2BaselineGrowth) -> data.Realism2GrowthTMinus1:
    """Compute the Realism 2 growth series one period before projection.

    Carry baseline growth into the underlying-growth panel as a t-minus-one coordinate series.

    Args:
        realism2_baseline_growth: Typed baseline growth series over catalog coordinates, providing the seed value for 2023 and the prior-period lookup source.

    Returns:
        Typed Realism 2 growth t-minus-one series aligned to the required catalog coordinates.
    """
    def formula(time_period: int) -> float | str | None:
        if time_period == 2023:
            return as_measure(realism2_baseline_growth[2023])
        return as_measure(realism2_growth_t_minus_1[time_period - 1])

    realism2_growth_t_minus_1 = CoordinateReader('realism2_growth_t_minus_1', data.REALISM2_GROWTH_T_MINUS_1.required, formula)
    return data.REALISM2_GROWTH_T_MINUS_1.collect((coord, realism2_growth_t_minus_1[coord]) for coord in data.REALISM2_GROWTH_T_MINUS_1.required)

@publish(data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.schema, cells=data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.cells)
def realism2_fiscal_adjustment_growth_impact(*, realism2_growth_impact_multiplier_0_2_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_4_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_6_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_0_8_cumulative: data.Series[float | str | None], realism2_growth_impact_multiplier_1_0_cumulative: data.Series[float | str | None]) -> data.Realism2FiscalAdjustmentGrowthImpact:
    """Compute the Realism2 fiscal-adjustment growth-impact series across multiplier variants.

    Combine the cumulative growth-impact multiplier series into the Realism2 fiscal-adjustment growth-impact dataset.

    Args:
        realism2_growth_impact_multiplier_0_2_cumulative: Cumulative growth impact of the planned fiscal adjustment under a multiplier of 0.2, as a data.Series[float | str | None] over catalog coordinates.
        realism2_growth_impact_multiplier_0_4_cumulative: Cumulative growth impact of the planned fiscal adjustment under a multiplier of 0.4, as a data.Series[float | str | None] over catalog coordinates.
        realism2_growth_impact_multiplier_0_6_cumulative: Cumulative growth impact of the planned fiscal adjustment under a multiplier of 0.6, as a data.Series[float | str | None] over catalog coordinates.
        realism2_growth_impact_multiplier_0_8_cumulative: Cumulative growth impact of the planned fiscal adjustment under a multiplier of 0.8, as a data.Series[float | str | None] over catalog coordinates.
        realism2_growth_impact_multiplier_1_0_cumulative: Cumulative growth impact of the planned fiscal adjustment under a multiplier of 1.0, as a data.Series[float | str | None] over catalog coordinates.

    Returns:
        data.Realism2FiscalAdjustmentGrowthImpact, a dataclass of series holding the growth impact of the planned fiscal adjustment under each alternative multiplier variant.
    """
    def formula(time_period: int, variant: str) -> float | str | None:
        if variant == 'Multiplier = 0.2':
            return as_measure(realism2_growth_impact_multiplier_0_2_cumulative[time_period])
        elif variant == 'Multiplier = 0.4':
            return as_measure(realism2_growth_impact_multiplier_0_4_cumulative[time_period])
        elif variant == 'Multiplier = 0.6':
            return as_measure(realism2_growth_impact_multiplier_0_6_cumulative[time_period])
        elif variant == 'Multiplier = 0.8':
            return as_measure(realism2_growth_impact_multiplier_0_8_cumulative[time_period])
        return as_measure(realism2_growth_impact_multiplier_1_0_cumulative[time_period])

    return data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.collect(evaluate(formula, data.REALISM2_FISCAL_ADJUSTMENT_GROWTH_IMPACT.required))

@publish(data.REALISM2_UNDERLYING_GROWTH.schema, cells=data.REALISM2_UNDERLYING_GROWTH.cells)
def realism2_underlying_growth(*, realism2_growth_t_minus_1: data.Realism2GrowthTMinus1, realism2_fiscal_adjustment_growth_impact: data.Realism2FiscalAdjustmentGrowthImpact) -> data.Realism2UnderlyingGrowth:
    """Computes underlying growth paths under alternative fiscal-multiplier assumptions.

    Builds the Realism 2 underlying growth series from prior-period growth and fiscal-adjustment growth impacts.

    Args:
        realism2_growth_t_minus_1: Prior-period growth series indexed by time period and fiscal-multiplier variant.
        realism2_fiscal_adjustment_growth_impact: Fiscal-adjustment growth-impact series indexed by time period and fiscal-multiplier variant.

    Returns:
        A typed data.Realism2UnderlyingGrowth series keyed by time period and fiscal-multiplier variant.
    """
    def formula(time_period: int, variant: str) -> float | str | None:
        VARIANT_TO_REALISM2_UNDERLYING_GROWTH = {'Multiplier = 0.4': 'Multiplier = 0.2', 'Multiplier = 0.6': 'Multiplier = 0.4', 'Multiplier = 0.8': 'Multiplier = 0.6', 'Multiplier = 1': 'Multiplier = 0.8'}
        if time_period == 2023 and variant == 'Multiplier = 0.2':
            return as_measure(realism2_growth_t_minus_1[time_period])
        elif time_period == 2023 and variant in ('Multiplier = 0.4', 'Multiplier = 0.6', 'Multiplier = 0.8', 'Multiplier = 1'):
            return as_measure(realism2_underlying_growth[time_period, VARIANT_TO_REALISM2_UNDERLYING_GROWTH[variant]])
        return as_measure(xl_add(realism2_growth_t_minus_1[time_period], realism2_fiscal_adjustment_growth_impact[time_period, variant]))

    realism2_underlying_growth = CoordinateReader('realism2_underlying_growth', data.REALISM2_UNDERLYING_GROWTH.required, formula)
    return data.REALISM2_UNDERLYING_GROWTH.collect((coord, realism2_underlying_growth[coord]) for coord in data.REALISM2_UNDERLYING_GROWTH.required)

@publish(data.REALISM3_INVESTMENT_YEARS.schema, cells=data.REALISM3_INVESTMENT_YEARS.cells)
def realism3_investment_years(*, realism3_first_projection_year: int | str) -> data.Realism3InvestmentYears:
    """Build the Realism 3 investment year axis.

    Anchor the public/private investment vintage-comparison chart by deriving projected investment years from the first projection year.

    Args:
        realism3_first_projection_year: Scalar first projection year, provided as an integer or string label, used as the anchor for the generated year axis.

    Returns:
        A `data.Realism3InvestmentYears` series that maps catalog coordinates to investment years for the public/private investment vintage-comparison chart.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(realism3_first_projection_year, 'int')
        elif time_period >= 2025:
            return as_measure(xl_add(realism3_investment_years[time_period - 1], 1), 'int')
        return as_measure(xl_sub(realism3_investment_years[time_period + 1], 1), 'int')

    realism3_investment_years = CoordinateReader('realism3_investment_years', data.REALISM3_INVESTMENT_YEARS.required, formula)
    return data.REALISM3_INVESTMENT_YEARS.collect((coord, realism3_investment_years[coord]) for coord in data.REALISM3_INVESTMENT_YEARS.required)

@publish(data.REALISM3_INVESTMENT_PATH_LABELS.schema, cells=data.REALISM3_INVESTMENT_PATH_LABELS.cells)
def realism3_investment_path_labels(*, translation_investment_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism3InvestmentPathLabels:
    """Create Realism 3 investment-path row labels from translated phrases.

    Resolves English legend text for the previous and current DSA public and private investment paths.

    Args:
        translation_investment_phrases: Named-axis series of translated investment-path phrases (string or None) indexed by language and investment-path indicator, providing the English legend text for each required path.
        start_debt_sustainability_analysis_m: Scalar DSA start period (month integer or string) used to select the English language coordinate when stepping the phrase lookup.

    Returns:
        A data.Realism3InvestmentPathLabels dataclass of typed row-legend series for the previous and current DSA public and private investment paths.
    """
    data.TRANSLATION_INVESTMENT_PHRASES.schema.validate(translation_investment_phrases)
    def formula(indicator: str) -> str | int | float | bool | None:
        return as_measure(translation_investment_phrases[indicator, axis_step(data.LANGUAGE_AXIS, 'English', start_debt_sustainability_analysis_m)], 'str')

    return data.REALISM3_INVESTMENT_PATH_LABELS.collect(evaluate(formula, data.REALISM3_INVESTMENT_PATH_LABELS.required))

@publish(data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.schema, cells=data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.cells)
def realism3_public_private_investment_paths(*, realism3_public_investment_ratio_by_vintage: data.Series[float | str | None], realism3_private_investment_ratio_by_vintage: data.Series[float | str | None]) -> data.Realism3PublicPrivateInvestmentPaths:
    """Compute public and private investment ratio paths for Realism 3 by DSA vintage.

    Build the Realism 3 invest-growth chart series comparing current and previous DSA vintages.

    Args:
        realism3_public_investment_ratio_by_vintage: Public investment ratio (% of GDP) by vintage, given as a named-axis data series over catalog coordinates (Current and Previous DSA).
        realism3_private_investment_ratio_by_vintage: Private investment ratio (% of GDP) by vintage, given as a named-axis data series over catalog coordinates (Current and Previous DSA).

    Returns:
        A data.Realism3PublicPrivateInvestmentPaths dataclass of typed series giving the public and private investment ratio paths for the current and previous DSA vintages.
    """
    def formula(indicator: str, time_period: int) -> float | str | None:
        INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE = {'Gov. Invest. - Prev. DSA': 'Previous', 'Gov. Invest. - Curr. DSA': 'Current'}
        INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE = {'Priv. Invest. - Prev. DSA': 'Previous', 'Priv. Invest. - Curr. DSA': 'Current'}
        if indicator in ('Gov. Invest. - Prev. DSA', 'Gov. Invest. - Curr. DSA'):
            return as_measure((realism3_public_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period] if xl_bool(xl_isnumber(lambda: xl_mul(realism3_public_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PUBLIC_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period], 100))) else ''))
        return as_measure((realism3_private_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period] if xl_bool(xl_isnumber(lambda: xl_mul(realism3_private_investment_ratio_by_vintage[INDICATOR_TO_REALISM3_PRIVATE_INVESTMENT_RATIO_BY_VINTAGE[indicator], time_period], 100))) else ''))

    return data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.collect(evaluate(formula, data.REALISM3_PUBLIC_PRIVATE_INVESTMENT_PATHS.required))

@publish(data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.schema, cells=data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.cells)
def realism3_growth_accounting_vintages(*, translation_projection_phrases: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> data.Realism3GrowthAccountingVintages:
    """Compute Realism 3 investment-growth accounting vintage headers.

    Build the vintage header series consumed by the investment-growth accounting summary and Realism 3 charts.

    Args:
        translation_projection_phrases: Typed `data.Series[str | None]` of translation projection phrases over language variants, with `None` for missing text entries.
        start_debt_sustainability_analysis_m: Scalar `int | str` giving the starting period identifier for the debt sustainability analysis vintage.

    Returns:
        A typed `data.Realism3GrowthAccountingVintages` dataclass of series containing the investment-growth accounting vintage headers.
    """
    data.TRANSLATION_PROJECTION_PHRASES.schema.validate(translation_projection_phrases)
    def formula(variant: str) -> str | int | float | bool | None:
        return as_measure(translation_projection_phrases[variant, axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')

    return data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.collect(evaluate(formula, data.REALISM3_GROWTH_ACCOUNTING_VINTAGES.required))

@publish(data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.schema, cells=data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.cells)
def realism3_growth_accounting_contributions(*, realism3_growth_contributions: data.Series[float | str | None]) -> data.Realism3GrowthAccountingContributions:
    """Compute Realism 3 growth-accounting contributions by averaging authored DSA-vintage series over five-year windows.

    Populate the Realism 3 investment-growth accounting outputs from current and previous DSA contribution coordinates.

    Args:
        realism3_growth_contributions: A catalogue-indexed data.Series[float | str | None] of five-year-average contributions of government capital and other factors to growth, with rows identifying current and previous DSA vintages and columns spanning the time-period axis.

    Returns:
        A data.Realism3GrowthAccountingContributions dataclass of coordinate-aligned data.Series[float | str | None] containing the historical and projected averaged contribution values for the required Realism 3 growth-accounting indicators and variants.
    """
    def formula(indicator: str, variant: str) -> float | str | None:
        if variant == 'Historical':
            return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Curr. DSA',), cols=span(data.TIME_PERIOD_AXIS_16, 2019, 2023))))
        elif variant == 'Projected (Prev. DSA)':
            return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Prev. DSA',), cols=span(data.TIME_PERIOD_AXIS_16, 2024, 2028))))
        return as_measure(xl_average(view(realism3_growth_contributions, rows=(f'{indicator} - Curr. DSA',), cols=span(data.TIME_PERIOD_AXIS_16, 2024, 2028))))

    return data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.collect(evaluate(formula, data.REALISM3_GROWTH_ACCOUNTING_CONTRIBUTIONS.required))

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_LABEL_CELLS)
def realism4_projected_3yr_adjustment_label(*, translation_adjustment_phrase: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> str | int | float | bool:
    """Resolve the country's projected three-year fiscal-adjustment label from the translation-phrase series.

    Select the English fiscal-adjustment wording for the DSA start marker and return it as a scalar label or workbook error code.

    Args:
        translation_adjustment_phrase: Named-axis series of translation adjustment phrases (string or null) over catalog coordinates, holding the fiscal-adjustment wording to resolve along the language axis.
        start_debt_sustainability_analysis_m: Scalar start-of-debt-sustainability-analysis marker (year or label) used to select the English coordinate offset in the phrase series.

    Returns:
        Scalar projected three-year fiscal-adjustment label: a string when the translation lookup succeeds, otherwise the workbook error code (string or numeric) raised by the failed lookup.
    """
    data.TRANSLATION_ADJUSTMENT_PHRASE.schema.validate(translation_adjustment_phrase)
    try:
        return as_measure(translation_adjustment_phrase[axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_CELLS)
def realism4_projected_3yr_adjustment(*, realism4_three_year_adjustment: data.Series[float | str | None]) -> float | str:
    """Extract the projected 3-year fiscal adjustment for 2026.

    Read the Realism 4 fiscal-adjustment series and return its 2026 placement as a scalar.

    Args:
        realism4_three_year_adjustment: Projected 3-year fiscal adjustment (percentage points of GDP) as a typed series over catalog coordinates, keyed to projection years.

    Returns:
        The 2026 projected 3-year fiscal adjustment as a float, or the corresponding Excel error code as a string.
    """
    try:
        return as_measure(realism4_three_year_adjustment[2026])
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_BIN_CELLS)
def realism4_projected_3yr_adjustment_bin(*, realism4_projected_3yr_adjustment: float | str) -> float | str:
    """Round a projected three-year fiscal adjustment to its histogram bin edge.

    Normalizes a Realism 4 fiscal-adjustment projection for placement and distribution charting by snapping it to the nearest histogram bin boundary.

    Args:
        realism4_projected_3yr_adjustment: Scalar projected three-year fiscal adjustment; numeric inputs are rounded to the histogram bin edge, while string inputs represent formula error codes.

    Returns:
        Scalar projected three-year adjustment rounded to the nearest histogram bin edge, or the string error code if the calculation raises an `XlError`.
    """
    try:
        return as_measure(xl_div(xl_round(xl_mul(2, realism4_projected_3yr_adjustment), 0), 2))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_CATEGORY_CELLS)
def realism4_projected_3yr_adjustment_category(*, realism4_projected_3yr_adjustment_bin: float | str, realism4_fiscal_adjustment_bin_edges: data.Series[float | str | None], realism4_fiscal_adjustment_bin_frequencies: data.Series[float | str | None], realism4_fiscal_adjustment_bin_categories: data.Series[int | str | None]) -> float | str:
    """Determine the fiscal adjustment category for a projected 3-year adjustment using histogram bin definitions.

    Maps a projected adjustment value to its corresponding category from Realism 4 fiscal adjustment bins.

    Args:
        realism4_projected_3yr_adjustment_bin: Projected 3-year fiscal adjustment value (scalar float or string).
        realism4_fiscal_adjustment_bin_edges: Series of bin edge values defining the histogram bins for fiscal adjustment.
        realism4_fiscal_adjustment_bin_frequencies: Series of bin frequencies for the histogram bins (float or string).
        realism4_fiscal_adjustment_bin_categories: Series of category labels (integer or string) corresponding to each histogram bin.

    Returns:
        The category value (float or string) assigned to the projected adjustment.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_EDGES.schema.validate(realism4_fiscal_adjustment_bin_edges)
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_FREQUENCIES.schema.validate(realism4_fiscal_adjustment_bin_frequencies)
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_CATEGORIES.schema.validate(realism4_fiscal_adjustment_bin_categories)
    _realism4_projected_3yr_adjustment_category_table_0 = lazy_table(((view(realism4_fiscal_adjustment_bin_edges, rows=span(data.VARIANT_AXIS_4, 2, 27)), view(realism4_fiscal_adjustment_bin_frequencies, rows=span(data.VARIANT_AXIS_4, 2, 27)), view(realism4_fiscal_adjustment_bin_categories, rows=span(data.VARIANT_AXIS_4, 2, 27))),))
    try:
        return as_measure((realism4_fiscal_adjustment_bin_categories[1] if xl_bool(xl_lt(realism4_projected_3yr_adjustment_bin, realism4_fiscal_adjustment_bin_edges[2])) else (realism4_fiscal_adjustment_bin_categories[28] if xl_bool(xl_gt(realism4_projected_3yr_adjustment_bin, realism4_fiscal_adjustment_bin_edges[27])) else xl_vlookup(realism4_projected_3yr_adjustment_bin, _realism4_projected_3yr_adjustment_category_table_0, 3, False))))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_PROJECTED_3YR_ADJUSTMENT_SAMPLE_SHARE_CELLS)
def realism4_projected_3yr_adjustment_sample_share(*, realism4_projected_3yr_adjustment_category: float | str, realism4_fiscal_adjustment_bin_categories: data.Series[int | str | None], realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare) -> float | str:
    """Return the Realism 4 projected three-year fiscal adjustment sample share for a category.

    Look up the percent-of-sample value associated with the projected three-year fiscal adjustment category from the authored bin/sample-share table.

    Args:
        realism4_projected_3yr_adjustment_category: Scalar category code or label identifying the projected three-year fiscal adjustment bin.
        realism4_fiscal_adjustment_bin_categories: Named-axis series of fiscal adjustment bin categories over the variant-axis coordinate, supplying the left-hand lookup column.
        realism4_fiscal_adjustment_sample_share: Percent-of-sample series at the country's projected-adjustment bin, supplying the matched value column.

    Returns:
        The matched sample share as a float, or the workbook error code string when the category is not found.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_CATEGORIES.schema.validate(realism4_fiscal_adjustment_bin_categories)
    _realism4_projected_3yr_adjustment_sample_share_table_0 = lazy_table(((view(realism4_fiscal_adjustment_bin_categories, rows=data.VARIANT_AXIS_4.keys), view(realism4_fiscal_adjustment_sample_share, rows=data.VARIANT_AXIS_4.keys)),))
    try:
        return as_measure(xl_vlookup(realism4_projected_3yr_adjustment_category, _realism4_projected_3yr_adjustment_sample_share_table_0, 2, False))
    except XlError as error:
        return error.code

@publish(key=(), domain=None, cells=data.REALISM4_FISCAL_ADJUSTMENT_TOP_BIN_LABEL_CELLS)
def realism4_fiscal_adjustment_top_bin_label(*, translation_more_phrase: data.Series[str | None], start_debt_sustainability_analysis_m: int | str) -> str | int | float | bool:
    """Return the open-ended top-bin label for the fiscal-adjustment histogram from the translated workbook catalog.

    Select the top-bin text label used by the Realism 4 fiscal-adjustment distribution chart.

    Args:
        translation_more_phrase: Localized catalog phrase series over the language axis, containing optional English/French text entries and validated against the authored coordinate schema before lookup.
        start_debt_sustainability_analysis_m: Scalar coordinate offset or cell-reference value identifying the starting debt sustainability analysis position used when stepping through the language/phrase axis.

    Returns:
        Scalar top-bin label value, normally a string from the translation lookup, or an Excel error code string on failure; the declared union also permits integer, float, or boolean scalar workbook results.
    """
    data.TRANSLATION_MORE_PHRASE.schema.validate(translation_more_phrase)
    try:
        return as_measure(translation_more_phrase[axis_step(span(data.LANGUAGE_AXIS, 'English', 'French'), 'English', start_debt_sustainability_analysis_m)], 'str')
    except XlError as error:
        return error.code

@publish(data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.cells)
def realism4_fiscal_adjustment_sample_share(*, realism4_fiscal_adjustment_bin_frequencies: data.Series[float | str | None]) -> data.Realism4FiscalAdjustmentSampleShare:
    """Compute Realism 4 fiscal-adjustment sample shares from per-bin LIC sample frequencies.

    Derives the percentage share of the LIC sample falling in each 3-year fiscal-adjustment bin.

    Args:
        realism4_fiscal_adjustment_bin_frequencies: Keyword-only `data.Series[float | str | None]` indexed by catalog bin coordinates, giving the percent of the LIC sample in each 3-year fiscal-adjustment bin.

    Returns:
        Typed `data.Realism4FiscalAdjustmentSampleShare` result containing the computed percentage sample share for each fiscal-adjustment bin.
    """
    data.REALISM4_FISCAL_ADJUSTMENT_BIN_FREQUENCIES.schema.validate(realism4_fiscal_adjustment_bin_frequencies)
    _realism4_fiscal_adjustment_sample_share_table_0 = view(realism4_fiscal_adjustment_bin_frequencies, rows=data.VARIANT_AXIS_4.keys)
    def formula(variant: int) -> float | str | None:
        return as_measure(xl_mul(xl_div(realism4_fiscal_adjustment_bin_frequencies[variant], xl_sum(_realism4_fiscal_adjustment_sample_share_table_0)), 100))

    return data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.collect(evaluate(formula, data.REALISM4_FISCAL_ADJUSTMENT_SAMPLE_SHARE.required))

@publish(data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.schema, cells=data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.cells)
def realism4_fiscal_adjustment_cumulative_share(*, realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare) -> data.Realism4FiscalAdjustmentCumulativeShare:
    """Cumulate the Realism 4 fiscal-adjustment sample shares into a running distribution.

    Derive the cumulative share of the LIC sample up to each fiscal-adjustment bin from the per-bin Realism 4 sample shares.

    Args:
        realism4_fiscal_adjustment_sample_share: data.Realism4FiscalAdjustmentSampleShare series giving the per-bin share of the LIC sample at each fiscal-adjustment coordinate.

    Returns:
        data.Realism4FiscalAdjustmentCumulativeShare series: the cumulative percent of the LIC sample up to each fiscal-adjustment bin.
    """
    def formula(variant: int) -> float | str | None:
        if variant == 2:
            return as_measure(xl_add(realism4_fiscal_adjustment_sample_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))
        return as_measure(xl_add(realism4_fiscal_adjustment_cumulative_share[variant - 1], realism4_fiscal_adjustment_sample_share[variant]))

    realism4_fiscal_adjustment_cumulative_share = CoordinateReader('realism4_fiscal_adjustment_cumulative_share', data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required, formula)
    return data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.collect((coord, realism4_fiscal_adjustment_cumulative_share[coord]) for coord in data.REALISM4_FISCAL_ADJUSTMENT_CUMULATIVE_SHARE.required)

@publish(data.PROBABILITY_PV_DEBT_TO_GDP.schema, cells=data.PROBABILITY_PV_DEBT_TO_GDP.cells)
def probability_pv_debt_to_gdp(*, probability_borderline_bandwidth: float | str, chart_output_pv_debt_gdp_ratio: data.ChartOutputPvDebtGdpRatio) -> data.ProbabilityPvDebtToGdp:
    """Compute probability-approach PV of PPG external debt-to-GDP paths, including lower and upper borderline bands.

    Derive the probability PV debt-to-GDP series from the chart-output ratio while replacing band scenarios with threshold-scaled bandwidth offsets.

    Args:
        probability_borderline_bandwidth: Borderline bandwidth scalar or string expression; the lower and upper bands are formed as threshold times one minus or plus half this bandwidth.
        chart_output_pv_debt_gdp_ratio: Chart-output PV debt-to-GDP ratio series over catalog coordinates, supplying the baseline, historical, MX shock, threshold, and band values copied or adjusted by scenario.

    Returns:
        data.ProbabilityPvDebtToGdp series over the required catalog coordinates, containing the chart-output values for baseline, historical, MX shock, and threshold scenarios and bandwidth-derived lower and upper band values.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Lower Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_sub(1, xl_div(probability_borderline_bandwidth, 2))))
        elif scenario == 'Upper Band':
            return as_measure(xl_mul(probability_pv_debt_to_gdp['Threshold', time_period], xl_add(1, xl_div(probability_borderline_bandwidth, 2))))
        return as_measure(chart_output_pv_debt_gdp_ratio[scenario, time_period])

    probability_pv_debt_to_gdp = CoordinateReader('probability_pv_debt_to_gdp', data.PROBABILITY_PV_DEBT_TO_GDP.required, formula)
    return data.PROBABILITY_PV_DEBT_TO_GDP.collect((coord, probability_pv_debt_to_gdp[coord]) for coord in data.PROBABILITY_PV_DEBT_TO_GDP.required)

