@publish(data.PV_BASE_DISCOUNT_AMORTIZATION.schema, cells=data.PV_BASE_DISCOUNT_AMORTIZATION.cells)
def pv_base_discount_amortization(*, pv_base_multilaterals: data.Series[int | str | None], pv_base_block_grace: data.Series[float | str | None], pv_base_block_maturity: data.Series[float | str | None], pv_base_opening_percent_of_face: data.Series[int | str | None], pv_base_discount_repayment_schedule: data.Series[float | str | None], pv_base_constant_discount_schedule_period: int | str, pv_base_discount_schedule_period: data.Series[int | str | None], pv_base_block_index: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute the PV_Base discount-schedule amortization series per instrument.

    Derive each instrument's principal amortization from its grace, maturity, opening-face, and discount-repayment inputs so the PV_Base discount schedule can be assembled over catalog coordinates.

    Args:
        pv_base_multilaterals: data.Series[int | str | None] series over catalog coordinates flagging which instruments are treated as multilaterals in the PV_Base discount schedule.
        pv_base_block_grace: data.Series[float | str | None] series over catalog coordinates giving each instrument's grace period, in years or schedule periods, used to suppress amortization before the first repayment.
        pv_base_block_maturity: data.Series[float | str | None] series over catalog coordinates giving each instrument's maturity, in years or schedule periods, bounding the amortization window.
        pv_base_opening_percent_of_face: data.Series[int | str | None] series over catalog coordinates holding each instrument's opening percent of face, the base balance amortized across the repayment window.
        pv_base_discount_repayment_schedule: data.Series[float | str | None] series over catalog coordinates mapping each instrument and time period to its discount repayment schedule factor.
        pv_base_constant_discount_schedule_period: int | str scalar constant discount schedule period used to normalize the constant-schedule branch of the amortization formula.
        pv_base_discount_schedule_period: data.Series[int | str | None] series over catalog coordinates marking the discount schedule period for each instrument along the time axis.
        pv_base_block_index: data.Series[int | str | None] series over catalog coordinates giving each instrument's block index by time period, used to measure elapsed periods since the 2024 base year.

    Returns:
        data.Series[float | str | None] series over catalog coordinates holding the computed amortization amount per instrument and time period, passing through blanks or strings where the formula is undefined.
    """
    data.PV_BASE_OPENING_PERCENT_OF_FACE.schema.validate(pv_base_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IDA - regular' and time_period == 2024:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(pv_base_constant_discount_schedule_period, pv_base_constant_discount_schedule_period), pv_base_block_grace['IDA - regular'])) else (xl_mul(pv_base_opening_percent_of_face['IDA - regular'], pv_base_discount_repayment_schedule['IDA - regular', time_period]) if xl_bool(xl_le(xl_sub(pv_base_constant_discount_schedule_period, pv_base_constant_discount_schedule_period), pv_base_block_maturity['IDA - regular'])) else 0)))
        elif instrument == 'IDA - SML' and 2075 <= time_period <= 2076:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(None, pv_base_block_index['IDA - SML', 2024]), 1), pv_base_block_grace['IDA - SML'])) else (xl_div(pv_base_opening_percent_of_face['IDA - SML'], xl_sub(pv_base_block_maturity['IDA - SML'], pv_base_block_grace['IDA - SML'])) if xl_bool(xl_lt(xl_sub(xl_sub(None, pv_base_block_index['IDA - SML', 2024]), 1), pv_base_block_maturity['IDA - SML'])) else 0)))
        elif instrument == 'IDA NEW Regular' and 2056 <= time_period <= 2058:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(pv_base_block_index['IDA NEW Regular', time_period], pv_base_block_index['IDA NEW Regular', 2024]), pv_base_block_grace['IDA NEW Regular'])) else (xl_mul(pv_base_opening_percent_of_face['IDA NEW Regular'], None) if xl_bool(xl_le(xl_sub(pv_base_block_index['IDA NEW Regular', time_period], pv_base_block_index['IDA NEW Regular', 2024]), pv_base_block_maturity['IDA NEW Regular'])) else 0)))
        elif instrument == 'IDA NEW Blend floating' and time_period <= 2049:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_base_block_index['IDA NEW Blend floating', time_period], pv_base_block_index['IDA NEW Blend floating', 2024]), 1), pv_base_block_grace['IDA NEW Blend floating'])) else (xl_div(pv_base_opening_percent_of_face['IDA NEW Blend floating'], xl_sub(pv_base_block_maturity['IDA NEW Blend floating'], pv_base_block_grace['IDA NEW Blend floating'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_base_block_index['IDA NEW Blend floating', time_period], pv_base_block_index['IDA NEW Blend floating', 2024]), 1), pv_base_block_maturity['IDA NEW Blend floating'])) else 0)))
        elif instrument == 'IDA NEW Regular' and time_period <= 2055:
            return as_measure((0 if xl_bool(xl_lt(xl_sub(pv_base_block_index['IDA NEW Regular', time_period], pv_base_block_index['IDA NEW Regular', 2024]), pv_base_block_grace['IDA NEW Regular'])) else (xl_mul(pv_base_opening_percent_of_face['IDA NEW Regular'], pv_base_discount_repayment_schedule['IDA NEW Regular', time_period]) if xl_bool(xl_le(xl_sub(pv_base_block_index['IDA NEW Regular', time_period], pv_base_block_index['IDA NEW Regular', 2024]), pv_base_block_maturity['IDA NEW Regular'])) else 0)))
