@publish(data.PV_BASE_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_BASE_DISCOUNT_T_M_CONDITION.cells)
def pv_base_discount_t_m_condition(*, pv_base_constant_discount_schedule_period: int | str, pv_base_block_maturity: data.Series[float | str | None], pv_base_discount_schedule_period: data.Series[int | str | None], pv_base_block_index: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the per-instrument, per-time-period t-minus-maturity condition on the PV baseline discount schedule.

    Derive the discount-schedule cell value where the schedule's discount period exceeds the instrument's block maturity, and zero otherwise.

    Args:
        pv_base_constant_discount_schedule_period: Scalar constant discount-schedule period, expressed as an integer or string measure, subtracted uniformly from block maturity for the fixed-period instrument branch.
        pv_base_block_maturity: Typed series of block maturities keyed by instrument, treated as a named-axis tensor over catalog coordinates; blanks and string measures are preserved.
        pv_base_discount_schedule_period: Typed series of discount-schedule periods keyed by instrument and time period, used for the post-2024 IDA-regular branch and carried as a named-axis tensor over catalog coordinates.
        pv_base_block_index: Typed series of block indices keyed by instrument and time period, supplying the shifted reference value for the rolled-over IDA and MULTI instruments.

    Returns:
        A typed data.Series[int | str | None] over instrument and time-period coordinates holding the computed t-minus-maturity measure, with zero filled in where the condition fails and blank or string cells preserved as authored.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'IMF' and time_period == 2024:
            return as_measure((xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IMF']) if xl_bool(xl_gt(xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IMF']), 0)) else 0), 'int')
        elif instrument == 'IDA - regular' and time_period == 2024:
            return as_measure((xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IDA - regular']) if xl_bool(xl_gt(xl_sub(pv_base_constant_discount_schedule_period, pv_base_block_maturity['IDA - regular']), 0)) else 0), 'int')
