@publish(data.PV_BASE_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_BASE_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_base_output_stock_of_new_forex_debt_in_usd(*, pv_base_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_base_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the USD stock of new forex debt for each instrument and projection year.

    Builds the recursive debt-stock path by accumulating gross new forex borrowing and subtracting amortization from the prior period stock.

    Args:
        pv_base_output_new_forex_borrowing_gross_usd: Gross new forex borrowing in USD, as a named-axis series over instruments and time periods, used as the period addition to the debt stock and, for 2024, as the opening base.
        pv_base_output_amortization: Amortization in USD, as a named-axis series over instruments and time periods, subtracted from the prior stock plus new borrowing to yield the current stock.

    Returns:
        A data.Series[float | str | None] of the stock of new forex debt in USD over the instrument and time-period coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF' and time_period >= 2026:
            return as_measure(xl_sub(xl_add(pv_base_output_stock_of_new_forex_debt_in_usd['IMF', time_period - 1], pv_base_output_new_forex_borrowing_gross_usd['IMF', time_period]), pv_base_output_amortization['IMF', time_period]))
