@publish(data.PV_BASE_OUTPUT_PV_OF_DEBT.schema, cells=data.PV_BASE_OUTPUT_PV_OF_DEBT.cells)
def pv_base_output_pv_of_debt(*, pv_base_block_interest: data.Series[float | str | None], pv_base_block_discount: data.Series[float | str | None], pv_base_discount_pv_of_debt: data.Series[float | str | None], pv_base_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_base_output_total_debt_service_in_usd: data.Series[float | str | None], pv_base_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the baseline PV of debt by instrument and projection year.

    Derives the PV-of-debt output from interest, discount, borrowing, amortization, and debt-service inputs using authored coordinate identities.

    Args:
        pv_base_block_interest: data.Series[float | str | None] of interest-rate assumptions indexed by instrument and time period, used to choose between amortization and discounting update paths for selected instruments.
        pv_base_block_discount: data.Series[float | str | None] of discount-rate assumptions indexed by instrument and time period, used to grow the prior period PV of debt and to compute discounting adjustments.
        pv_base_discount_pv_of_debt: data.Series[float | str | None] of PV-of-debt discount factors indexed by instrument and time period, anchored at 2024 for capitalizing new foreign-currency borrowing.
        pv_base_output_new_forex_borrowing_gross_usd: data.Series[float | str | None] of gross new foreign-currency borrowing in USD indexed by instrument and time period, capitalized into PV terms and added to the rolling debt stock.
        pv_base_output_total_debt_service_in_usd: data.Series[float | str | None] of total debt service in USD indexed by instrument and time period, deducted from the rolling PV of debt in the recursion.
        pv_base_output_amortization: data.Series[float | str | None] of amortization amounts indexed by instrument and time period, used in the amortization-based alternative update path for selected instruments.

    Returns:
        A data.Series[float | str | None] of baseline PV of debt by instrument and time period, with year-specific seed values and recursive update identities preserving non-numeric or blank entries.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument in ('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend floating', 'IDA NEW 60-year credits') and time_period == 2024:
            return as_measure(xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_base_discount_pv_of_debt[instrument, time_period]), 100))
        elif instrument in ('IMF', 'IDA - regular', 'IDA - 50Y loans', 'IDA NEW 40-year credits', 'IDA NEW Regular', 'IDA NEW Blend floating', 'IDA NEW 60-year credits') and time_period == 2025:
            return as_measure((xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_base_discount_pv_of_debt[instrument, 2024]), 100) if xl_bool(xl_le(xl_sub(xl_mul(pv_base_output_pv_of_debt[instrument, time_period - 1], xl_add(1, pv_base_block_discount[instrument])), pv_base_output_total_debt_service_in_usd[instrument, time_period]), 0)) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt[instrument, time_period - 1], xl_add(1, pv_base_block_discount[instrument])), pv_base_output_total_debt_service_in_usd[instrument, time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_base_discount_pv_of_debt[instrument, 2024]), 100))))
        elif instrument == 'IMF' and time_period >= 2026:
            return as_measure((xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IMF', time_period], pv_base_discount_pv_of_debt['IMF', 2024]), 100) if xl_bool(xl_le(xl_sub(xl_mul(pv_base_output_pv_of_debt['IMF', time_period - 1], xl_add(1, pv_base_block_discount['IMF'])), pv_base_output_total_debt_service_in_usd['IMF', time_period]), 0)) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt['IMF', time_period - 1], xl_add(1, pv_base_block_discount['IMF'])), pv_base_output_total_debt_service_in_usd['IMF', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IMF', time_period], pv_base_discount_pv_of_debt['IMF', 2024]), 100))))
        elif instrument == 'IDA - regular' and time_period >= 2026:
            return as_measure((xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IDA - regular', time_period], pv_base_discount_pv_of_debt['IDA - regular', 2024]), 100) if xl_bool(xl_le(xl_sub(xl_mul(pv_base_output_pv_of_debt['IDA - regular', time_period - 1], xl_add(1, pv_base_block_discount['IDA - regular'])), pv_base_output_total_debt_service_in_usd['IDA - regular', time_period]), 0)) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt['IDA - regular', time_period - 1], xl_add(1, pv_base_block_discount['IDA - regular'])), pv_base_output_total_debt_service_in_usd['IDA - regular', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IDA - regular', time_period], pv_base_discount_pv_of_debt['IDA - regular', 2024]), 100))))
        elif instrument == 'IDA - 50Y loans' and time_period >= 2026:
            return as_measure((xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IDA - 50Y loans', time_period], pv_base_discount_pv_of_debt['IDA - 50Y loans', 2024]), 100) if xl_bool(xl_le(xl_sub(xl_mul(pv_base_output_pv_of_debt['IDA - 50Y loans', time_period - 1], xl_add(1, pv_base_block_discount['IDA - 50Y loans'])), pv_base_output_total_debt_service_in_usd['IDA - 50Y loans', time_period]), 0)) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt['IDA - 50Y loans', time_period - 1], xl_add(1, pv_base_block_discount['IDA - 50Y loans'])), pv_base_output_total_debt_service_in_usd['IDA - 50Y loans', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IDA - 50Y loans', time_period], pv_base_discount_pv_of_debt['IDA - 50Y loans', 2024]), 100))))
        elif instrument == 'IDA - SML' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_base_output_pv_of_debt['IDA - SML', time_period - 1], pv_base_output_amortization['IDA - SML', time_period]), pv_base_output_new_forex_borrowing_gross_usd['IDA - SML', time_period]) if xl_bool(xl_ge(pv_base_block_interest['IDA - SML'], pv_base_block_discount['IDA - SML'])) else xl_add(xl_sub(xl_mul(pv_base_output_pv_of_debt['IDA - SML', time_period - 1], xl_add(1, pv_base_block_discount['IDA - SML'])), pv_base_output_total_debt_service_in_usd['IDA - SML', time_period]), xl_div(xl_mul(pv_base_output_new_forex_borrowing_gross_usd['IDA - SML', time_period], pv_base_discount_pv_of_debt['IDA - SML', 2024]), 100))))
