@publish(data.PV_BASE_OUTPUT_INTEREST.schema, cells=data.PV_BASE_OUTPUT_INTEREST.cells)
def pv_base_output_interest(*, pv_base_block_interest: data.Series[float | str | None], pv_base_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute interest accrued on new foreign-currency debt by instrument.

    Derive PV base output interest by multiplying each instrument's interest rate by the prior period's new foreign-currency debt stock.

    Args:
        pv_base_block_interest: Named-axis series of per-instrument interest rates (or interest block values) over the instrument coordinate; may contain floats, strings, or nulls.
        pv_base_output_stock_of_new_forex_debt_in_usd: Named-axis series of the prior-period stock of new foreign-currency debt in USD, indexed by instrument and time period; may contain floats, strings, or nulls.

    Returns:
        data.Series of computed interest amounts per instrument and time period, aligned to the instrument and time-period coordinates; values may be floats, strings, or nulls.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'IMF':
            return as_measure(xl_mul(pv_base_block_interest['IMF'], pv_base_output_stock_of_new_forex_debt_in_usd['IMF', time_period - 1]))
        elif instrument == 'IDA - regular':
            return as_measure(xl_mul(pv_base_block_interest['IDA - regular'], pv_base_output_stock_of_new_forex_debt_in_usd['IDA - regular', time_period - 1]))
        elif instrument == 'IDA - 50Y loans':
            return as_measure(xl_mul(pv_base_block_interest['IDA - 50Y loans'], pv_base_output_stock_of_new_forex_debt_in_usd['IDA - 50Y loans', time_period - 1]))
