@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.cells)
def pv_base_add_cost_mkt_discount_t_m_condition(*, pv_base_add_cost_mkt_opening_stock_percent_of_face: int | str, pv_base_add_cost_mkt_shock_schedule_period: data.Series[int | str | None], pv_base_add_cost_mkt_maturity: data.Series[int | str | None], pv_base_add_cost_mkt_discount_t_g_0: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the t-m condition series for the PV base additional cost market discount schedule.

    Derive the per-instrument, per-period condition that subtracts maturity from the applicable opening stock, shock schedule, or discount term and floors non-positive results at zero.

    Args:
        pv_base_add_cost_mkt_opening_stock_percent_of_face: Opening stock as a percent of face, supplied as a scalar integer or string.
        pv_base_add_cost_mkt_shock_schedule_period: Shock schedule period values as a named-axis data.Series[int | str | None], used for projection years from 2025 onward.
        pv_base_add_cost_mkt_maturity: Maturity values as a named-axis data.Series[int | str | None], keyed by instrument and catalog coordinates for subtraction from the applicable source term.
        pv_base_add_cost_mkt_discount_t_g_0: Discount t_g_0 values as a named-axis data.Series[int | str | None], keyed by instrument and time period, with COM4 mapped to Eurobond and COM5 mapped to Commecial Bank.

    Returns:
        A named-axis data.Series[int | str | None] containing the t-m condition over catalog coordinates, one value per instrument and time period with non-positive differences floored to zero.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0 = {'COM4': 'Eurobond', 'COM5': 'Commecial Bank'}
        if instrument == 'Eurobond' and time_period == 2024:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and time_period == 2024:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and time_period == 2024:
            return as_measure((xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_opening_stock_percent_of_face, pv_base_add_cost_mkt_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'Eurobond' and time_period >= 2025:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank' and time_period >= 2025:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3' and time_period >= 2025:
            return as_measure((xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_shock_schedule_period[time_period], pv_base_add_cost_mkt_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM4']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM5']) if xl_bool(xl_gt(xl_sub(pv_base_add_cost_mkt_discount_t_g_0[INSTRUMENT_TO_PV_BASE_ADD_COST_MKT_DISCOUNT_T_G_0[instrument], time_period], pv_base_add_cost_mkt_maturity['COM5']), 0)) else 0), 'int')

    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_DISCOUNT_T_M_CONDITION.required))

@publish(data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.schema, cells=data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.cells)
def pv_base_add_cost_mkt_discount_post_maturity_cumulative(*, pv_base_add_cost_mkt_discount_t_m_condition: data.Series[int | str | None], pv_base_add_cost_mkt_output_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the post-maturity cumulative market-discount add-cost series per instrument.

    Resolves each instrument's post-maturity cumulative add-cost by indexing the cumulative output series with the per-instrument t−m condition.

    Args:
        pv_base_add_cost_mkt_discount_t_m_condition: Named-axis series of per-instrument post-maturity t−m conditions over catalog coordinates; an entry equal to 0 yields 0, otherwise its value indexes into that instrument's cumulative output table for the given time period.
        pv_base_add_cost_mkt_output_cumulative: Named-axis series of cumulative market-discount add-cost values over the time axis, sliced at 2024–2051 to act as the per-instrument lookup table for the condition-driven selection.

    Returns:
        data.Series[float | str | None] of post-maturity cumulative market-discount add-costs aligned to the five instruments (COM3, COM4, COM5, Commecial Bank, Eurobond) and the time period axis.
    """
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_0 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_1 = view(pv_base_add_cost_mkt_output_cumulative, rows=('Commecial Bank',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_2 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM3',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_3 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM4',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_4 = view(pv_base_add_cost_mkt_output_cumulative, rows=('COM5',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['Eurobond', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['Eurobond', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['Commecial Bank', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['Commecial Bank', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_1)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM3', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM3', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_2)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM4', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM4', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_3)))
        return as_measure((0 if xl_bool(xl_eq(pv_base_add_cost_mkt_discount_t_m_condition['COM5', time_period], 0)) else xl_choose_range(pv_base_add_cost_mkt_discount_t_m_condition['COM5', time_period], _pv_base_add_cost_mkt_discount_post_maturity_cumulative_table_4)))

    return data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_DISCOUNT_POST_MATURITY_CUMULATIVE.required))

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Return gross new forex borrowing (USD) by instrument for the PV base add-cost market output.

    Populate the market-output series for new forex borrowing (gross, USD) from external debt new disbursements across the five catalog instruments.

    Args:
        ext_debt_new_disbursements_external: Source series of external new debt disbursements over catalog instrument and time-period coordinates, providing the values used to populate gross new forex borrowing (USD) across COM3, COM4, COM5, Commecial Bank, and Eurobond.

    Returns:
        A data.Series[float | str | None] containing gross new forex borrowing (USD) aligned to the output catalog coordinates, with one series per instrument among COM3, COM4, COM5, Commecial Bank, and Eurobond.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required))

