@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd(*, pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_base_add_cost_mkt_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the stock of new forex debt in USD from gross new forex borrowing and amortization by instrument over time.

    Derive the internal stock path for new forex debt using the authored year-by-year roll-forward identities.

    Args:
        pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd: Gross new forex borrowing in USD as a named-axis series over instruments (COM3, COM4, COM5, Commercial Bank, Eurobond) and time periods.
        pv_base_add_cost_mkt_output_amortization: Amortization as a named-axis series over the same instruments and time periods.

    Returns:
        Named-axis series of the stock of new forex debt in USD over instruments and time periods, aligned to the coordinate series for this internal output.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['Eurobond', time_period]), pv_base_add_cost_mkt_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]), pv_base_add_cost_mkt_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM3', time_period]), pv_base_add_cost_mkt_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_base_add_cost_mkt_output_amortization['COM4', time_period]))
        elif instrument == 'COM5' and time_period == 2026:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd['COM5', time_period]), pv_base_add_cost_mkt_output_amortization['COM5', time_period]))
        elif time_period == 2024:
            return as_measure(xl_sub(None, pv_base_add_cost_mkt_output_amortization[instrument, time_period]))
        elif time_period == 2025:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd[instrument, time_period - 1], pv_base_add_cost_mkt_output_new_forex_borrowing_gross_usd[instrument, time_period]), pv_base_add_cost_mkt_output_amortization[instrument, time_period]))
        elif instrument == 'Eurobond' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2027:
            return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM4', time_period]))
        return as_measure(xl_sub(xl_add(pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], None), pv_base_add_cost_mkt_output_amortization['COM5', time_period]))

    pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd = CoordinateReader('pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd', data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required, formula)
    return data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.collect((coord, pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd[coord]) for coord in data.PV_BASE_ADD_COST_MKT_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required)

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST.cells)
def pv_base_add_cost_mkt_output_interest(*, pv_base_add_cost_mkt_discount_interest_rate: data.Series[float | str | None], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute per-instrument market interest on the stock of new foreign-currency debt by projection period.

    Multiply each instrument's discount interest rate by its prior-period stock of new foreign-currency debt to derive interest additions for the LIC-DSF output.

    Args:
        pv_base_add_cost_mkt_discount_interest_rate: Per-instrument discount interest rate series over catalog coordinates; supplies the rate applied to each instrument's prior-period new foreign-currency debt stock.
        pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd: Per-instrument stock of new foreign-currency debt in USD over catalog coordinates; provides the lagged balance on which interest is accrued.

    Returns:
        A data.Series[float | str | None] of computed interest amounts over the same instrument and time-period coordinates as the template output, preserving blank, string, and None values.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['Eurobond'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['Commecial Bank'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM3'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM4'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_base_add_cost_mkt_discount_interest_rate['COM5'], pv_base_add_cost_mkt_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1]))

    return data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_INTEREST.required))

@publish(data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION.schema, cells=data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION.cells)
def pv_base_add_cost_mkt_output_amortization(*, pv_base_add_cost_mkt_grace: data.Series[int | str | None], pv_base_add_cost_mkt_maturity: data.Series[int | str | None], pv_base_add_cost_mkt_discount_post_grace_cumulative: data.Series[float | str | None], pv_base_add_cost_mkt_discount_post_maturity_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute per-instrument amortization from cumulative discount stages and maturity/grace spans.

    Produce the internal amortization series consumed by the PV base add-cost market output calculation.

    Args:
        pv_base_add_cost_mkt_grace: Grace-period span per instrument and projection period, typed as a named-axis data.Series over catalog coordinates with integer, text, or missing values.
        pv_base_add_cost_mkt_maturity: Maturity span per instrument and projection period, typed as a named-axis data.Series over catalog coordinates with integer, text, or missing values.
        pv_base_add_cost_mkt_discount_post_grace_cumulative: Cumulative post-grace discount values per instrument and projection period, typed as a named-axis data.Series over catalog coordinates with float, text, or missing values.
        pv_base_add_cost_mkt_discount_post_maturity_cumulative: Cumulative post-maturity discount values per instrument and projection period, typed as a named-axis data.Series over catalog coordinates with float, text, or missing values.

    Returns:
        A named-axis data.Series[float | str | None] of amortization values per instrument and projection period, derived as the difference between cumulative post-grace and post-maturity discount values divided by the maturity less grace span.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['Eurobond', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['Eurobond', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['Eurobond'], pv_base_add_cost_mkt_grace['Eurobond'])))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['Commecial Bank', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['Commecial Bank', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['Commecial Bank'], pv_base_add_cost_mkt_grace['Commecial Bank'])))
        elif instrument == 'COM3':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM3', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM3', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM3'], pv_base_add_cost_mkt_grace['COM3'])))
        elif instrument == 'COM4':
            return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM4', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM4', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM4'], pv_base_add_cost_mkt_grace['COM4'])))
        return as_measure(xl_div(xl_sub(pv_base_add_cost_mkt_discount_post_grace_cumulative['COM5', time_period], pv_base_add_cost_mkt_discount_post_maturity_cumulative['COM5', time_period]), xl_sub(pv_base_add_cost_mkt_maturity['COM5'], pv_base_add_cost_mkt_grace['COM5'])))

    return data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION.collect(evaluate(formula, data.PV_BASE_ADD_COST_MKT_OUTPUT_AMORTIZATION.required))

@dataclass(frozen=True, slots=True)
class ScanPvLcNr1TermsFxPaGrowthResult:
    """Complete named results of one recurrence group evaluation."""
    pv_lc_nr1_terms_fx_pa_growth: data.Series[float | str | None]
    pv_lc_nr1_terms_fx_pa_growth_avg: float | str
    pv_lc_nr1_terms_fx_pa: data.Series[float | str | None]

def scan_pv_lc_nr1_terms_fx_pa_growth(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc: data.Series[float | str | None]) -> ScanPvLcNr1TermsFxPaGrowthResult:
    """Evaluate the recurrence group `pv_lc_nr1_terms_fx_pa_growth`, `pv_lc_nr1_terms_fx_pa_growth_avg`, `pv_lc_nr1_terms_fx_pa` and publish complete tensors."""
    def pv_lc_nr1_terms_fx_pa_growth_formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        return as_measure(xl_sub(xl_div(pv_lc_nr1_terms_fx_pa[instrument, holder, time_period], pv_lc_nr1_terms_fx_pa[instrument, holder, time_period - 1]), 1))

    pv_lc_nr1_terms_fx_pa_growth = CoordinateReader('pv_lc_nr1_terms_fx_pa_growth', data.PV_LC_NR1_TERMS_FX_PA_GROWTH.required, pv_lc_nr1_terms_fx_pa_growth_formula)
    def pv_lc_nr1_terms_fx_pa_growth_avg_formula() -> float | str:
        return as_measure(xl_average(view(pv_lc_nr1_terms_fx_pa_growth, cols={'INSTRUMENT': ('Bonds (1 to 3 years)-LC',), 'HOLDER': ('non-residents',), 'TIME_PERIOD': span(data.TIME_PERIOD_AXIS, 2040, 2044)})))

    pv_lc_nr1_terms_fx_pa_growth_avg = CoordinateReader('pv_lc_nr1_terms_fx_pa_growth_avg', Domain.product(), pv_lc_nr1_terms_fx_pa_growth_avg_formula)
    def pv_lc_nr1_terms_fx_pa_formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if time_period <= 2044:
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar_nc[time_period])
        return as_measure(xl_mul(pv_lc_nr1_terms_fx_pa[instrument, holder, time_period - 1], xl_add(1, pv_lc_nr1_terms_fx_pa_growth_avg[()])))

    pv_lc_nr1_terms_fx_pa = CoordinateReader('pv_lc_nr1_terms_fx_pa', data.PV_LC_NR1_TERMS_FX_PA.required, pv_lc_nr1_terms_fx_pa_formula)
    return ScanPvLcNr1TermsFxPaGrowthResult(
        pv_lc_nr1_terms_fx_pa_growth=data.PV_LC_NR1_TERMS_FX_PA_GROWTH.collect((coord, pv_lc_nr1_terms_fx_pa_growth[coord]) for coord in data.PV_LC_NR1_TERMS_FX_PA_GROWTH.required),
        pv_lc_nr1_terms_fx_pa_growth_avg=pv_lc_nr1_terms_fx_pa_growth_avg[()],
        pv_lc_nr1_terms_fx_pa=data.PV_LC_NR1_TERMS_FX_PA.collect((coord, pv_lc_nr1_terms_fx_pa[coord]) for coord in data.PV_LC_NR1_TERMS_FX_PA.required),
    )

@publish(data.PV_LC_NR1_TERMS_PROJECTION_YEAR.schema, cells=data.PV_LC_NR1_TERMS_PROJECTION_YEAR.cells)
def pv_lc_nr1_terms_projection_year(*, macro_debt_data: int | str) -> data.Series[int | str | None]:
    """Build the Projection year series for local-currency bonds (1 to 3 years) held by non-residents on the pv_lc.terms coordinate.

    Derive the projection-year labels recursively across time periods from a supplied macro-debt seed value.

    Args:
        macro_debt_data: Scalar seed (int or str) used as the 2024 projection year; later periods take the prior year plus one.

    Returns:
        data.Series[int | str | None]: Projection year values over the pv_lc.terms coordinate, with 2024 seeded from the scalar input and None where unavailable.
    """
    def formula(instrument: str, holder: str, time_period: int) -> int | str | None:
        if time_period == 2024:
            return as_measure(macro_debt_data, 'int')
        return as_measure(xl_add(pv_lc_nr1_terms_projection_year[instrument, holder, time_period - 1], 1), 'int')

    pv_lc_nr1_terms_projection_year = CoordinateReader('pv_lc_nr1_terms_projection_year', data.PV_LC_NR1_TERMS_PROJECTION_YEAR.required, formula)
    return data.PV_LC_NR1_TERMS_PROJECTION_YEAR.collect((coord, pv_lc_nr1_terms_projection_year[coord]) for coord in data.PV_LC_NR1_TERMS_PROJECTION_YEAR.required)

@publish(data.PV_LC_NR1_TERMS_FX_EOP.schema, cells=data.PV_LC_NR1_TERMS_FX_EOP.cells)
def pv_lc_nr1_terms_fx_eop(*, macro_debt_exchange_rate_national_currency_per_u_s_dollar: data.Series[float | str | None], pv_lc_nr1_terms_fx_pa_growth_avg: float | str) -> data.Series[float | str | None]:
    """Compute the end-of-period FX rate series for the PV LC NR1 terms block.

    Extrapolate the national-currency-per-U.S.-dollar exchange rate beyond 2044 using a constant growth average.

    Args:
        macro_debt_exchange_rate_national_currency_per_u_s_dollar: Time-indexed data.Series of national-currency-per-U.S.-dollar exchange rates, with float, str, or None values.
        pv_lc_nr1_terms_fx_pa_growth_avg: Scalar average growth rate (float or str) applied to compound the FX rate after 2044.

    Returns:
        data.Series[float | str | None] over catalog coordinates for instrument, holder, and time period, containing end-of-period FX rates.
    """
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if time_period <= 2044:
            return as_measure(macro_debt_exchange_rate_national_currency_per_u_s_dollar[time_period])
        return as_measure(xl_mul(pv_lc_nr1_terms_fx_eop[instrument, holder, time_period - 1], xl_add(1, pv_lc_nr1_terms_fx_pa_growth_avg)))

    pv_lc_nr1_terms_fx_eop = CoordinateReader('pv_lc_nr1_terms_fx_eop', data.PV_LC_NR1_TERMS_FX_EOP.required, formula)
    return data.PV_LC_NR1_TERMS_FX_EOP.collect((coord, pv_lc_nr1_terms_fx_eop[coord]) for coord in data.PV_LC_NR1_TERMS_FX_EOP.required)

@publish(data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY.schema, cells=data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY.cells)
def pv_lc_terms_interest_rate_local_currency(*, input5_internal_interest_rate_on_domestic_debt: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute local-currency interest-rate terms on PV_LC from domestic-debt rates.

    Maps internal interest-rate inputs on domestic debt to the PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3 instrument terms.

    Args:
        input5_internal_interest_rate_on_domestic_debt: Keyword-only data.Series[float | str | None] of internal interest rates on domestic debt, keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3, supplying the local-currency rate used to build the corresponding PV_LC terms.

    Returns:
        data.Series[float | str | None] keyed by INSTRUMENT across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3, containing the local-currency interest rate on PV_LC, with entries that may be numeric rates, text labels, or None.
    """
    def formula(instrument: str, holder: str, time_period: int) -> float | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC':
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (1 to 3 years)-LC', 'non-residents', time_period])
        elif instrument == 'Bonds (4 to 7 years)-LC':
            return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (4 to 7 years)-LC', 'non-residents', time_period])
        return as_measure(input5_internal_interest_rate_on_domestic_debt['Bonds (beyond 7 years)-LC', 'non-residents', time_period])

    return data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY.collect(evaluate(formula, data.PV_LC_TERMS_INTEREST_RATE_LOCAL_CURRENCY.required))

