@publish(data.PV_LC_OUTPUT_PROJECTION_YEAR.schema, cells=data.PV_LC_OUTPUT_PROJECTION_YEAR.cells)
def pv_lc_output_projection_year(*, pv_lc_nr1_terms_projection_year: data.Series[int | str | None], pv_lc_terms_projection_year: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the projection year for PV of local-currency debt output by instrument, holder, issuance year, and time period.

    Assign each local-currency bond cohort a projection-year index so its cash flows land on the correct DSA horizon year, propagating the prior year forward where later periods are missing.

    Args:
        pv_lc_nr1_terms_projection_year: Projection-year terms for local-currency bonds with 1 to 3 year maturities, as a data.Series of integer, text, or missing values keyed by instrument, holder, and issuance year.
        pv_lc_terms_projection_year: Projection-year terms for local-currency bonds with 4 to 7 year and beyond-7-year maturities, as a data.Series of integer, text, or missing values keyed by instrument, holder, and issuance year.

    Returns:
        A data.Series[int | str | None] giving the projection year on PV_LC, keyed by instrument across PV_LC_NR1, PV_LC_NR2, and PV_LC_NR3.
    """
    def formula(instrument: str, holder: str, issuance_year: int, time_period: int) -> int | str | None:
        if instrument == 'Bonds (1 to 3 years)-LC' and issuance_year == 2024 and time_period == 2024:
            return as_measure(pv_lc_nr1_terms_projection_year[instrument, holder, issuance_year], 'int')
        elif instrument in ('Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC') and issuance_year == 2024 and time_period == 2024:
            return as_measure(pv_lc_terms_projection_year[instrument, holder, issuance_year], 'int')
        elif instrument == 'Bonds (1 to 3 years)-LC' and issuance_year >= 2025 and time_period == 2024:
            return as_measure(pv_lc_nr1_terms_projection_year[instrument, holder, 2024], 'int')
        elif instrument in ('Bonds (4 to 7 years)-LC', 'Bonds (beyond 7 years)-LC') and issuance_year >= 2025 and time_period == 2024:
            return as_measure(pv_lc_terms_projection_year[instrument, holder, 2024], 'int')
