            return as_measure((0 if xl_bool(xl_gt(pv_lc_output_issuance_year[instrument, holder, 2024], pv_lc_output_projection_year[instrument, holder, 2024, time_period])) else (pv_lc_output_stock_of_debt_in_usd[instrument, holder, 2024, time_period] if xl_bool(xl_gt(xl_npv(pv_lc_output_discount[instrument, holder, 2024], view(pv_lc_output_total_debt_service_in_usd, rows={'ISSUANCE_YEAR': (2024,)}, cols={'INSTRUMENT': (instrument,), 'HOLDER': (holder,), 'TIME_PERIOD': span(data.TIME_PERIOD_AXIS, time_period + 1, 2051)})), pv_lc_output_stock_of_debt_in_usd[instrument, holder, 2024, time_period])) else xl_npv(pv_lc_output_discount[instrument, holder, 2024], view(pv_lc_output_total_debt_service_in_usd, rows={'ISSUANCE_YEAR': (2024,)}, cols={'INSTRUMENT': (instrument,), 'HOLDER': (holder,), 'TIME_PERIOD': span(data.TIME_PERIOD_AXIS, time_period + 1, 2051)})))))
