@publish(data.PV_RESFIN_PUB_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.schema, cells=data.PV_RESFIN_PUB_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.cells)
def pv_resfin_pub_output_total_debt_service_in_usd(*, pv_resfin_pub_output_interest: data.Series[float | str | None], pv_resfin_pub_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total public external debt service in USD by adding the interest and amortization series over matching instrument, scenario, and year coordinates.

    Derive the public residual-financing output series for total debt service (External PPG medium- and long-term) across all nine stress and tailored scenarios.

    Args:
        pv_resfin_pub_output_interest: Interest component of External PPG medium- and long-term debt service, as a data.Series over instrument, scenario, and time period; non-numeric or blank entries are carried through the sum.
        pv_resfin_pub_output_amortization: Amortization (principal repayment) component of External PPG medium- and long-term debt service, as a data.Series aligned to the same instrument, scenario, and year coordinates as the interest series.

    Returns:
        A data.Series[float | str | None] of total debt service in USD, retaining the input instrument, scenario, and year coordinates and preserving blanks or text where either component is non-numeric.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Key variables at historical average', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Key variables at historical average', time_period]))
        elif scenario == 'Bounds Test 1: Real GDP Growth Shock':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Bounds Test 1: Real GDP Growth Shock', time_period]))
        elif scenario == 'Bounds Test 2: Primary Balance Shock for Market Access Countries':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))
        elif scenario == 'Bounds Test 2: Primary Balance Shock for non-market access countries':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]))
        elif scenario == 'Bounds Test 5: Exchange Rate Shock':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Bounds Test 5: Exchange Rate Shock', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Bounds Test 6: Combined Shock for Market Access Countries', time_period]))
        elif scenario == 'Tailored Stress Test 1: Contingent Liability Shock':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Tailored Stress Test 1: Contingent Liability Shock', time_period]))
        elif scenario == 'CL1: Natural disaster':
            return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'CL1: Natural disaster', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'CL1: Natural disaster', time_period]))
        return as_measure(xl_add(pv_resfin_pub_output_interest['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period], pv_resfin_pub_output_amortization['External PPG medium and long-term', 'Tailored Stress Test 3. Commodity Price shock - Public', time_period]))

    return data.PV_RESFIN_PUB_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_RESFIN_PUB_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.required))

@publish(data.PV_RESFIN_PUB_OUTPUT_T_G_0.schema, cells=data.PV_RESFIN_PUB_OUTPUT_T_G_0.cells)
def pv_resfin_pub_output_t_g_0(*, pv_resfin_pub_opening_stock_period: int | str, pv_resfin_pub_discount_period: data.Series[int | str | None], pv_resfin_pub_assumptions_avg_grace_period: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Computes the non-negative t−g year index for residual public financing output, per instrument, scenario, and projection period.

    Maps each period to the elapsed post-grace year used downstream by the PV residual-financing engine.

    Args:
        pv_resfin_pub_opening_stock_period: Scalar opening-stock base period (int year or str label) anchoring the t−g calculation for the initial projection period 2024.
        pv_resfin_pub_discount_period: Named-axis data series of discount-period indices over instrument, scenario, and time-period coordinates; its 'External MLT debt' slice supplies the period value for years after 2024.
        pv_resfin_pub_assumptions_avg_grace_period: Named-axis data series of average grace periods over instrument/scenario/time-period coordinates, keyed by debt instrument ('Domestic MLT debt', 'External MLT debt'), subtracted from the period index.

    Returns:
        data.Series of period indices (int, with str/None passthrough) over instrument, scenario, and time-period coordinates: the period minus the instrument's average grace period when positive, otherwise 0.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD = {'External PPG medium and long-term': 'External MLT debt', 'Domestic medium and long-term': 'Domestic MLT debt'}
        if time_period == 2024:
            return as_measure((xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_assumptions_avg_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')

    return data.PV_RESFIN_PUB_OUTPUT_T_G_0.collect(evaluate(formula, data.PV_RESFIN_PUB_OUTPUT_T_G_0.required))

@publish(data.PV_RESFIN_PUB_OUTPUT_T_M_CONDITION.schema, cells=data.PV_RESFIN_PUB_OUTPUT_T_M_CONDITION.cells)
def pv_resfin_pub_output_t_m_condition(*, pv_resfin_pub_opening_stock_period: int | str, pv_resfin_pub_discount_period: data.Series[int | str | None], pv_resfin_pub_assumptions_avg_maturity_incl_grace_period: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Compute the public residual-financing t minus m condition over the instrument, scenario, and time-period coordinates.

    Derive the per-period maturity condition used by the public debt residual-financing calculation from opening stock, discount period, and average maturity assumptions.

    Args:
        pv_resfin_pub_opening_stock_period: Scalar opening-stock period (integer or string) supplying the base year for the 2024 maturity-condition branch.
        pv_resfin_pub_discount_period: Typed data series over catalog coordinates holding discount-period values (integer, string, or null) indexed by instrument, scenario, and time period.
        pv_resfin_pub_assumptions_avg_maturity_incl_grace_period: Typed data series over catalog coordinates holding average maturity including grace period (float, string, or null), mapped to the residual-financing instrument assumptions.

    Returns:
        Typed data series over catalog coordinates containing the t minus m condition per instrument, scenario, and time period as an integer, string, or null.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD = {'External PPG medium and long-term': 'External MLT debt', 'Domestic medium and long-term': 'Domestic MLT debt'}
        if time_period == 2024:
            return as_measure((xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_pub_opening_stock_period, pv_resfin_pub_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_pub_discount_period['External MLT debt', time_period], pv_resfin_pub_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_PUB_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')

    return data.PV_RESFIN_PUB_OUTPUT_T_M_CONDITION.collect(evaluate(formula, data.PV_RESFIN_PUB_OUTPUT_T_M_CONDITION.required))

@publish(key=(), domain=None, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_ADDITIONAL_BORROWING_COSTS_DOMESTIC_CELLS)
def pv_resfin_add_assumptions_additional_borrowing_costs_domestic(*, input6_standard_params_2: data.Series[float | str | None]) -> float | str:
    """Compute the domestic additional borrowing-cost assumption for PV residual financing.

    Evaluate the single-cell domestic additional borrowing-cost formula using authored coordinate identities.

    Args:
        input6_standard_params_2: Standard parameters series for Input 6, holding scalar and text values over catalog coordinates; the domestic additional borrowing-cost result is derived from its primary balance default coordinate.

    Returns:
        Resolved additional borrowing cost as a float, or a workbook error code string if evaluation fails.
    """
    try:
        return as_measure(input6_standard_params_2['b2_primary_balance', 'default'])
    except XlError as error:
        return error.code

