@publish(data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.schema, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.cells)
def pv_resfin_add_assumptions_avg_maturity_incl_grace_period(*, in7_resfin_dom_mlt_effective: data.Series[float | str | None], in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Assemble the average-maturity (including grace period) assumptions for domestic and external MLT debt into one instrument-keyed series.

    Lifts the two Input 7 residual-financing maturity assumptions onto the internal assumptions coordinate so downstream steps can look them up by instrument.

    Args:
        in7_resfin_dom_mlt_effective: Assumption series of average maturities (in years, including grace period) for Domestic MLT debt on the Input 7 residual-financing coordinate; values are rounded down to whole years before being emitted, while text and blank cells pass through unchanged.
        in7_resfin_ext_mlt_effective: Assumption series of average maturities (in years, including grace period) for External MLT debt on the Input 7 residual-financing coordinate; values are taken as authored, with text and blank cells preserved.

    Returns:
        Series of average maturities (in years, including grace period) keyed by instrument over the Domestic MLT debt and External MLT debt coordinates, retaining any string or blank entries from the source assumptions.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. maturity (incl. grace period)'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. maturity (incl. grace period)'], 0))

    return data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.collect(evaluate(formula, data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD.required))

@publish(data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD.schema, cells=data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD.cells)
def pv_resfin_add_assumptions_avg_grace_period(*, in7_resfin_dom_mlt_effective: data.Series[float | str | None], in7_resfin_ext_mlt_effective: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute average grace period assumptions for residual financing by MLT debt instrument.

    Populate the `pv_resfin` assumptions `Avg. grace period` series across domestic and external MLT debt instruments.

    Args:
        in7_resfin_dom_mlt_effective: Domestic MLT debt effective residual financing assumptions as a data.Series of float, str, or None values over catalog coordinates, including the `Avg. grace period` field.
        in7_resfin_ext_mlt_effective: External MLT debt effective residual financing assumptions as a data.Series of float, str, or None values over catalog coordinates, including the `Avg. grace period` field.

    Returns:
        data.Series[float | str | None] of average grace period values keyed by MLT debt instrument, with domestic values rounded down and external values passed through.
    """
    def formula(instrument: str) -> float | str | None:
        if instrument == 'External MLT debt':
            return as_measure(in7_resfin_ext_mlt_effective['Avg. grace period'])
        return as_measure(xl_rounddown(in7_resfin_dom_mlt_effective['Avg. grace period'], 0))

    return data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD.collect(evaluate(formula, data.PV_RESFIN_ADD_ASSUMPTIONS_AVG_GRACE_PERIOD.required))

@publish(data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX.schema, cells=data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX.cells)
def pv_resfin_add_projection_years_period_index(*, pv_resfin_add_opening_stock_period_seed: int | str) -> data.Series[int | str | None]:
    """Derive the projection-years period-index series for the PV_ResFin-add internal cost/market table.

    Builds the recursive period-index coordinate by seeding the opening-stock period and incrementing by one across the projection years.

    Args:
        pv_resfin_add_opening_stock_period_seed: Opening-stock period seed scalar (int or str) used as the base value for the period-index recursion.

    Returns:
        A data.Series[int | str | None] over the PV_ResFin-add projection-years period-index axis (period-index row 23, with calendar years on row 22), yielding the derived period-index values from the seed onward.
    """
    def formula(time_period: int) -> int | str | None:
        if time_period == 1:
            return as_measure(xl_add(pv_resfin_add_opening_stock_period_seed, 1), 'int')
        return as_measure(xl_add(pv_resfin_add_projection_years_period_index[time_period - 1], 1), 'int')

    pv_resfin_add_projection_years_period_index = CoordinateReader('pv_resfin_add_projection_years_period_index', data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX.required, formula)
    return data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX.collect((coord, pv_resfin_add_projection_years_period_index[coord]) for coord in data.PV_RESFIN_ADD_PROJECTION_YEARS_PERIOD_INDEX.required)

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW.cells)
def pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window(*, pv_resfin_add_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None], pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the stock of new external forex debt beyond the projection window under a market-access primary-balance shock.

    Rolls forward the external PPG medium- and long-term debt stock by subtracting beyond-window market-access amortization from the prior period's stock.

    Args:
        pv_resfin_add_output_stock_of_new_forex_debt_in_usd: Coordinate-indexed data.Series of the stock of new external PPG medium- and long-term forex debt in USD under the Bounds Test 2 primary-balance market-access shock, supplying the initial value used when the projection window boundary is crossed.
        pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window: Coordinate-indexed data.Series of market-access interest-cost amortization beyond the projection window for external PPG medium- and long-term debt, subtracted each period in the recursive stock identity.

    Returns:
        data.Series[float | str | None] indexed by instrument, scenario, and time period, giving the stock of new forex debt beyond the projection window; the first beyond-window period starts from the output stock plus 2023 and later periods roll forward by subtracting the amortization series.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if time_period == 26:
            return as_measure(xl_sub(xl_add(pv_resfin_add_output_stock_of_new_forex_debt_in_usd['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period + 2023], None), pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))
        return as_measure(xl_sub(xl_add(pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period - 1], None), pv_resfin_add_int_cost_mkt_amortization_beyond_projection_window['External PPG medium and long-term', 'Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))

    pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window = CoordinateReader('pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window', data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW.required, formula)
    return data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW.collect((coord, pv_resfin_add_int_cost_mkt_stock_of_new_forex_debt_beyond_projection_window[coord]) for coord in data.PV_RESFIN_ADD_INT_COST_MKT_STOCK_OF_NEW_FOREX_DEBT_BEYOND_PROJECTION_WINDOW.required)

