@publish(data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS.cells)
def pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years(*, pv_resfin_add_assumptions_deviation_in_pb_ppt: data.Series[float | str | None], pv_resfin_add_assumptions_additional_borrowing_costs_domestic: float | str) -> data.Series[float | str | None]:
    """Compute additional domestic interest-rate shock series from primary-balance deviations and domestic borrowing costs across stress scenarios.

    Supports the residual financing additional-cost calculation by translating primary-balance shock assumptions into annual domestic interest-rate shocks.

    Args:
        pv_resfin_add_assumptions_deviation_in_pb_ppt: Scenario- and time-period-indexed data.Series of primary-balance deviation assumptions in percentage points, used to scale the domestic borrowing-cost add-on; string or None overrides are preserved.
        pv_resfin_add_assumptions_additional_borrowing_costs_domestic: Scalar additional domestic borrowing cost for domestic medium- and long-term instruments, or a string override, divided by 10,000 before multiplying the relevant primary-balance deviation.

    Returns:
        data.Series of additional domestic interest-rate shock values over instrument (domestic medium and long-term), stress scenario (Bounds Test 2 primary-balance shocks and Bounds Test 6 combined shocks for market-access and non-market-access countries), and projection year, with float values and string or None overrides.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Bounds Test 2: Primary Balance Shock for Market Access Countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 2: Primary Balance Shock for Market Access Countries', time_period]))
        elif scenario == 'Bounds Test 2: Primary Balance Shock for non-market access countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 2: Primary Balance Shock for non-market access countries', time_period]))
        elif scenario == 'Bounds Test 6: Combined Shock for Market Access Countries':
            return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 6: Combined Shock for Market Access Countries', time_period]))
        return as_measure(xl_mul(xl_div(pv_resfin_add_assumptions_additional_borrowing_costs_domestic, 10000), pv_resfin_add_assumptions_deviation_in_pb_ppt['Bounds Test 6: Combined Shock for Non-Market Access Countries', time_period]))

    return data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_SHOCK_YEARS.required))

@publish(data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION.schema, cells=data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION.cells)
def pv_resfin_add_output_t_m_condition(*, pv_resfin_add_assumptions_avg_maturity_incl_grace_period: data.Series[float | str | None], pv_resfin_add_opening_stock_period_seed: int | str, pv_resfin_add_projection_years_period_index: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the time-to-maturity condition for residual financing add-on projections.

    Evaluates whether the elapsed time since the opening stock period exceeds each instrument's average maturity including grace period, producing a positive measure when debt remains outstanding.

    Args:
        pv_resfin_add_assumptions_avg_maturity_incl_grace_period: Named-axis data series of average maturity including grace period per instrument type (e.g., 'External MLT debt', 'Domestic MLT debt'), mapping float, string, or null values over catalog coordinates.
        pv_resfin_add_opening_stock_period_seed: Scalar seed for the opening stock period, an integer or string year such as 2024, serving as the base reference for maturity comparisons.
        pv_resfin_add_projection_years_period_index: Named-axis data series of projection-year period indices as integers or strings (e.g., years after 2024), possibly containing nulls, used to compute the condition for periods beyond the seed.

    Returns:
        A data series of integers, strings, or nulls over the instrument, scenario, and time-period grid, where each value is the positive difference between the period index (or opening stock seed) and the average maturity including grace period, or zero when that difference is non-positive.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD = {'External PPG medium and long-term': 'External MLT debt', 'Domestic medium and long-term': 'Domestic MLT debt'}
        if time_period == 2024:
            return as_measure((xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_add_opening_stock_period_seed, pv_resfin_add_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]) if xl_bool(xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period - 2024], pv_resfin_add_assumptions_avg_maturity_incl_grace_period[INSTRUMENT_TO_PV_RESFIN_ADD_ASSUMPTIONS_AVG_MATURITY_INCL_GRACE_PERIOD[instrument]]), 0)) else 0), 'int')

    return data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION.collect(evaluate(formula, data.PV_RESFIN_ADD_OUTPUT_T_M_CONDITION.required))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW.cells)
def pv_resfin_add_int_cost_mkt_t_m_condition_beyond_projection_window(*, pv_resfin_add_assumptions_avg_maturity_incl_grace_period: data.Series[float | str | None], pv_resfin_add_projection_years_period_index: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the market-term t-m condition marking projection years that fall beyond an instrument's average maturity.

    Derive, for each instrument, scenario, and projection year, how far the year index extends past the average maturity including grace period, floored at zero.

    Args:
        pv_resfin_add_assumptions_avg_maturity_incl_grace_period: Series of average maturities including grace period, aligned to the catalog coordinates; entries may be floats, blank or text placeholders.
        pv_resfin_add_projection_years_period_index: Series of projection-period year indices over the same coordinates, with entries as ints, blanks or text placeholders.

    Returns:
        Int-typed series giving the positive difference between the projection year index and the average maturity when that gap exceeds zero, and 0 otherwise, over the instrument, scenario, and time-period coordinates.
    """
    def formula(instrument: str, scenario: str, time_period: int) -> int | str | None:
        return as_measure((xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']) if xl_bool(xl_gt(xl_sub(pv_resfin_add_projection_years_period_index[time_period], pv_resfin_add_assumptions_avg_maturity_incl_grace_period['External MLT debt']), 0)) else 0), 'int')

    return data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_T_M_CONDITION_BEYOND_PROJECTION_WINDOW.required))

@publish(data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE.schema, cells=data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE.cells)
def pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_two_year_average(*, pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the two-year average additional domestic interest rate for market-access shock scenarios.

    Average the 2025 and 2026 additional domestic interest rate shock assumptions into a per-scenario two-year value.

    Args:
        pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years: Named-axis data.Series[float | str | None] of additional domestic interest rate shock-year assumptions over catalog coordinates (debt type, scenario, and TIME_PERIOD year); the function consumes the 'Domestic medium and long-term' 2025 and 2026 entries.

    Returns:
        Named-axis data.Series[float | str | None] of two-year averages (2025 and 2026) for each scenario; non-numeric or missing source values propagate as str or None.
    """
    def formula(scenario: str) -> float | str | None:
        return as_measure(xl_average(pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years['Domestic medium and long-term', scenario, 2025], pv_resfin_add_int_cost_mkt_additional_domestic_interest_rate_shock_years['Domestic medium and long-term', scenario, 2026]))

    return data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE.collect(evaluate(formula, data.PV_RESFIN_ADD_INT_COST_MKT_ADDITIONAL_DOMESTIC_INTEREST_RATE_TWO_YEAR_AVERAGE.required))

