@publish(data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.schema, cells=data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.cells)
def pv_baseline_com_discount_debt_stock(*, pv_baseline_com_opening_percent_of_face: data.Series[int | str | None], pv_baseline_com_discount_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the PV baseline commercial discount debt stock for each instrument and projection year.

    Rolls forward opening percent-of-face balances and prior-period debt stock by subtracting scheduled discount amortization across the projection horizon.

    Args:
        pv_baseline_com_opening_percent_of_face: A data.Series of opening debt stock as a percent of face value, keyed by instrument and time period.
        pv_baseline_com_discount_amortization: A data.Series of discount amortization amounts, keyed by instrument and time period, subtracted from the corresponding opening or prior-period stock.

    Returns:
        A data.Series of the resulting debt stock by instrument and time period, holding floats or string/None passthrough values.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_baseline_com_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Eurobond' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'Commecial Bank' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM3' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM4' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM4', time_period]))
        elif instrument == 'COM5' and time_period == 2024:
            return as_measure(xl_sub(pv_baseline_com_opening_percent_of_face[instrument], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'COM5' and time_period == 2025:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock[instrument, time_period - 1], pv_baseline_com_discount_amortization['COM5', time_period]))
        elif instrument == 'Eurobond' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Eurobond', time_period - 1], pv_baseline_com_discount_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['Commecial Bank', time_period - 1], pv_baseline_com_discount_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM3', time_period - 1], pv_baseline_com_discount_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2026:
            return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM4', time_period - 1], pv_baseline_com_discount_amortization['COM4', time_period]))
        return as_measure(xl_sub(pv_baseline_com_discount_debt_stock['COM5', time_period - 1], pv_baseline_com_discount_amortization['COM5', time_period]))

    pv_baseline_com_discount_debt_stock = CoordinateReader('pv_baseline_com_discount_debt_stock', data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required, formula)
    return data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.collect((coord, pv_baseline_com_discount_debt_stock[coord]) for coord in data.PV_BASELINE_COM_DISCOUNT_DEBT_STOCK.required)

@publish(data.PV_BASELINE_COM_DISCOUNT_INTEREST_RATE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_INTEREST_RATE.cells)
def pv_baseline_com_discount_interest_rate(*, input4_interest_rate: data.Input4InterestRate) -> data.Series[float | str | None]:
    """Compute the PV baseline commercial discount interest-rate series from Input 4 interest rates.

    Maps Input 4 interest-rate values by instrument onto the pv_baseline_com discount interest-rate coordinate.

    Args:
        input4_interest_rate: Input 4 interest-rate series indexed by instrument, providing the per-instrument rates for COM3, COM4, COM5, Commercial Bank, and Eurobond.

    Returns:
        A typed series of per-instrument discount/interest rates (float, str, or None) collected over the PV baseline commercial discount interest-rate coordinate.
    """
    data.INPUT4_INTEREST_RATE.schema.validate(input4_interest_rate)
    def formula(instrument: str) -> float | str | None:
        return as_measure(input4_interest_rate[instrument])

    return data.PV_BASELINE_COM_DISCOUNT_INTEREST_RATE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_INTEREST_RATE.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.schema, cells=data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.cells)
def pv_baseline_com_discount_amortization(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_grace: data.Series[int | str | None], pv_baseline_com_maturity: data.Series[int | str | None], pv_baseline_com_opening_percent_of_face: data.Series[int | str | None]) -> data.Series[float | str | None]:
    """Compute baseline commercial discount amortization.

    Derive per-instrument amortization from discount periods, grace, maturity, and opening percent of face.

    Args:
        pv_baseline_com_discount_period: Series over instrument and time-period coordinates holding discount-period values as int, string, or missing values.
        pv_baseline_com_grace: Series over instrument coordinates holding grace-period values as int, string, or missing values.
        pv_baseline_com_maturity: Series over instrument coordinates holding maturity values as int, string, or missing values.
        pv_baseline_com_opening_percent_of_face: Series over instrument coordinates holding opening percent of face values as int, string, or missing values.

    Returns:
        Amortization values as a data.Series[float | str | None] over instrument and time-period coordinates.
    """
    data.PV_BASELINE_COM_OPENING_PERCENT_OF_FACE.schema.validate(pv_baseline_com_opening_percent_of_face)
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_grace['Eurobond'])) else (xl_div(pv_baseline_com_opening_percent_of_face['Eurobond'], xl_sub(pv_baseline_com_maturity['Eurobond'], pv_baseline_com_grace['Eurobond'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_discount_period['Eurobond', 2024]), 1), pv_baseline_com_maturity['Eurobond'])) else 0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_grace['Commecial Bank'])) else (xl_div(pv_baseline_com_opening_percent_of_face['Commecial Bank'], xl_sub(pv_baseline_com_maturity['Commecial Bank'], pv_baseline_com_grace['Commecial Bank'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_discount_period['Commecial Bank', 2024]), 1), pv_baseline_com_maturity['Commecial Bank'])) else 0)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_grace['COM3'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM3'], xl_sub(pv_baseline_com_maturity['COM3'], pv_baseline_com_grace['COM3'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_discount_period['COM3', 2024]), 1), pv_baseline_com_maturity['COM3'])) else 0)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_grace['COM4'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM4'], xl_sub(pv_baseline_com_maturity['COM4'], pv_baseline_com_grace['COM4'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_discount_period['COM4', 2024]), 1), pv_baseline_com_maturity['COM4'])) else 0)))
        return as_measure((0 if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_grace['COM5'])) else (xl_div(pv_baseline_com_opening_percent_of_face['COM5'], xl_sub(pv_baseline_com_maturity['COM5'], pv_baseline_com_grace['COM5'])) if xl_bool(xl_lt(xl_sub(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_discount_period['COM5', 2024]), 1), pv_baseline_com_maturity['COM5'])) else 0)))

    return data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_AMORTIZATION.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.cells)
def pv_baseline_com_discount_discount_rate(*, input4_discount_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Assemble the per-instrument discount-rate series used on the `pv_baseline_com` terms sheet.

    Reindex the Input 4 discount-rate assumptions onto the COM3, COM4, COM5, Commercial Bank, and Eurobond instrument coordinates so downstream PV baseline logic can read one aligned series.

    Args:
        input4_discount_rate: Named-axis `data.Series` over the internal instrument coordinates (COM3, COM4, COM5, Commercial Bank, Eurobond) holding each instrument's discount rate as a float, a template string, or a blank `None`; values are read per instrument and passed through unchanged.

    Returns:
        `data.Series[float | str | None]` on the same instrument coordinates, carrying the lifted per-instrument discount rates for use by the baseline PV computation.
    """
    def formula(instrument: str) -> float | str | None:
        return as_measure(input4_discount_rate[instrument])

    return data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_DISCOUNT_RATE.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_INTEREST.schema, cells=data.PV_BASELINE_COM_DISCOUNT_INTEREST.cells)
def pv_baseline_com_discount_interest(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute baseline commercial discount interest for each instrument from prior-period debt stock and interest rates.

    Derive the discount-schedule interest series by applying instrument interest rates to the corresponding prior-period debt stock.

    Args:
        pv_baseline_com_discount_debt_stock: Debt-stock series by instrument and time period; each instrument’s prior-period value is multiplied by its corresponding interest rate.
        pv_baseline_com_discount_interest_rate: Interest-rate series by instrument; each rate is applied to the prior-period debt stock for COM3, COM4, COM5, Commecial Bank, and Eurobond.

    Returns:
        data.Series[float | str | None] containing the computed discount interest by instrument and time period, aligned to the output catalog coordinates.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Eurobond'], pv_baseline_com_discount_debt_stock['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['Commecial Bank'], pv_baseline_com_discount_debt_stock['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM3'], pv_baseline_com_discount_debt_stock['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM4'], pv_baseline_com_discount_debt_stock['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_baseline_com_discount_interest_rate['COM5'], pv_baseline_com_discount_debt_stock['COM5', time_period - 1]))

    return data.PV_BASELINE_COM_DISCOUNT_INTEREST.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_INTEREST.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.schema, cells=data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.cells)
def pv_baseline_com_discount_total_debt_service(*, pv_baseline_com_discount_amortization: data.Series[float | str | None], pv_baseline_com_discount_interest: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Sum amortization and interest into total debt service per instrument.

    Derive the baseline commercial discount-schedule total debt service series by adding, instrument by instrument, amortization to interest over the catalog's instrument and time-period coordinates.

    Args:
        pv_baseline_com_discount_amortization: Typed data series of amortization amounts, aligned to the commercial discount-schedule catalog axes and carrying float, string, or null leaves across the five instruments.
        pv_baseline_com_discount_interest: Typed data series of interest amounts on the same instrument and time-period coordinates, with float, string, or null leaves matching the amortization series.

    Returns:
        A typed data series of total debt service (amortization plus interest) on the commercial discount-schedule catalog coordinates, preserving the same instrument and time-period axes and the float, string, or null leaf type.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Eurobond', time_period], pv_baseline_com_discount_interest['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['Commecial Bank', time_period], pv_baseline_com_discount_interest['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM3', time_period], pv_baseline_com_discount_interest['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_baseline_com_discount_amortization['COM4', time_period], pv_baseline_com_discount_interest['COM4', time_period]))
        return as_measure(xl_add(pv_baseline_com_discount_amortization['COM5', time_period], pv_baseline_com_discount_interest['COM5', time_period]))

    return data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_TOTAL_DEBT_SERVICE.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.schema, cells=data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.cells)
def pv_baseline_com_discount_pv_of_debt(*, pv_baseline_com_discount_debt_stock: data.Series[float | str | None], pv_baseline_com_discount_interest_rate: data.Series[float | str | None], pv_baseline_com_discount_discount_rate: data.Series[float | str | None], pv_baseline_com_discount_total_debt_service: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Computes the present value of debt for the baseline commercial discount schedule.

    Used to determine the PV of debt under baseline assumptions for commercial debt instruments.

    Args:
        pv_baseline_com_discount_debt_stock: A data.Series of debt stock values for commercial instruments, indexed by instrument and time period.
        pv_baseline_com_discount_interest_rate: A data.Series of interest rates for commercial instruments, indexed by instrument and time period.
        pv_baseline_com_discount_discount_rate: A data.Series of discount rates for commercial instruments, indexed by instrument and time period.
        pv_baseline_com_discount_total_debt_service: A data.Series of total debt service values for commercial instruments, indexed by instrument and time period.

    Returns:
        A data.Series of present value of debt for commercial instruments, indexed by instrument and time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        return as_measure((pv_baseline_com_discount_debt_stock[instrument, time_period] if xl_bool(xl_ge(pv_baseline_com_discount_interest_rate[instrument], pv_baseline_com_discount_discount_rate[instrument])) else xl_npv(pv_baseline_com_discount_discount_rate[instrument], view(pv_baseline_com_discount_total_debt_service, rows=(instrument,), cols=span(data.TIME_PERIOD_AXIS, time_period + 1, 2063)))))

    return data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_PV_OF_DEBT.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_T_G_0.schema, cells=data.PV_BASELINE_COM_DISCOUNT_T_G_0.cells)
def pv_baseline_com_discount_t_g_0(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_grace: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the t-g>0 spread by subtracting each instrument's grace series from its discount-period series and clamping non-positive results to zero.

    Derive the effective discounting horizon remaining after grace per baseline commercial instrument, used as the discount t-g>0 flag/value input on pv_baseline_com.discount_schedule.

    Args:
        pv_baseline_com_discount_period: data.Series[int | str | None] of baseline commercial discount periods, indexed by instrument (COM3, COM4, COM5, Commecial Bank, Eurobond) and time period.
        pv_baseline_com_grace: data.Series[int | str | None] of baseline commercial grace values, indexed by the same instrument and time-period coordinates, subtracted from the discount periods.

    Returns:
        data.Series[int | str | None] over the instrument and time-period coordinates holding (discount period - grace) where that spread exceeds zero and 0 otherwise.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_grace['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_grace['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_grace['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_grace['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_grace['COM5']), 0)) else 0), 'int')

    return data.PV_BASELINE_COM_DISCOUNT_T_G_0.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_T_G_0.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_G_0.schema, cells=data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_G_0.cells)
def pv_baseline_com_discount_cumulative_selected_by_t_g_0(*, pv_baseline_com_discount_t_g_0: data.Series[int | str | None], pv_baseline_com_output_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Return the PV baseline commercial discount cumulative amounts selected by the t-g > 0 coordinate.

    Evaluate the authored formula that maps the t-g selector and cumulative output series into the selected cumulative discount series.

    Args:
        pv_baseline_com_discount_t_g_0: Keyword-only data.Series[int | str | None] over commercial instruments and time periods; a zero selector value yields 0, otherwise it points to the matching cumulative projection year.
        pv_baseline_com_output_cumulative: Keyword-only data.Series[float | str | None] over commercial instruments and projection years 2024–2051, supplying the cumulative output values selected by the first series.

    Returns:
        data.Series[float | str | None] over the instrument/time-period coordinates; zero where the selector is 0 and the selected cumulative output otherwise.
    """
