@publish(data.PV_BASELINE_COM_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_BASELINE_COM_DISCOUNT_T_M_CONDITION.cells)
def pv_baseline_com_discount_t_m_condition(*, pv_baseline_com_discount_period: data.Series[int | str | None], pv_baseline_com_maturity: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute per-instrument discount-period-minus-maturity offsets for the baseline commercial PV schedule.

    Feeds the t-minus-maturity condition used to align discount periods with maturities in the baseline commercial PV engine.

    Args:
        pv_baseline_com_discount_period: Named-axis data series of baseline commercial discount periods, one value per instrument and time period.
        pv_baseline_com_maturity: Named-axis data series of baseline commercial maturities, one value per instrument and time period.

    Returns:
        Named-axis data series giving, per instrument and time period, the discount period minus maturity when that difference is positive and zero otherwise.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Eurobond', time_period], pv_baseline_com_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['Commecial Bank', time_period], pv_baseline_com_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM3', time_period], pv_baseline_com_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_maturity['COM4']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM4', time_period], pv_baseline_com_maturity['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_maturity['COM5']) if xl_bool(xl_gt(xl_sub(pv_baseline_com_discount_period['COM5', time_period], pv_baseline_com_maturity['COM5']), 0)) else 0), 'int')

    return data.PV_BASELINE_COM_DISCOUNT_T_M_CONDITION.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_T_M_CONDITION.required))

@publish(data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.schema, cells=data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.cells)
def pv_baseline_com_discount_cumulative_selected_by_t_m_condition(*, pv_baseline_com_discount_t_m_condition: data.Series[int | str | None], pv_baseline_com_output_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Return per-instrument PV baseline commercial discount cumulative amounts selected by the t-m discount condition.

    Resolve each instrument's cumulative discount output for the 2024–2051 projection years by indexing it with the matching t-m condition value.

    Args:
        pv_baseline_com_discount_t_m_condition: Per-instrument, per-time-period t-m discount condition series (`data.Series[int | str | None]`) over the instrument and time-period catalog axes; a condition of 0 forces a zero result and any other value is used as the 1-based selector into the corresponding instrument's cumulative output row.
        pv_baseline_com_output_cumulative: Per-instrument, per-time-period cumulative discount output series (`data.Series[float | str | None]`) over the same instrument and time-period catalog axes, supplying the candidate values indexed for COM3, COM4, COM5, Commecial Bank, and Eurobond.

    Returns:
        A `data.Series[float | str | None]` over the instrument and time-period catalog axes giving, for each instrument and projection year, 0 where the t-m condition equals 0 and otherwise the cumulative discount value selected by that condition.
    """
    _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_0 = view(pv_baseline_com_output_cumulative, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_1 = view(pv_baseline_com_output_cumulative, rows=('Commecial Bank',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_2 = view(pv_baseline_com_output_cumulative, rows=('COM3',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_3 = view(pv_baseline_com_output_cumulative, rows=('COM4',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_4 = view(pv_baseline_com_output_cumulative, rows=('COM5',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_eq(pv_baseline_com_discount_t_m_condition['Eurobond', time_period], 0)) else xl_choose_range(pv_baseline_com_discount_t_m_condition['Eurobond', time_period], _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_eq(pv_baseline_com_discount_t_m_condition['Commecial Bank', time_period], 0)) else xl_choose_range(pv_baseline_com_discount_t_m_condition['Commecial Bank', time_period], _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_1)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_eq(pv_baseline_com_discount_t_m_condition['COM3', time_period], 0)) else xl_choose_range(pv_baseline_com_discount_t_m_condition['COM3', time_period], _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_2)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_eq(pv_baseline_com_discount_t_m_condition['COM4', time_period], 0)) else xl_choose_range(pv_baseline_com_discount_t_m_condition['COM4', time_period], _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_3)))
        return as_measure((0 if xl_bool(xl_eq(pv_baseline_com_discount_t_m_condition['COM5', time_period], 0)) else xl_choose_range(pv_baseline_com_discount_t_m_condition['COM5', time_period], _pv_baseline_com_discount_cumulative_selected_by_t_m_condition_table_4)))

    return data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.collect(evaluate(formula, data.PV_BASELINE_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.required))

@publish(data.PV_BASELINE_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_BASELINE_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_baseline_com_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the COM baseline output series for gross new forex borrowing in USD.

    Reindex external new disbursements onto the COM3, COM4, COM5, Commecial Bank, and Eurobond instrument coordinates.

    Args:
        ext_debt_new_disbursements_external: Named-axis data.Series[float | str | None] over instrument and time-period coordinates holding external new debt disbursements; supplies the values carried through for the Eurobond, Commecial Bank, COM3, COM4, and COM5 coordinates.

    Returns:
        data.Series[float | str | None] over the COM output's instrument and time-period coordinates giving gross new forex borrowing in USD, with each value copied from the matching coordinate of the input series.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_BASELINE_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_BASELINE_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required))

