@publish(data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.schema, cells=data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.cells)
def pv_stress_com_discount_t_m_condition(*, pv_stress_com_discount_period: data.Series[int | str | None], pv_stress_com_maturity: data.Series[int | str | None]) -> data.Series[int | str | None]:
    """Compute the per-instrument discount-period-minus-maturity condition from the pv_stress_com discount schedule.

    Lift the t-m condition used for the five commercial instruments in the PV stress discount schedule.

    Args:
        pv_stress_com_discount_period: A typed data.Series over catalog coordinates holding each instrument's discount period as int, str, or None.
        pv_stress_com_maturity: A typed data.Series over catalog coordinates holding each instrument's maturity as int, str, or None.

    Returns:
        A typed data.Series over catalog coordinates with the positive discount-period-minus-maturity for each instrument, or 0 when that difference is not positive.
    """
    def formula(instrument: str, time_period: int) -> int | str | None:
        if instrument == 'Eurobond':
            return as_measure((xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_maturity['Eurobond']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['Eurobond', time_period], pv_stress_com_maturity['Eurobond']), 0)) else 0), 'int')
        elif instrument == 'Commecial Bank':
            return as_measure((xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_maturity['Commecial Bank']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['Commecial Bank', time_period], pv_stress_com_maturity['Commecial Bank']), 0)) else 0), 'int')
        elif instrument == 'COM3':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_maturity['COM3']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM3', time_period], pv_stress_com_maturity['COM3']), 0)) else 0), 'int')
        elif instrument == 'COM4':
            return as_measure((xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_maturity['COM4']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM4', time_period], pv_stress_com_maturity['COM4']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_maturity['COM5']) if xl_bool(xl_gt(xl_sub(pv_stress_com_discount_period['COM5', time_period], pv_stress_com_maturity['COM5']), 0)) else 0), 'int')

    return data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_T_M_CONDITION.required))

@publish(data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.schema, cells=data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.cells)
def pv_stress_com_discount_cumulative_selected_by_t_m_condition(*, pv_stress_com_discount_t_m_condition: data.Series[int | str | None], pv_stress_com_output_cumulative: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Selects per-instrument cumulative PV-stress discount outputs across the time-period axis according to a t-m condition index.

    Resolves each instrument's cumulative discount value by applying the t-m condition as a lookup into the corresponding cumulative output series.

    Args:
        pv_stress_com_discount_t_m_condition: data.Series indexed by instrument and time-period coordinates whose integer/string entries act as the selection index into the cumulative output series, with 0 (or a None value) yielding a zero result.
        pv_stress_com_output_cumulative: data.Series of cumulative PV-stress discount outputs indexed by the same instrument and time-period coordinates, evaluated over the 2024-2051 time-period span to supply the values selected by the condition.

    Returns:
        data.Series of the selected cumulative discount outputs, indexed by instrument and time-period coordinates, carrying float values (or strings/None for unevaluated or empty cells).
    """
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0 = view(pv_stress_com_output_cumulative, rows=('Eurobond',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1 = view(pv_stress_com_output_cumulative, rows=('Commecial Bank',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2 = view(pv_stress_com_output_cumulative, rows=('COM3',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3 = view(pv_stress_com_output_cumulative, rows=('COM4',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4 = view(pv_stress_com_output_cumulative, rows=('COM5',), cols=span(data.TIME_PERIOD_AXIS, 2024, 2051))
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['Eurobond', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['Eurobond', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_0)))
        elif instrument == 'Commecial Bank':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['Commecial Bank', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_1)))
        elif instrument == 'COM3':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM3', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM3', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_2)))
        elif instrument == 'COM4':
            return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM4', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM4', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_3)))
        return as_measure((0 if xl_bool(xl_eq(pv_stress_com_discount_t_m_condition['COM5', time_period], 0)) else xl_choose_range(pv_stress_com_discount_t_m_condition['COM5', time_period], _pv_stress_com_discount_cumulative_selected_by_t_m_condition_table_4)))

    return data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.collect(evaluate(formula, data.PV_STRESS_COM_DISCOUNT_CUMULATIVE_SELECTED_BY_T_M_CONDITION.required))

@publish(data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.schema, cells=data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.cells)
def pv_stress_com_output_new_forex_borrowing_gross_usd(*, ext_debt_new_disbursements_external: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute new forex borrowing (gross, USD) for the PV Stress COM output as a named-axis series over instruments and time periods.

    Re-keys external new-disbursement amounts from the external debt source into the PV Stress COM output instrument set so gross USD forex borrowing can be read on the catalog coordinate grid.

    Args:
        ext_debt_new_disbursements_external: Named-axis data series of external debt new disbursements keyed by instrument and time period, supplying the per-instrument gross forex borrowing values (Eurobond, Commecial Bank, COM3, COM4, COM5) that are re-projected onto the PV Stress COM output coordinates.

    Returns:
        A data series of new forex borrowing (gross, USD) over the PV Stress COM output instrument and time-period coordinates, with values drawn from the corresponding external new-disbursement cells.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(ext_debt_new_disbursements_external['Eurobond', time_period])
        elif instrument == 'Commecial Bank':
            return as_measure(ext_debt_new_disbursements_external['Commecial Bank', time_period])
        elif instrument == 'COM3':
            return as_measure(ext_debt_new_disbursements_external['COM3', time_period])
        elif instrument == 'COM4':
            return as_measure(ext_debt_new_disbursements_external['COM4', time_period])
        return as_measure(ext_debt_new_disbursements_external['COM5', time_period])

    return data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_NEW_FOREX_BORROWING_GROSS_USD.required))

