@publish(data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.schema, cells=data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.cells)
def pv_stress_com_output_stock_of_new_forex_debt_in_usd(*, pv_stress_com_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_com_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the stock of new forex debt in USD for each instrument from prior stock, gross new borrowing, and amortization.

    Rolls forward per-instrument forex debt stocks across projection years in the PV stress COM output block.

    Args:
        pv_stress_com_output_new_forex_borrowing_gross_usd: Coordinate series of gross new forex borrowing in USD, indexed by instrument and time period.
        pv_stress_com_output_amortization: Coordinate series of forex debt amortization in USD, indexed by instrument and time period.

    Returns:
        Coordinate series of the outstanding stock of new forex debt in USD per instrument and time period, aligned to the block's required coordinates and carrying blanks where a period has no value.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]), pv_stress_com_output_amortization['COM4', time_period]))
        elif instrument == 'COM5' and 2026 <= time_period <= 2027:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]), pv_stress_com_output_amortization['COM5', time_period]))
        elif time_period == 2024:
            return as_measure(xl_sub(None, pv_stress_com_output_amortization[instrument, time_period]))
        elif time_period == 2025:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd[instrument, time_period - 1], pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]), pv_stress_com_output_amortization[instrument, time_period]))
        elif instrument == 'Eurobond' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1], None), pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1], None), pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1], None), pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4' and time_period >= 2028:
            return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1], None), pv_stress_com_output_amortization['COM4', time_period]))
        return as_measure(xl_sub(xl_add(pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1], None), pv_stress_com_output_amortization['COM5', time_period]))

    pv_stress_com_output_stock_of_new_forex_debt_in_usd = CoordinateReader('pv_stress_com_output_stock_of_new_forex_debt_in_usd', data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required, formula)
    return data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.collect((coord, pv_stress_com_output_stock_of_new_forex_debt_in_usd[coord]) for coord in data.PV_STRESS_COM_OUTPUT_STOCK_OF_NEW_FOREX_DEBT_IN_USD.required)

@publish(data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.schema, cells=data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.cells)
def pv_stress_com_output_pv_of_debt(*, pv_stress_com_discount_interest_rate: data.Series[float | str | None], pv_stress_com_discount_discount_rate: data.Series[float | str | None], pv_stress_com_discount_pv_of_debt: data.Series[float | str | None], pv_stress_com_output_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_com_output_total_debt_service_in_usd: data.Series[float | str | None], pv_stress_com_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute PV of debt for stress scenario commercial instruments.

    Roll forward the present value of debt using discount rates, amortization, new borrowing, and debt service to produce the stress-test PV series.

    Args:
        pv_stress_com_discount_interest_rate: Series of discount interest rates by instrument and time period.
        pv_stress_com_discount_discount_rate: Series of discount rates by instrument and time period.
        pv_stress_com_discount_pv_of_debt: Series of present value of debt from the discount step by instrument and time period.
        pv_stress_com_output_new_forex_borrowing_gross_usd: Series of new foreign-currency borrowing gross amounts in USD by instrument and time period.
        pv_stress_com_output_total_debt_service_in_usd: Series of total debt service in USD by instrument and time period.
        pv_stress_com_output_amortization: Series of amortization amounts by instrument and time period.

    Returns:
        A data.Series of float, str, or None values representing the present value of debt for stress scenario commercial instruments, keyed by instrument and time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], pv_stress_com_output_amortization['Eurobond', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Eurobond', time_period], pv_stress_com_discount_pv_of_debt['Eurobond', 2024]), 100))))
        elif instrument == 'Commecial Bank' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], pv_stress_com_output_amortization['Commecial Bank', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_discount_rate['Commecial Bank'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Commecial Bank'])), pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['Commecial Bank', time_period], pv_stress_com_discount_pv_of_debt['Commecial Bank', 2024]), 100))))
        elif instrument == 'COM3' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], pv_stress_com_output_amortization['COM3', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_discount_rate['COM3'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM3'])), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM3', time_period], pv_stress_com_discount_pv_of_debt['COM3', 2024]), 100))))
        elif instrument == 'COM4' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], pv_stress_com_output_amortization['COM4', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_discount_rate['COM4'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM4'])), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM4', time_period], pv_stress_com_discount_pv_of_debt['COM4', 2024]), 100))))
        elif instrument == 'COM5' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], pv_stress_com_output_amortization['COM5', time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_discount_discount_rate['COM5'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM5'])), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd['COM5', time_period], pv_stress_com_discount_pv_of_debt['COM5', 2024]), 100))))
        elif time_period == 2024:
            return as_measure((None if xl_bool(xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument])) else xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt[instrument, time_period]), 100)))
        elif time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt[instrument, time_period - 1], pv_stress_com_output_amortization[instrument, time_period]), pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period]) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate[instrument], pv_stress_com_discount_discount_rate[instrument])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt[instrument, time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate[instrument])), pv_stress_com_output_total_debt_service_in_usd[instrument, time_period]), xl_div(xl_mul(pv_stress_com_output_new_forex_borrowing_gross_usd[instrument, time_period], pv_stress_com_discount_pv_of_debt[instrument, 2024]), 100))))
        elif instrument == 'Eurobond' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], pv_stress_com_output_amortization['Eurobond', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_discount_discount_rate['Eurobond'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Eurobond', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Eurobond'])), pv_stress_com_output_total_debt_service_in_usd['Eurobond', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['Eurobond', 2024]), 100))))
        elif instrument == 'Commecial Bank' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], pv_stress_com_output_amortization['Commecial Bank', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_discount_discount_rate['Commecial Bank'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['Commecial Bank', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['Commecial Bank'])), pv_stress_com_output_total_debt_service_in_usd['Commecial Bank', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['Commecial Bank', 2024]), 100))))
        elif instrument == 'COM3' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], pv_stress_com_output_amortization['COM3', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_discount_discount_rate['COM3'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM3', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM3'])), pv_stress_com_output_total_debt_service_in_usd['COM3', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM3', 2024]), 100))))
        elif instrument == 'COM4' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], pv_stress_com_output_amortization['COM4', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_discount_discount_rate['COM4'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM4', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM4'])), pv_stress_com_output_total_debt_service_in_usd['COM4', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM4', 2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], pv_stress_com_output_amortization['COM5', time_period]), None) if xl_bool(xl_ge(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_discount_discount_rate['COM5'])) else xl_add(xl_sub(xl_mul(pv_stress_com_output_pv_of_debt['COM5', time_period - 1], xl_add(1, pv_stress_com_discount_discount_rate['COM5'])), pv_stress_com_output_total_debt_service_in_usd['COM5', time_period]), xl_div(xl_mul(None, pv_stress_com_discount_pv_of_debt['COM5', 2024]), 100))))

    pv_stress_com_output_pv_of_debt = CoordinateReader('pv_stress_com_output_pv_of_debt', data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.required, formula)
    return data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.collect((coord, pv_stress_com_output_pv_of_debt[coord]) for coord in data.PV_STRESS_COM_OUTPUT_PV_OF_DEBT.required)

@publish(data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.schema, cells=data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.cells)
def pv_stress_com_output_total_debt_service_in_usd(*, pv_stress_com_output_interest: data.Series[float | str | None], pv_stress_com_output_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total debt service in USD per instrument for the PV stress COM output.

    Combine interest and amortization series into the total debt service series by summing both components for each instrument and time period.

    Args:
        pv_stress_com_output_interest: Interest component series over the instruments COM3, COM4, COM5, Commecial Bank, and Eurobond, in USD.
        pv_stress_com_output_amortization: Amortization component series over the same instruments, in USD.

    Returns:
        A data series of total debt service in USD, indexed by instrument and time period.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_add(pv_stress_com_output_interest['Eurobond', time_period], pv_stress_com_output_amortization['Eurobond', time_period]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_add(pv_stress_com_output_interest['Commecial Bank', time_period], pv_stress_com_output_amortization['Commecial Bank', time_period]))
        elif instrument == 'COM3':
            return as_measure(xl_add(pv_stress_com_output_interest['COM3', time_period], pv_stress_com_output_amortization['COM3', time_period]))
        elif instrument == 'COM4':
            return as_measure(xl_add(pv_stress_com_output_interest['COM4', time_period], pv_stress_com_output_amortization['COM4', time_period]))
        return as_measure(xl_add(pv_stress_com_output_interest['COM5', time_period], pv_stress_com_output_amortization['COM5', time_period]))

    return data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_TOTAL_DEBT_SERVICE_IN_USD.required))

@publish(data.PV_STRESS_COM_OUTPUT_INTEREST.schema, cells=data.PV_STRESS_COM_OUTPUT_INTEREST.cells)
def pv_stress_com_output_interest(*, pv_stress_com_discount_interest_rate: data.Series[float | str | None], pv_stress_com_output_stock_of_new_forex_debt_in_usd: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute interest on new foreign-currency debt under the commercial PV stress output.

    Combine instrument-level discount interest rates with lagged new-forex-debt stocks to produce interest amounts.

    Args:
        pv_stress_com_discount_interest_rate: Instrument-level discount interest rate series over the PV stress catalog, covering COM3, COM4, COM5, Commecial Bank, and Eurobond; values may be float, str, or None.
        pv_stress_com_output_stock_of_new_forex_debt_in_usd: Instrument-level stock of new foreign-currency debt in USD, indexed by instrument and time period; values may be float, str, or None and are read at the prior period when forming interest.

    Returns:
        A data.Series[float | str | None] of instrument-level interest amounts aligned to the PV stress output catalog.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Eurobond'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['Eurobond', time_period - 1]))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['Commecial Bank'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['Commecial Bank', time_period - 1]))
        elif instrument == 'COM3':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM3'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM3', time_period - 1]))
        elif instrument == 'COM4':
            return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM4'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM4', time_period - 1]))
        return as_measure(xl_mul(pv_stress_com_discount_interest_rate['COM5'], pv_stress_com_output_stock_of_new_forex_debt_in_usd['COM5', time_period - 1]))

    return data.PV_STRESS_COM_OUTPUT_INTEREST.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_INTEREST.required))

@publish(data.PV_STRESS_COM_OUTPUT_AMORTIZATION.schema, cells=data.PV_STRESS_COM_OUTPUT_AMORTIZATION.cells)
def pv_stress_com_output_amortization(*, pv_stress_com_grace: data.Series[int | str | None], pv_stress_com_maturity: data.Series[int | str | None], pv_stress_com_discount_cumulative_selected_by_t_g_0: data.Series[float | str | None], pv_stress_com_discount_cumulative_selected_by_t_m_condition: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the PV-stress commercial-output amortization series from instrument grace, maturity, and cumulative discount selections.

    Supply the per-instrument, per-period amortization ratio consumed by the PV stress commercial output block.

    Args:
        pv_stress_com_grace: Named-axis data series over catalog instruments (COM3, COM4, COM5, Commercial Bank, Eurobond) holding each instrument's grace period as an integer, string, or null.
        pv_stress_com_maturity: Named-axis data series over the same instruments holding each instrument's maturity period as an integer, string, or null.
        pv_stress_com_discount_cumulative_selected_by_t_g_0: Named-axis data series over instruments and projection periods holding the cumulative discount factor selected under the t_g_0 condition as a float, string, or null.
        pv_stress_com_discount_cumulative_selected_by_t_m_condition: Named-axis data series over instruments and projection periods holding the cumulative discount factor selected under the t_m condition as a float, string, or null.

    Returns:
        A data series on instruments and projection periods containing the amortization ratio, formed as the difference between the two cumulative discount selections divided by maturity minus grace; entries are floats, strings, or nulls.
    """
    def formula(instrument: str, time_period: int) -> float | str | None:
        if instrument == 'Eurobond':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['Eurobond', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['Eurobond', time_period]), xl_sub(pv_stress_com_maturity['Eurobond'], pv_stress_com_grace['Eurobond'])))
        elif instrument == 'Commecial Bank':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['Commecial Bank', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['Commecial Bank', time_period]), xl_sub(pv_stress_com_maturity['Commecial Bank'], pv_stress_com_grace['Commecial Bank'])))
        elif instrument == 'COM3':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM3', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM3', time_period]), xl_sub(pv_stress_com_maturity['COM3'], pv_stress_com_grace['COM3'])))
        elif instrument == 'COM4':
            return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM4', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM4', time_period]), xl_sub(pv_stress_com_maturity['COM4'], pv_stress_com_grace['COM4'])))
        return as_measure(xl_div(xl_sub(pv_stress_com_discount_cumulative_selected_by_t_g_0['COM5', time_period], pv_stress_com_discount_cumulative_selected_by_t_m_condition['COM5', time_period]), xl_sub(pv_stress_com_maturity['COM5'], pv_stress_com_grace['COM5'])))

    return data.PV_STRESS_COM_OUTPUT_AMORTIZATION.collect(evaluate(formula, data.PV_STRESS_COM_OUTPUT_AMORTIZATION.required))

@publish(data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT.schema, cells=data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT.cells)
def pv_stress_average_interest_rate_new_debt(*, in7_resfin_ext_mlt_override: data.Series[float | str | None], c4_mkt_fin_average_residual_interest: float | str) -> data.Series[float | str | None]:
    """Compute the average interest rate on new debt for the PV Stress scenario set.

    Populate the PV Stress average-interest-rate-on-new-debt series across paste-block copies using the historical-average override or the market-financing residual rate.

    Args:
        in7_resfin_ext_mlt_override: Keyword-only data.Series[float | str | None] over catalog coordinates; supplies the 'Avg. nominal interest rate on new borrowing in USD' value for the historical-average scenario.
        c4_mkt_fin_average_residual_interest: Keyword-only scalar float or str; market-financing average residual interest rate used for all non-historical-average scenarios.

    Returns:
        data.Series[float | str | None] giving the average interest rate on new debt on PV Stress, keyed across paste-block copies and populated per scenario from either the override series or the scalar fallback.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. nominal interest rate on new borrowing in USD'])
        return as_measure(c4_mkt_fin_average_residual_interest)

    return data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT.collect(evaluate(formula, data.PV_STRESS_AVERAGE_INTEREST_RATE_NEW_DEBT.required))

@publish(data.PV_STRESS_USD_DISCOUNT_RATE.schema, cells=data.PV_STRESS_USD_DISCOUNT_RATE.cells)
def pv_stress_usd_discount_rate(*, in7_resfin_ext_mlt_override: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Resolve the PV Stress USD discount rate across scenario coordinates.

    Builds the USD discount-rate series used in PV Stress calculations, honoring the Input 7 residual-financing external-multiplier override for the historical-average case and reusing that value for other scenarios.

    Args:
        in7_resfin_ext_mlt_override: A named-axis data series of float, string, or null override values aligned to catalog coordinates, supplying the Input 7 residual-financing external-multiplier override used for the historical-average scenario.

    Returns:
        A named-axis data.Series[float | str | None] containing the USD discount rate on PV Stress, keyed across paste-block copies, with the historical-average value propagated to the remaining scenarios.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['USD Discount rate'])
        return as_measure(pv_stress_usd_discount_rate['Key variables at historical average'])

    pv_stress_usd_discount_rate = CoordinateReader('pv_stress_usd_discount_rate', data.PV_STRESS_USD_DISCOUNT_RATE.required, formula)
    return data.PV_STRESS_USD_DISCOUNT_RATE.collect((coord, pv_stress_usd_discount_rate[coord]) for coord in data.PV_STRESS_USD_DISCOUNT_RATE.required)

@publish(data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT.schema, cells=data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT.cells)
def pv_stress_average_maturity_of_new_debt(*, in7_resfin_ext_mlt_override: data.Series[float | str | None], c4_mkt_fin_average_residual_terms: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the average maturity of new debt on the PV Stress path, selecting the scenario-appropriate override.

    Resolve the average maturity of new debt used by the PV Stress calculation from the historical-average override or market-financing residual terms.

    Args:
        in7_resfin_ext_mlt_override: Keyword-only data.Series of float, str, or None containing external residual-financing maturity overrides across scenarios; the historical-average scenario reads its 'Avg. maturity (incl. grace period)' coordinate.
        c4_mkt_fin_average_residual_terms: Keyword-only data.Series of float, str, or None containing market-financing average residual-term maturities across scenarios; non-historical scenarios read its 'Maturity (rounded)' coordinate.

    Returns:
        data.Series of float, str, or None giving the average maturity of new debt on PV Stress, keyed across paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. maturity (incl. grace period)'])
        return as_measure(c4_mkt_fin_average_residual_terms['Maturity\n(rounded)'])

    return data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT.collect(evaluate(formula, data.PV_STRESS_AVERAGE_MATURITY_OF_NEW_DEBT.required))

@publish(data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT.schema, cells=data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT.cells)
def pv_stress_average_grace_period_new_debt(*, in7_resfin_ext_mlt_override: data.Series[float | str | None], c4_mkt_fin_average_residual_terms: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the PV Stress average grace period on new debt series from scenario-keyed input and residual-term series.

    Selects the historical-average or residual-term grace-period value per scenario to populate the PV Stress output.

    Args:
        in7_resfin_ext_mlt_override: Keyword-only data.Series[float | str | None] of Input 7 residual financing external multilateral overrides, whose average grace-period coordinate supplies the historical-average scenario value.
        c4_mkt_fin_average_residual_terms: Keyword-only data.Series[float | str | None] of C4 market-financing average residual terms, whose rounded grace-period coordinate supplies the non-historical scenario values.

    Returns:
        data.Series[float | str | None] containing the average grace period on new debt on PV Stress, keyed across paste-block copies.
    """
    def formula(scenario: str) -> float | str | None:
        if scenario == 'Key variables at historical average':
            return as_measure(in7_resfin_ext_mlt_override['Avg. grace period'])
        return as_measure(c4_mkt_fin_average_residual_terms['Grace\n(rounded)'])

    return data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT.collect(evaluate(formula, data.PV_STRESS_AVERAGE_GRACE_PERIOD_NEW_DEBT.required))

@publish(data.PV_STRESS_PV_OF_NEW_FOREX_DEBT.schema, cells=data.PV_STRESS_PV_OF_NEW_FOREX_DEBT.cells)
def pv_stress_pv_of_new_forex_debt(*, pv_stress_discount_pv_of_debt: data.Series[float | str | None], pv_stress_average_interest_rate_new_debt: data.Series[float | str | None], pv_stress_usd_discount_rate: data.Series[float | str | None], pv_stress_new_forex_borrowing_gross_usd: data.Series[float | str | None], pv_stress_total_debt_service: data.Series[float | str | None], pv_stress_amortization: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute the present value of new foreign-currency debt under PV Stress scenarios.

    Calculates the discounted present value of new forex borrowing for each scenario and projection year, applying concessional or non-concessional discounting rules based on the comparison of the average interest rate on new debt to the USD discount rate.

    Args:
        pv_stress_discount_pv_of_debt: A data.Series of discount rates (as percentages) applied to the present value of debt, used to discount new forex borrowing under non-concessional terms.
        pv_stress_average_interest_rate_new_debt: A data.Series of average interest rates on new external debt, used to determine whether new borrowing is concessional (interest rate below the USD discount rate).
        pv_stress_usd_discount_rate: A data.Series of USD discount rates used to discount future debt service and as a threshold for concessionality.
        pv_stress_new_forex_borrowing_gross_usd: A data.Series of gross new foreign-currency borrowing amounts (in USD) for each scenario and projection year.
        pv_stress_total_debt_service: A data.Series of total debt service (principal plus interest) for each scenario and projection year.
        pv_stress_amortization: A data.Series of amortization (principal repayments) for each scenario and projection year.

    Returns:
        A data.Series[float | str | None] containing the PV of new forex debt (in USD) for each scenario and time period, keyed across paste-block copies.
    """
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Market financing stress test / primary' and time_period == 2024:
            return as_measure((None if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary'])) else xl_div(xl_mul(None, pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario == 'Market financing stress test / primary' and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), pv_stress_new_forex_borrowing_gross_usd[scenario, time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2024:
            return as_measure((None if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_div(xl_mul(None, pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), None) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(None, pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario in ('Key variables at historical average', 'Tailored Stress Test 3. Commodity Price shock -External') and time_period == 2024:
            return as_measure((pv_stress_new_forex_borrowing_gross_usd[scenario, time_period] if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[time_period]), 100)))
        elif scenario in ('Key variables at historical average', 'Tailored Stress Test 3. Commodity Price shock -External') and time_period == 2025:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], pv_stress_amortization[scenario, time_period]), pv_stress_new_forex_borrowing_gross_usd[scenario, time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt[scenario, time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service[scenario, time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd[scenario, time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / primary' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], pv_stress_amortization['Market financing stress test / primary', time_period]), pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / primary', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / primary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and 2026 <= time_period <= 2027:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], pv_stress_amortization['Market financing stress test / secondary', time_period]), None) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]), xl_div(xl_mul(None, pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / primary' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], pv_stress_amortization['Market financing stress test / primary', time_period]), None) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Market financing stress test / primary'], pv_stress_usd_discount_rate['Market financing stress test / primary'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / primary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / primary', time_period]), xl_div(xl_mul(None, pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Market financing stress test / secondary' and time_period >= 2028:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], pv_stress_amortization['Market financing stress test / secondary', time_period]), pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / secondary', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Market financing stress test / secondary', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Market financing stress test / secondary', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Market financing stress test / secondary', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        elif scenario == 'Key variables at historical average' and time_period >= 2026:
            return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Key variables at historical average', time_period - 1], pv_stress_amortization['Key variables at historical average', time_period]), pv_stress_new_forex_borrowing_gross_usd['Key variables at historical average', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Key variables at historical average', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Key variables at historical average', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Key variables at historical average', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))
        return as_measure((xl_add(xl_sub(pv_stress_pv_of_new_forex_debt['Tailored Stress Test 3. Commodity Price shock -External', time_period - 1], pv_stress_amortization['Tailored Stress Test 3. Commodity Price shock -External', time_period]), pv_stress_new_forex_borrowing_gross_usd['Tailored Stress Test 3. Commodity Price shock -External', time_period]) if xl_bool(xl_ge(pv_stress_average_interest_rate_new_debt['Key variables at historical average'], pv_stress_usd_discount_rate['Key variables at historical average'])) else xl_add(xl_sub(xl_mul(pv_stress_pv_of_new_forex_debt['Tailored Stress Test 3. Commodity Price shock -External', time_period - 1], xl_add(1, pv_stress_usd_discount_rate['Key variables at historical average'])), pv_stress_total_debt_service['Tailored Stress Test 3. Commodity Price shock -External', time_period]), xl_div(xl_mul(pv_stress_new_forex_borrowing_gross_usd['Tailored Stress Test 3. Commodity Price shock -External', time_period], pv_stress_discount_pv_of_debt[2024]), 100))))

    pv_stress_pv_of_new_forex_debt = CoordinateReader('pv_stress_pv_of_new_forex_debt', data.PV_STRESS_PV_OF_NEW_FOREX_DEBT.required, formula)
    return data.PV_STRESS_PV_OF_NEW_FOREX_DEBT.collect((coord, pv_stress_pv_of_new_forex_debt[coord]) for coord in data.PV_STRESS_PV_OF_NEW_FOREX_DEBT.required)

@publish(data.PV_STRESS_TOTAL_DEBT_SERVICE.schema, cells=data.PV_STRESS_TOTAL_DEBT_SERVICE.cells)
def pv_stress_total_debt_service(*, pv_stress_interest: data.Series[float | str | None], pv_stress_amortization: data.Series[float | str | None], pv_stress_interest_scenario: data.Series[float | str | None]) -> data.Series[float | str | None]:
    """Compute total PV Stress debt service as interest plus amortization.

    Derive total debt service per scenario and year on the PV Stress sheet.

    Args:
        pv_stress_interest: Interest component of PV Stress debt service, keyed across paste-block copies; a data.Series of float, str, or None.
        pv_stress_amortization: Amortization component of PV Stress debt service, keyed across paste-block copies; a data.Series of float, str, or None.
        pv_stress_interest_scenario: Scenario-specific interest component of PV Stress debt service, keyed across paste-block copies; a data.Series of float, str, or None.

    Returns:
        Total debt service (in USD) on PV Stress, keyed across paste-block copies; a data.Series of float, str, or None.
    """
    data.PV_STRESS_INTEREST_SCENARIO.schema.validate(pv_stress_interest_scenario)
    def formula(scenario: str, time_period: int) -> float | str | None:
        if scenario == 'Market financing stress test / primary' and time_period == 2024:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        elif scenario == 'Market financing stress test / secondary' and time_period == 2024:
            return as_measure(xl_add(pv_stress_interest_scenario['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))
        elif scenario == 'Key variables at historical average' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Key variables at historical average', time_period], pv_stress_amortization['Key variables at historical average', time_period]))
        elif scenario == 'Tailored Stress Test 3. Commodity Price shock -External' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Tailored Stress Test 3. Commodity Price shock -External', time_period], pv_stress_amortization['Tailored Stress Test 3. Commodity Price shock -External', time_period]))
        elif scenario == 'Market financing stress test / primary' and time_period in (2025, 2026, 2027, 2028, 2029, 2030, 2031, 2032, 2033, 2034, 2035, 2036, 2037, 2038, 2039, 2040, 2041, 2042, 2043, 2044):
            return as_measure(xl_add(pv_stress_interest['Market financing stress test / primary', time_period], pv_stress_amortization['Market financing stress test / primary', time_period]))
        return as_measure(xl_add(pv_stress_interest['Market financing stress test / secondary', time_period], pv_stress_amortization['Market financing stress test / secondary', time_period]))

    return data.PV_STRESS_TOTAL_DEBT_SERVICE.collect(evaluate(formula, data.PV_STRESS_TOTAL_DEBT_SERVICE.required))

@publish(data.PV_STRESS_T_G_0.schema, cells=data.PV_STRESS_T_G_0.cells)
def pv_stress_t_g_0(*, pv_stress_calendar_period: data.Series[int | str | None], pv_stress_average_grace_period_new_debt: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Compute the non-negative difference between calendar period and average grace period for new debt on the PV Stress sheet.

    Produces a typed coordinate series encoding the t-g>0 condition across paste-block copies for PV stress-test scenario evaluation.

    Args:
        pv_stress_calendar_period: Typed data.Series[int | str | None] of calendar periods keyed by time period and scenario on the PV Stress sheet.
        pv_stress_average_grace_period_new_debt: Typed data.Series[float | str | None] of average grace periods for new debt keyed by scenario, used as the subtrahend in the t-g>0 comparison.

    Returns:
        A data.Series[int | str | None] of the non-negative difference between the calendar period and the average grace period for new debt, keyed across paste-block copies; zero when the difference is non-positive.
    """
    def formula(scenario: str, time_period: int) -> int | str | None:
        if scenario == 'Market financing stress test / primary':
            return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Market financing stress test / primary']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Market financing stress test / primary']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_grace_period_new_debt['Key variables at historical average']), 0)) else 0), 'int')

    return data.PV_STRESS_T_G_0.collect(evaluate(formula, data.PV_STRESS_T_G_0.required))

@publish(data.PV_STRESS_T_M_CONDITION.schema, cells=data.PV_STRESS_T_M_CONDITION.cells)
def pv_stress_t_m_condition(*, pv_stress_calendar_period: data.Series[int | str | None], pv_stress_average_maturity_of_new_debt: data.Series[float | str | None]) -> data.Series[int | str | None]:
    """Compute the PV Stress t-m condition series across paste-block copies.

    Derive the t-m condition from calendar-period and average-maturity-of-new-debt inputs on PV Stress.

    Args:
        pv_stress_calendar_period: Typed data.Series of int, str, or None calendar periods over catalog coordinates, supplying the time-period operand for the t-m condition.
        pv_stress_average_maturity_of_new_debt: Typed data.Series of float, str, or None average maturities of new debt over catalog coordinates, keyed by scenario for the t-m condition calculation.

    Returns:
        A data.Series[int | str | None] of computed t-m condition values indexed across paste-block copies.
    """
    def formula(scenario: str, time_period: int) -> int | str | None:
        if scenario == 'Market financing stress test / primary':
            return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Market financing stress test / primary']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Market financing stress test / primary']), 0)) else 0), 'int')
        return as_measure((xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']) if xl_bool(xl_gt(xl_sub(pv_stress_calendar_period[time_period], pv_stress_average_maturity_of_new_debt['Key variables at historical average']), 0)) else 0), 'int')

    return data.PV_STRESS_T_M_CONDITION.collect(evaluate(formula, data.PV_STRESS_T_M_CONDITION.required))
